window.__TOPIC_JS=window.__TOPIC_JS||{};window.__TOPIC_JS["自動詞・他動詞"]={
"_note": "02. 自動詞・他動詞 — mỗi mục một dòng. LEVEL: n5 → n1 = cấp độ JLPT từ sơ cấp (n5) đến cao cấp (n1). THỨ TỰ: các nhóm xếp n5, n4, n3, không trộn lẫn; trong mỗi nhóm giữ nguyên thứ tự gốc. ĐỊNH DẠNG MỖI TỪ: word, reading, pair (tuỳ chọn), level, meaning (tuỳ chọn), note (tuỳ chọn), example (tuỳ chọn), example_reading (tuỳ chọn), example_meaning (tuỳ chọn). TRƯỜNG antonym (tuỳ chọn): từ trái nghĩa, dạng \"từ（cách đọc）: nghĩa\", nhiều từ cách nhau bằng \" / \". TRƯỜNG antonym_hanviet (tuỳ chọn, đi kèm antonym): âm Hán Việt của từng từ trái nghĩa, viết thường như trường hanviet, cùng thứ tự và cách nhau bằng \" / \" (từ chỉ có kana, không có chữ Hán, để trống). SỐ LƯỢNG: n5 23, n4 46, n3 135; tổng 204 mục từ vựng + 5 mẫu ngữ pháp (pattern, usage, example, example_reading, example_meaning).",
"id": "2. 自動詞・他動詞",
"title": "自動詞・他動詞",
"icon": "🔄",
"category": "ref",
"vocab": [
{"word":"上がる・上げる","reading":"あがる・あげる","pair":[{"word":"上がる","reading":"あがる","meaning":"tăng lên, đi lên (tự nhiên) [自動詞]","notes":["「値段が上がる」: giá TỰ tăng lên, không nói rõ ai làm → dùng が."],"examples":[{"example":"値段が上がりました。","example_reading":"ねだんがあがりました。","example_meaning":"Giá đã tăng lên."},{"example":"テストの点数が上がりました。","example_reading":"てすとのてんすうがあがりました。","example_meaning":"Điểm bài kiểm tra đã tăng lên."}]},{"word":"上げる","reading":"あげる","meaning":"nâng lên, tăng (có tác động) [他動詞]","notes":["「値段を上げる」: CÓ người chủ động tăng giá → dùng を với tha động từ."],"examples":[{"example":"店員が値段を上げました。","example_reading":"てんいんがねだんをあげました。","example_meaning":"Nhân viên đã tăng giá lên."},{"example":"毎日勉強して、点数を上げました。","example_reading":"まいにちべんきょうして、てんすうをあげました。","example_meaning":"Tôi học mỗi ngày nên đã nâng được điểm số."}]}],"level":"n5"},
{"word":"閉まる・閉める","reading":"しまる・しめる","pair":[{"word":"閉まる","reading":"しまる","meaning":"đóng lại (tự nhiên) [自動詞]","notes":["Không rõ ai đóng, chỉ mô tả trạng thái cửa → ドアが閉まる.","Cửa sổ tự đóng lại → 窓が閉まる."],"examples":[{"example":"ドアが閉まりました。","example_reading":"どあがしまりました。","example_meaning":"Cửa đã đóng lại."},{"example":"雨が降り出したので、窓が閉まりました。","example_reading":"あめがふりだしたので、まどがしまりました。","example_meaning":"Trời bắt đầu mưa nên cửa sổ đã khép lại."},{"example":"夜十時に店が閉まります。","example_reading":"よるじゅうじにみせがしまります。","example_meaning":"Cửa hàng đóng cửa lúc 10 giờ tối."}]},{"word":"閉める","reading":"しめる","meaning":"đóng, khép lại (có tác động) [他動詞]","notes":["Rõ ràng chủ ngữ 私 chủ động đóng → ドアを閉める.","Có người chủ động đóng cửa sổ → 窓を閉める."],"examples":[{"example":"私がドアを閉めました。","example_reading":"わたしがどあをしめました。","example_meaning":"Tôi đã đóng cửa."},{"example":"母は窓を閉めて、エアコンをつけました。","example_reading":"はははまどをしめて、えあこんをつけました。","example_meaning":"Mẹ đã đóng cửa sổ và bật điều hòa."},{"example":"店員は夜十時に店を閉めます。","example_reading":"てんいんはよるじゅうじにみせをしめます。","example_meaning":"Nhân viên đóng cửa tiệm lúc 10 giờ tối."}]}],"level":"n5"},
{"word":"集まる・集める","reading":"あつまる・あつめる","pair":[{"word":"集まる","reading":"あつまる","meaning":"tụ tập lại [自動詞]","notes":["Học sinh tự đến tụ tập → 学生が集まる."],"examples":[{"example":"学生が教室に集まりました。","example_reading":"がくせいがきょうしつにあつまりました。","example_meaning":"Học sinh đã tụ tập ở lớp."},{"example":"駅前に大勢の人が集まっています。","example_reading":"えきまえにおおぜいのひとがあつまっています。","example_meaning":"Rất đông người đang tụ tập trước nhà ga."}]},{"word":"集める","reading":"あつめる","meaning":"tập hợp, thu thập [他動詞]","notes":["Giáo viên là người gọi tập hợp → 学生を集める."],"examples":[{"example":"先生が学生を教室に集めました。","example_reading":"せんせいががくせいをきょうしつにあつめました。","example_meaning":"Giáo viên đã tập hợp học sinh vào lớp."},{"example":"私は趣味で、古い切手を集めています。","example_reading":"わたしはしゅみで、ふるいきってをあつめています。","example_meaning":"Tôi sưu tầm tem cũ như một sở thích."}]}],"level":"n5"},
{"word":"決まる・決める","reading":"きまる・きめる","pair":[{"word":"決まる","reading":"きまる","meaning":"được quyết định, chốt lại [自動詞]","notes":["Không nhấn mạnh ai quyết định → 日にちが決まる."],"examples":[{"example":"旅行の日にちが決まりました。","example_reading":"りょこうのひにちがきまりました。","example_meaning":"Ngày đi du lịch đã được chốt."},{"example":"来週の会議の時間が決まりました。","example_reading":"らいしゅうのかいぎのじかんがきまりました。","example_meaning":"Giờ họp của tuần sau đã được chốt."}]},{"word":"決める","reading":"きめる","meaning":"quyết định [他動詞]","notes":["Nhấn mạnh chủ thể quyết định → 日にちを決める."],"examples":[{"example":"私たちは旅行の日にちを決めました。","example_reading":"わたしたちはりょこうのひにちをきめました。","example_meaning":"Chúng tôi đã quyết định ngày đi du lịch."},{"example":"みんなで相談して、会議の時間を決めました。","example_reading":"みんなでそうだんして、かいぎのじかんをきめました。","example_meaning":"Mọi người bàn bạc với nhau rồi quyết định giờ họp."}]}],"level":"n5"},
{"word":"止まる・止める","reading":"とまる・とめる","pair":[{"word":"止まる","reading":"とまる","meaning":"dừng lại (tự nhiên) [自動詞]","notes":["Tàu dừng do sự cố hay đến ga, không nói rõ ai làm → 電車が止まる.","Vật/người tự dừng lại → 車が止まる."],"examples":[{"example":"電車が止まりました。","example_reading":"でんしゃがとまりました。","example_meaning":"Tàu điện đã dừng lại."},{"example":"車が信号で止まりました。","example_reading":"くるまがしんごうでとまりました。","example_meaning":"Xe đã dừng lại ở đèn tín hiệu."},{"example":"急に音楽が止まって、みんなびっくりしました。","example_reading":"きゅうにおんがくがとまって、みんなびっくりしました。","example_meaning":"Nhạc đột nhiên dừng nên ai cũng giật mình."}]},{"word":"止める","reading":"とめる","meaning":"dừng, ngừng, làm dừng (có tác động) [他動詞]","notes":["Người lái chủ động dừng → 電車を止める.","Có người chủ động dừng lại → 車を止める."],"examples":[{"example":"運転手が電車を止めました。","example_reading":"うんてんしゅがでんしゃをとめました。","example_meaning":"Người lái tàu đã dừng tàu lại."},{"example":"運転手が車を止めました。","example_reading":"うんてんしゅがくるまをとめました。","example_meaning":"Tài xế đã dừng xe."},{"example":"うるさいので、音楽を止めました。","example_reading":"うるさいので、おんがくをとめました。","example_meaning":"Vì ồn quá nên tôi đã tắt nhạc."}]}],"level":"n5"},
{"word":"始まる・始める","reading":"はじまる・はじめる","pair":[{"word":"始まる","reading":"はじまる","meaning":"bắt đầu (tự nhiên) [自動詞]","notes":["Chỉ nói sự việc bắt đầu → 授業が始まる."],"examples":[{"example":"授業が始まりました。","example_reading":"じゅぎょうがはじまりました。","example_meaning":"Buổi học đã bắt đầu."},{"example":"映画は七時から始まります。","example_reading":"えいがはしちじからはじまります。","example_meaning":"Bộ phim bắt đầu từ 7 giờ."}]},{"word":"始める","reading":"はじめる","meaning":"bắt đầu (có tác động) [他動詞]","notes":["Giáo viên là người khởi động → 授業を始める."],"examples":[{"example":"先生が授業を始めました。","example_reading":"せんせいがじゅぎょうをはじめました。","example_meaning":"Giáo viên đã bắt đầu buổi học."},{"example":"来月から、新しい仕事を始めます。","example_reading":"らいげつから、あたらしいしごとをはじめます。","example_meaning":"Từ tháng sau, tôi sẽ bắt đầu công việc mới."}]}],"level":"n5"},
{"word":"開く・開ける","reading":"あく・あける","pair":[{"word":"開く","reading":"あく","meaning":"mở ra, bung ra (tự nhiên) [自動詞]","notes":["Cửa tự mở (cảm biến, gió...) → ドアが開く.","Không rõ ai mở, chỉ chú ý trạng thái cửa → 開く."],"examples":[{"example":"ドアが開きました。","example_reading":"どあがあきました。","example_meaning":"Cửa đã mở ra."},{"example":"店の前に大きなシャッターが開きました。","example_reading":"みせのまえにおおきなしゃったーがあきました。","example_meaning":"Cửa cuốn lớn trước cửa hàng đã mở ra."},{"example":"デパートは十時に開きます。","example_reading":"でぱーとはじゅうじにあきます。","example_meaning":"Trung tâm thương mại mở cửa lúc 10 giờ."}]},{"word":"開ける","reading":"あける","meaning":"mở ra, mở cửa (có tác động) [他動詞]","notes":["Đứa trẻ chủ động mở → ドアを開ける.","Có chủ thể chủ động mở cửa → 店を開ける."],"examples":[{"example":"子供がドアを開けました。","example_reading":"こどもがどあをあけました。","example_meaning":"Đứa trẻ đã mở cửa."},{"example":"彼は店を開けて、朝の準備を始めました。","example_reading":"かれはみせをあけて、あさのじゅんびをはじめました。","example_meaning":"Anh ấy mở cửa shop và bắt đầu chuẩn bị buổi sáng."},{"example":"暑いので、窓を開けてもいいですか。","example_reading":"あついので、まどをあけてもいいですか。","example_meaning":"Nóng quá, tôi mở cửa sổ được không?"}]}],"level":"n5"},
{"word":"続く・続ける","reading":"つづく・つづける","pair":[{"word":"続く","reading":"つづく","meaning":"tiếp tục (tự nhiên) [自動詞]","notes":["Mưa là hiện tượng tự nhiên → 雨が続く."],"examples":[{"example":"雨がまだ続いています。","example_reading":"あめがまだつづいています。","example_meaning":"Mưa vẫn còn tiếp tục."},{"example":"天気のいい日が、一週間続いています。","example_reading":"てんきのいいひが、いっしゅうかんつづいています。","example_meaning":"Những ngày thời tiết đẹp đã kéo dài cả tuần rồi."}]},{"word":"続ける","reading":"つづける","meaning":"tiếp tục (có ý chí) [他動詞]","notes":["Người có ý chí tiếp tục hành động → 勉強を続ける."],"examples":[{"example":"彼は勉強を続けました。","example_reading":"かれはべんきょうをつづけました。","example_meaning":"Anh ấy đã tiếp tục học."},{"example":"疲れていても、練習を続けました。","example_reading":"つかれていても、れんしゅうをつづけました。","example_meaning":"Dù mệt tôi vẫn tiếp tục luyện tập."}]}],"level":"n5"},
{"word":"並ぶ・並べる","reading":"ならぶ・ならべる","pair":[{"word":"並ぶ","reading":"ならぶ","meaning":"xếp thành hàng (tự nhiên) [自動詞]","notes":["Không rõ ai xếp, chỉ tả trạng thái → 本が並ぶ."],"examples":[{"example":"本が棚に並んでいます。","example_reading":"ほんがたなにならんでいます。","example_meaning":"Sách được xếp trên kệ."},{"example":"人気の店の前に、たくさんの人が並んでいます。","example_reading":"にんきのみせのまえに、たくさんのひとがならんでいます。","example_meaning":"Trước tiệm nổi tiếng có rất nhiều người đang xếp hàng."}]},{"word":"並べる","reading":"ならべる","meaning":"xếp, sắp hàng [他動詞]","notes":["私 là người chủ động sắp xếp → 本を並べる."],"examples":[{"example":"私は本を棚に並べました。","example_reading":"わたしはほんをたなにならべました。","example_meaning":"Tôi đã xếp sách lên kệ."},{"example":"テーブルの上に、お皿を並べました。","example_reading":"てーぶるのうえに、おさらをならべました。","example_meaning":"Tôi đã xếp đĩa lên bàn."}]}],"level":"n5"},
{"word":"出る・出す","reading":"でる・だす","pair":[{"word":"出る","reading":"でる","meaning":"ra, đi ra, ra khỏi (tự nhiên) [自動詞]","notes":["Chủ ngữ 彼 tự di chuyển ra khỏi phòng (động từ tự thân, は表移動) → 部屋から出る.","Chú ý đến hành động ra khỏi nơi chốn → 〜を出る."],"examples":[{"example":"彼は部屋から出ました。","example_reading":"かれはへやからでました。","example_meaning":"Anh ấy đã ra khỏi phòng."},{"example":"先生が教室を出ました。","example_reading":"せんせいがきょうしつをでました。","example_meaning":"Giáo viên đã rời khỏi phòng học."},{"example":"熱が出て、学校を休みました。","example_reading":"ねつがでて、がっこうをやすみました。","example_meaning":"Tôi bị sốt nên đã nghỉ học."}]},{"word":"出す","reading":"だす","meaning":"đưa ra, lấy ra (có tác động) [他動詞]","notes":["彼 tác động lên đối tượng 本 để lấy ra → 本を出す.","Có đối tượng bị tác động rõ ràng → お金を出す."],"examples":[{"example":"彼はかばんから本を出しました。","example_reading":"かれはかばんからほんをだしました。","example_meaning":"Anh ấy đã lấy sách ra khỏi cặp."},{"example":"彼は財布からお金を出しました。","example_reading":"かれはさいふからおかねをだしました。","example_meaning":"Anh ấy đã lấy tiền ra khỏi ví."},{"example":"手紙を出しに、郵便局へ行きます。","example_reading":"てがみをだしに、ゆうびんきょくへいきます。","example_meaning":"Tôi đến bưu điện để gửi thư."}]}],"level":"n5"},
{"word":"起きる・起こす","reading":"おきる・おこす","pair":[{"word":"起きる","reading":"おきる","meaning":"thức dậy, xảy ra (tự nhiên) [自動詞]","notes":["Tai nạn tự xảy ra, không chỉ rõ nguyên nhân chủ động → 事故が起きる.","Chủ thể tự thức dậy → 起きる."],"examples":[{"example":"夜中に事故が起きました。","example_reading":"よなかにじこがおきました。","example_meaning":"Tai nạn đã xảy ra lúc nửa đêm."},{"example":"朝、目が覚めて起きました。","example_reading":"あさ、めがさめておきました。","example_meaning":"Sáng nay tôi thức dậy."},{"example":"朝、地震が起きて、とても驚きました。","example_reading":"あさ、じしんがおきて、とてもおどろきました。","example_meaning":"Buổi sáng xảy ra động đất, tôi đã rất giật mình."}]},{"word":"起こす","reading":"おこす","meaning":"đánh thức, gây ra (có tác động) [他動詞]","notes":["Nhấn mạnh nguyên nhân trực tiếp gây ra → 事故を起こす.","Có người chủ động đánh thức ai → 私を起こす."],"examples":[{"example":"居眠り運転が事故を起こしました。","example_reading":"いねむりうんてんがじこをおこしました。","example_meaning":"Lái xe ngủ gật đã gây ra tai nạn."},{"example":"母は私を起こしました。","example_reading":"はははわたしをおこしました。","example_meaning":"Mẹ đã đánh thức tôi."},{"example":"明日は早いので、六時に起こしてください。","example_reading":"あしたははやいので、ろくじにおこしてください。","example_meaning":"Mai phải dậy sớm nên hãy đánh thức tôi lúc 6 giờ."}]}],"level":"n5"},
{"word":"落ちる・落とす","reading":"おちる・おとす","pair":[{"word":"落ちる","reading":"おちる","meaning":"rơi xuống, ngã xuống (tự nhiên) [自動詞]","notes":["Không rõ nguyên nhân, sách tự rơi → 本が落ちる.","Quả táo rơi tự nhiên → りんごが落ちる."],"examples":[{"example":"本が棚から落ちました。","example_reading":"ほんがたなからおちました。","example_meaning":"Sách đã rơi khỏi kệ."},{"example":"りんごが木から落ちました。","example_reading":"りんごがきからおちました。","example_meaning":"Quả táo đã rơi xuống từ cây."},{"example":"机の上から、ペンが落ちました。","example_reading":"つくえのうえから、ぺんがおちました。","example_meaning":"Cây bút rơi từ trên bàn xuống."}]},{"word":"落とす","reading":"おとす","meaning":"làm rơi, để rơi (có tác động) [他動詞]","notes":["Con mèo là tác nhân trực tiếp → 本を落とす.","Có người chủ động làm rơi → コップを落とす."],"examples":[{"example":"猫が本を落としました。","example_reading":"ねこがほんをおとしました。","example_meaning":"Con mèo đã làm rơi cuốn sách."},{"example":"子どもがコップを落としました。","example_reading":"こどもがこっぷをおとしました。","example_meaning":"Đứa trẻ đã làm rơi chiếc cốc."},{"example":"駅で、財布を落としてしまいました。","example_reading":"えきで、さいふをおとしてしまいました。","example_meaning":"Tôi lỡ đánh rơi ví ở nhà ga mất rồi."}]}],"level":"n5"},
{"word":"切れる・切る","reading":"きれる・きる","pair":[{"word":"切れる","reading":"きれる","meaning":"đứt, hết, rời ra (tự nhiên) [自動詞]","notes":["Pin tự hết theo thời gian sử dụng → 電池が切れる.","Dây tự đứt → 糸が切れる."],"examples":[{"example":"電池が切れました。","example_reading":"でんちがきれました。","example_meaning":"Pin đã hết."},{"example":"糸が切れました。","example_reading":"いとがきれました。","example_meaning":"Dây chỉ đã đứt."},{"example":"話している途中で、電話が切れました。","example_reading":"はなしているとちゅうで、でんわがきれました。","example_meaning":"Đang nói chuyện giữa chừng thì cuộc gọi bị ngắt."}]},{"word":"切る","reading":"きる","meaning":"cắt, ngắt (có tác động) [他動詞]","notes":["彼 chủ động dùng kéo cắt → ひもを切る.","Có người chủ động cắt → 紙を切る."],"examples":[{"example":"彼はひもを切りました。","example_reading":"かれはひもをきりました。","example_meaning":"Anh ấy đã cắt sợi dây."},{"example":"私は紙を切りました。","example_reading":"わたしはかみをきりました。","example_meaning":"Tôi đã cắt giấy."},{"example":"果物をナイフで小さく切りました。","example_reading":"くだものをないふでちいさくきりました。","example_meaning":"Tôi dùng dao cắt trái cây thành miếng nhỏ."}]}],"level":"n5"},
{"word":"つく・つける","reading":"つく・つける","pair":[{"word":"つく","reading":"つく","meaning":"sáng lên, bật lên (tự nhiên) [自動詞]","notes":["Ánh đèn tự sáng lên → 電気がつく."],"examples":[{"example":"電気がつきました。","example_reading":"でんきがつきました。","example_meaning":"Đèn đã sáng lên."},{"example":"暗くなると、街の明かりがつきます。","example_reading":"くらくなると、まちのあかりがつきます。","example_meaning":"Khi trời tối, đèn đường phố sẽ sáng lên."}]},{"word":"つける","reading":"つける","meaning":"bật, gắn, đính (có tác động) [他動詞]","notes":["Rõ ràng có người bật → 電気をつける."],"examples":[{"example":"私は電気をつけました。","example_reading":"わたしはでんきをつけました。","example_meaning":"Tôi đã bật đèn."},{"example":"暑いので、エアコンをつけてもいいですか。","example_reading":"あついので、えあこんをつけてもいいですか。","example_meaning":"Nóng quá, tôi bật điều hòa được không?"}]}],"level":"n5"},
{"word":"消える・消す","reading":"きえる・けす","pair":[{"word":"消える","reading":"きえる","meaning":"mất đi, tắt đi (tự nhiên) [自動詞]","notes":["Đèn tự tắt → 電気が消える."],"examples":[{"example":"電気が消えました。","example_reading":"でんきがきえました。","example_meaning":"Đèn đã tắt mất."},{"example":"ろうそくの火が、風で消えました。","example_reading":"ろうそくのひが、かぜできえました。","example_meaning":"Ngọn nến bị gió thổi tắt."}]},{"word":"消す","reading":"けす","meaning":"tắt, xóa, xua đi (có tác động) [他動詞]","notes":["Có người chủ động tắt đèn → 電気を消す."],"examples":[{"example":"彼は電気を消しました。","example_reading":"かれはでんきをけしました。","example_meaning":"Anh ấy đã tắt đèn."},{"example":"寝る前に、テレビを消してください。","example_reading":"ねるまえに、てれびをけしてください。","example_meaning":"Trước khi ngủ hãy tắt tivi đi."}]}],"level":"n5"},
{"word":"入る・入れる","reading":"はいる・いれる","pair":[{"word":"入る","reading":"はいる","meaning":"đi vào, vào trong (tự nhiên) [自動詞]","notes":["Động tác tự nhiên đi vào/được bao bọc → 〜に入る."],"examples":[{"example":"雨が少しずつ部屋に入ってきました。","example_reading":"あめがすこしずつへやにはいってきました。","example_meaning":"Mưa dần dần bắt đầu tràn vào phòng."},{"example":"毎晩、お風呂に入ってから寝ます。","example_reading":"まいばん、おふろにはいってからねます。","example_meaning":"Mỗi tối tôi tắm bồn xong rồi mới đi ngủ."}]},{"word":"入れる","reading":"いれる","meaning":"cho vào, đặt vào (có tác động) [他動詞]","notes":["Có người chủ động đặt vào → 本をバッグに入れる."],"examples":[{"example":"私は本をバッグに入れました。","example_reading":"わたしはほんをばっぐにはいれました。","example_meaning":"Tôi đã bỏ sách vào túi."},{"example":"コーヒーに、砂糖を入れますか。","example_reading":"こーひーに、さとうをいれますか。","example_meaning":"Bạn có cho đường vào cà phê không?"}]}],"level":"n5"},
{"word":"乗る・乗せる","reading":"のる・のせる","pair":[{"word":"乗る","reading":"のる","meaning":"lên xe, ngồi lên (tự nhiên) [自動詞]","notes":["Chủ thể tự lên xe → 電車に乗る."],"examples":[{"example":"電車に乗りました。","example_reading":"でんしゃにのりました。","example_meaning":"Tôi đã lên tàu điện."},{"example":"毎朝、八時のバスに乗ります。","example_reading":"まいあさ、はちじのばすにのります。","example_meaning":"Sáng nào tôi cũng đi chuyến xe buýt 8 giờ."}]},{"word":"乗せる","reading":"のせる","meaning":"cho ai lên, đặt lên (có tác động) [他動詞]","notes":["Có người chủ động cho ai lên xe → 子どもを車に乗せる."],"examples":[{"example":"母は子どもを車に乗せました。","example_reading":"はははこどもをくるまにのせました。","example_meaning":"Mẹ cho con lên xe."},{"example":"父は私を、駅まで車に乗せてくれました。","example_reading":"ちちはわたしを、えきまでくるまにのせてくれました。","example_meaning":"Bố đã cho tôi đi nhờ xe ô tô đến tận nhà ga."}]}],"level":"n5"},
{"word":"降りる・降ろす","reading":"おりる・おろす","pair":[{"word":"降りる","reading":"おりる","meaning":"xuống, xuống xe (tự nhiên) [自動詞]","notes":["Chỉ hành động tự mình xuống → 電車から降りる."],"examples":[{"example":"駅で電車から降りました。","example_reading":"えきででんしゃからおります。","example_meaning":"Tôi xuống tàu ở nhà ga."},{"example":"バスから降りるとき、気をつけてください。","example_reading":"ばすからおりるとき、きをつけてください。","example_meaning":"Khi xuống xe buýt hãy cẩn thận."}]},{"word":"降ろす","reading":"おろす","meaning":"hạ xuống, cho xuống (có tác động) [他動詞]","notes":["Có người chủ động hạ xuống vật → 荷物を降ろす."],"examples":[{"example":"運転手が荷物を降ろしました。","example_reading":"うんてんしゅがにもつをおろしました。","example_meaning":"Tài xế đã hạ hàng xuống."},{"example":"すみません、次の角で降ろしてください。","example_reading":"すみません、つぎのかどでおろしてください。","example_meaning":"Xin lỗi, cho tôi xuống ở góc đường tiếp theo."}]}],"level":"n5"},
{"word":"戻る・戻す","reading":"もどる・もどす","pair":[{"word":"戻る","reading":"もどる","meaning":"quay lại, trở về (tự nhiên) [自動詞]","notes":["Hành động trở lại xảy ra tự nhiên với chủ thể → 家に戻る."],"examples":[{"example":"会社から家に戻りました。","example_reading":"かいしゃからいえにもどりました。","example_meaning":"Tôi đã trở về nhà từ công ty."},{"example":"十分後に戻りますので、少しお待ちください。","example_reading":"じゅっぷんごにもどりますので、すこしおまちください。","example_meaning":"10 phút nữa tôi sẽ quay lại, xin hãy đợi một chút."}]},{"word":"戻す","reading":"もどす","meaning":"trả lại, đưa lại chỗ cũ (có tác động) [他動詞]","notes":["Có người chủ động hoàn trả vật → 本を戻す."],"examples":[{"example":"彼は本を棚に戻しました。","example_reading":"かれはほんをたなにもどしました。","example_meaning":"Anh ấy đã trả sách lại giá sách."},{"example":"使ったはさみは、元の場所に戻してください。","example_reading":"つかったはさみは、もとのばしょにもどしてください。","example_meaning":"Kéo dùng xong hãy để lại chỗ cũ."}]}],"level":"n5"},
{"word":"見える・見せる","reading":"みえる・みせる","pair":[{"word":"見える","reading":"みえる","meaning":"có thể nhìn thấy, xuất hiện (tự nhiên) [自動詞]","notes":["Màu/khối hình xuất hiện trước mắt → 雪が見える."],"examples":[{"example":"山の上に雪が見えます。","example_reading":"やまのうえにゆきがみえます。","example_meaning":"Có thể nhìn thấy tuyết trên đỉnh núi."},{"example":"天気がいい日は、窓から海が見えます。","example_reading":"てんきがいいひは、まどからうみがみえます。","example_meaning":"Hôm nào trời đẹp, từ cửa sổ có thể nhìn thấy biển."}]},{"word":"見せる","reading":"みせる","meaning":"cho xem, chỉ cho thấy (có tác động) [他動詞]","notes":["Có chủ thể chủ động cho ai thấy → 写真を見せる."],"examples":[{"example":"先生が学生に写真を見せました。","example_reading":"せんせいががくせいにしゃしんをみせました。","example_meaning":"Giáo viên đã cho học sinh xem ảnh."},{"example":"パスポートを見せてください。","example_reading":"ぱすぽーとをみせてください。","example_meaning":"Xin hãy cho tôi xem hộ chiếu."}]}],"level":"n5"},
{"word":"聞こえる・聞く","reading":"きこえる・きく","pair":[{"word":"聞こえる","reading":"きこえる","meaning":"nghe được, vọng đến (tự nhiên) [自動詞]","notes":["Âm thanh xuất hiện trong tai người nghe → 音が聞こえる."],"examples":[{"example":"遠くで音が聞こえます。","example_reading":"とおくでおとがきこえます。","example_meaning":"Có thể nghe âm thanh từ xa."},{"example":"隣の部屋から、ピアノの音が聞こえます。","example_reading":"となりのへやから、ぴあののおとがきこえます。","example_meaning":"Từ phòng bên cạnh có thể nghe thấy tiếng đàn piano."}]},{"word":"聞く","reading":"きく","meaning":"nghe (chủ động) [他動詞]","notes":["Người nghe chủ động nghe âm thanh → 音楽を聞く."],"examples":[{"example":"毎朝、音楽を聞きます。","example_reading":"まいあさ、おんがくをききます。","example_meaning":"Mỗi sáng tôi nghe nhạc."},{"example":"先生の話をよく聞いてください。","example_reading":"せんせいのはなしをよくきいてください。","example_meaning":"Hãy nghe kỹ lời thầy cô nói."}]}],"level":"n5"},
{"word":"逃げる・逃がす","reading":"にげる・にがす","pair":[{"word":"逃げる","reading":"にげる","meaning":"chạy trốn, trốn đi (tự nhiên) [自動詞]","notes":["Mèo tự chạy trốn → 猫が逃げる."],"examples":[{"example":"猫が急に逃げました。","example_reading":"ねこがきゅうににげました。","example_meaning":"Con mèo đã chạy trốn đột ngột."},{"example":"火事になったので、みんな外へ逃げました。","example_reading":"かじになったので、みんなそとへにげました。","example_meaning":"Vì xảy ra hỏa hoạn nên mọi người đều chạy ra ngoài."}]},{"word":"逃がす","reading":"にがす","meaning":"để trốn, cho trốn thoát (có tác động) [他動詞]","notes":["Có người chủ động làm cho trốn thoát → 〜を逃がす."],"examples":[{"example":"彼は泥棒を逃がしませんでした。","example_reading":"かれはどろぼうをにがしませんでした。","example_meaning":"Anh ấy đã không để tên trộm trốn thoát."},{"example":"釣った魚を、川に逃がしました。","example_reading":"つったさかなを、かわににがしました。","example_meaning":"Tôi đã thả con cá câu được về lại dòng sông."}]}],"level":"n5"},
{"word":"冷える・冷やす","reading":"ひえる・ひやす","pair":[{"word":"冷える","reading":"ひえる","meaning":"lạnh đi, nguội xuống (tự nhiên) [自動詞]","notes":["Nhiệt độ tự giảm → コーヒーが冷える."],"examples":[{"example":"コーヒーが冷えました。","example_reading":"こーひーがひえました。","example_meaning":"Cà phê đã nguội đi."},{"example":"今夜は冷えるので、暖かい服を着てください。","example_reading":"こんやはひえるので、あたたかいふくをきてください。","example_meaning":"Tối nay trời lạnh nên hãy mặc đồ ấm."}]},{"word":"冷やす","reading":"ひやす","meaning":"làm lạnh, làm nguội (có tác động) [他動詞]","notes":["Có người chủ động làm nguội → 水を冷やす."],"examples":[{"example":"私は水を冷やしました。","example_reading":"わたしはみずをひやしました。","example_meaning":"Tôi đã làm nước lạnh đi."},{"example":"ジュースを冷蔵庫で冷やしておきます。","example_reading":"じゅーすをれいぞうこでひやしておきます。","example_meaning":"Tôi sẽ để sẵn nước ép trong tủ lạnh cho mát."}]}],"level":"n5"},
{"word":"下がる・下げる","reading":"さがる・さげる","pair":[{"word":"下がる","reading":"さがる","meaning":"giảm xuống, hạ (tự nhiên) [自動詞]","notes":["Sốt tự hạ, không ai tác động → 熱が下がる."],"examples":[{"example":"熱が下がりました。","example_reading":"ねつがさがりました。","example_meaning":"Cơn sốt đã hạ."},{"example":"夜になると、気温が下がります。","example_reading":"よるになると、きおんがさがります。","example_meaning":"Hễ đến tối là nhiệt độ hạ xuống."}]},{"word":"下げる","reading":"さげる","meaning":"hạ xuống, giảm (có tác động) [他動詞]","notes":["Có người chủ động chỉnh nhiệt độ → 温度を下げる."],"examples":[{"example":"エアコンの温度を下げました。","example_reading":"えあこんのおんどをさげました。","example_meaning":"Tôi đã hạ nhiệt độ điều hòa."},{"example":"お店はお客さんを増やすために、値段を下げました。","example_reading":"おみせはおきゃくさんをふやすために、ねだんをさげました。","example_meaning":"Cửa hàng đã hạ giá để thu hút thêm khách."}]}],"level":"n4"},
{"word":"変わる・変える","reading":"かわる・かえる","pair":[{"word":"変わる","reading":"かわる","meaning":"thay đổi (tự nhiên) [自動詞]","notes":["Đèn tự chuyển màu theo cơ chế → 信号が変わる.","Mùa tự chuyển đổi → 季節が変わる."],"examples":[{"example":"信号が赤から青に変わりました。","example_reading":"しんごうがあかからあおにかわりました。","example_meaning":"Đèn tín hiệu đã chuyển từ đỏ sang xanh."},{"example":"季節が変わりました。","example_reading":"きせつがかわりました。","example_meaning":"Mùa đã thay đổi."},{"example":"引っ越してから、生活がだいぶ変わりました。","example_reading":"ひっこしてから、せいかつがだいぶかわりました。","example_meaning":"Từ khi chuyển nhà, cuộc sống đã thay đổi khá nhiều."}]},{"word":"変える","reading":"かえる","meaning":"thay đổi, sửa đổi (có tác động) [他動詞]","notes":["Người chủ động thay đổi kiểu tóc → 髪型を変える.","Có chủ thể chủ động thay đổi → 予定を変える."],"examples":[{"example":"彼は髪型を変えました。","example_reading":"かれはかみがたをかえました。","example_meaning":"Anh ấy đã đổi kiểu tóc."},{"example":"会社は予定を変えました。","example_reading":"かいしゃはよていをかえました。","example_meaning":"Công ty đã thay đổi kế hoạch."},{"example":"気分を変えるために、新しい服を買いました。","example_reading":"きぶんをかえるために、あたらしいふくをかいました。","example_meaning":"Để thay đổi tâm trạng, tôi đã mua quần áo mới."}]}],"level":"n4"},
{"word":"見つかる・見つける","reading":"みつかる・みつける","pair":[{"word":"見つかる","reading":"みつかる","meaning":"được tìm thấy [自動詞]","notes":["Không nhấn mạnh ai tìm ra → 鍵が見つかる."],"examples":[{"example":"なくした鍵が見つかりました。","example_reading":"なくしたかぎがみつかりました。","example_meaning":"Chìa khóa bị mất đã được tìm thấy."},{"example":"長い間探していた本が、やっと見つかりました。","example_reading":"ながいあいださがしていたほんが、やっとみつかりました。","example_meaning":"Cuốn sách tôi tìm bấy lâu nay cuối cùng cũng đã được tìm thấy."}]},{"word":"見つける","reading":"みつける","meaning":"tìm thấy [他動詞]","notes":["Nhấn mạnh 私 là người tìm ra → 鍵を見つける."],"examples":[{"example":"私は鍵を見つけました。","example_reading":"わたしはかぎをみつけました。","example_meaning":"Tôi đã tìm thấy chìa khóa."},{"example":"私は道で、かわいい子猫を見つけました。","example_reading":"わたしはみちで、かわいいこねこをみつけました。","example_meaning":"Tôi đã phát hiện một chú mèo con đáng yêu ngoài đường."}]}],"level":"n4"},
{"word":"終わる・終える","reading":"おわる・おえる","pair":[{"word":"終わる","reading":"おわる","meaning":"kết thúc (tự nhiên) [自動詞]","notes":["Cuộc họp tự đến lúc kết thúc → 会議が終わる."],"examples":[{"example":"会議が終わりました。","example_reading":"かいぎがおわりました。","example_meaning":"Cuộc họp đã kết thúc."},{"example":"授業は三時に終わります。","example_reading":"じゅぎょうはさんじにおわります。","example_meaning":"Giờ học kết thúc lúc 3 giờ."}]},{"word":"終える","reading":"おえる","meaning":"kết thúc, hoàn tất (có tác động) [他動詞]","notes":["Người chủ động hoàn tất công việc → 仕事を終える."],"examples":[{"example":"彼は仕事を終えました。","example_reading":"かれはしごとをおえました。","example_meaning":"Anh ấy đã hoàn tất công việc."},{"example":"宿題を終えてから、遊びに行きます。","example_reading":"しゅくだいをおえてから、あそびにいきます。","example_meaning":"Sau khi làm xong bài tập, tôi sẽ đi chơi."}]}],"level":"n4"},
{"word":"立つ・立てる","reading":"たつ・たてる","pair":[{"word":"立つ","reading":"たつ","meaning":"đứng, được dựng lên [自動詞]","notes":["Chỉ mô tả kết quả tòa nhà đứng đó → ビルが立つ."],"examples":[{"example":"新しいビルが立ちました。","example_reading":"あたらしいびるがたちました。","example_meaning":"Tòa nhà mới đã được dựng lên."},{"example":"電車が混んでいて、ずっと立っていました。","example_reading":"でんしゃがこんでいて、ずっとたっていました。","example_meaning":"Tàu đông nên tôi đã phải đứng suốt."}]},{"word":"立てる","reading":"たてる","meaning":"dựng lên, xây [他動詞]","notes":["Nhấn mạnh công ty là chủ thể xây dựng → ビルを立てる."],"examples":[{"example":"会社はビルを立てました。","example_reading":"かいしゃはびるをたてました。","example_meaning":"Công ty đã xây tòa nhà."},{"example":"キャンプで、山の中にテントを立てました。","example_reading":"きゃんぷで、やまのなかにてんとをたてました。","example_meaning":"Khi đi cắm trại, chúng tôi đã dựng lều trong núi."}]}],"level":"n4"},
{"word":"届く・届ける","reading":"とどく・とどける","pair":[{"word":"届く","reading":"とどく","meaning":"đến nơi (tự nhiên) [自動詞]","notes":["Chỉ nói kết quả hàng đã đến → 荷物が届く."],"examples":[{"example":"荷物が届きました。","example_reading":"にもつがとどきました。","example_meaning":"Kiện hàng đã đến nơi."},{"example":"誕生日に、友達からプレゼントが届きました。","example_reading":"たんじょうびに、ともだちからぷれぜんとがとどきました。","example_meaning":"Vào ngày sinh nhật, quà của bạn gửi đã đến nơi."}]},{"word":"届ける","reading":"とどける","meaning":"giao, chuyển đến [他動詞]","notes":["Nhấn mạnh người giao hàng chủ động chuyển đến → 荷物を届ける."],"examples":[{"example":"配達員が荷物を届けました。","example_reading":"はいたついんがにもつをとどけました。","example_meaning":"Người giao hàng đã chuyển kiện hàng đến."},{"example":"忘れ物を、駅員さんが家まで届けてくれました。","example_reading":"わすれものを、えきいんさんがいえまでとどけてくれました。","example_meaning":"Nhân viên nhà ga đã mang đồ tôi để quên đến tận nhà."}]}],"level":"n4"},
{"word":"治る・治す","reading":"なおる・なおす","pair":[{"word":"治る","reading":"なおる","meaning":"khỏi bệnh (tự nhiên) [自動詞]","notes":["Cơ thể tự khỏi, không nói ai chữa → 風邪が治る."],"examples":[{"example":"風邪が治りました。","example_reading":"かぜがなおりました。","example_meaning":"Cảm đã khỏi."},{"example":"ゆっくり休んだので、けがが治りました。","example_reading":"ゆっくりやすんだので、けががなおりました。","example_meaning":"Vì nghỉ ngơi thong thả nên vết thương đã lành."}]},{"word":"治す","reading":"なおす","meaning":"chữa khỏi [他動詞]","notes":["Bác sĩ là người chủ động chữa trị → 病気を治す."],"examples":[{"example":"医者が病気を治しました。","example_reading":"いしゃがびょうきをなおしました。","example_meaning":"Bác sĩ đã chữa khỏi bệnh."},{"example":"歯医者さんは、私の歯を治してくれました。","example_reading":"はいしゃさんは、わたしのはをなおしてくれました。","example_meaning":"Nha sĩ đã chữa răng giúp tôi."}]}],"level":"n4"},
{"word":"割れる・割る","reading":"われる・わる","pair":[{"word":"割れる","reading":"われる","meaning":"vỡ (tự nhiên/không rõ ai làm) [自動詞]","notes":["Theo lý thuyết: 窓ガラスが割れた chỉ mô tả kính vỡ, không nói ai làm."],"examples":[{"example":"窓ガラスが割れました。","example_reading":"まどがらすがわれました。","example_meaning":"Kính cửa sổ đã vỡ."},{"example":"お皿が床に落ちて、割れてしまいました。","example_reading":"おさらがゆかにおちて、われてしまいました。","example_meaning":"Cái đĩa rơi xuống sàn và bị vỡ mất rồi."}]},{"word":"割る","reading":"わる","meaning":"làm vỡ (có tác động) [他動詞]","notes":["窓ガラスを割った cho biết rõ đứa trẻ là người gây ra."],"examples":[{"example":"子供が窓ガラスを割りました。","example_reading":"こどもがまどがらすをわりました。","example_meaning":"Đứa trẻ đã làm vỡ kính cửa sổ."},{"example":"卵を割って、ボウルに入れます。","example_reading":"たまごをわって、ぼうるにいれます。","example_meaning":"Đập trứng rồi cho vào tô."}]}],"level":"n4"},
{"word":"大学を卒業する","reading":"だいがくをそつぎょうする","meaning":"tốt nghiệp đại học (tự động từ dùng với を chỉ điểm xuất phát)","note":"⚠ 卒業する là TỰ ĐỘNG TỪ. 「大学を」chỉ nơi chốn xuất phát (rời khỏi), không phải đối tượng chịu tác động như tha động từ thật sự.","example":"来年、大学を卒業します。","example_reading":"らいねん、だいがくをそつぎょうします。","example_meaning":"Sang năm tôi sẽ tốt nghiệp đại học.","level":"n4"},
{"word":"付く・付ける","reading":"つく・つける","pair":[{"word":"付く","reading":"つく","meaning":"dính, gắn vào, bắt đầu (tự nhiên) [自動詞]","notes":["Là trạng thái dính/gắn vào → 〜に付く."],"examples":[{"example":"メモが冷蔵庫に付いています。","example_reading":"めもがれいぞうこについています。","example_meaning":"Ghi chú đã dính trên tủ lạnh."},{"example":"服にコーヒーのしみが付いてしまいました。","example_reading":"ふくにこーひーのしみがついてしまいました。","example_meaning":"Quần áo bị dính vết cà phê mất rồi."}]},{"word":"付ける","reading":"つける","meaning":"gắn, dán, thêm vào (có tác động) [他動詞]","notes":["Có người chủ động gắn/đính → 名前を付ける."],"examples":[{"example":"私は名前を付けました。","example_reading":"わたしはなまえをつけました。","example_meaning":"Tôi đã gắn tên vào."},{"example":"メールに写真を付けて送りました。","example_reading":"めーるにしゃしんをつけておくりました。","example_meaning":"Tôi đã đính kèm ảnh vào email rồi gửi đi."}]}],"level":"n4"},
{"word":"進む・進める","reading":"すすむ・すすめる","pair":[{"word":"進む","reading":"すすむ","meaning":"tiến lên, tiến triển (tự nhiên) [自動詞]","notes":["Quá trình tiến triển tự nhiên → 工事が進む."],"examples":[{"example":"工事が順調に進んでいます。","example_reading":"こうじがじゅんちょうにすすんでいます。","example_meaning":"Công việc đang tiến triển thuận lợi."},{"example":"道が混んでいて、車がなかなか進みません。","example_reading":"みちがこんでいて、くるまがなかなかすすみません。","example_meaning":"Đường đông nên xe mãi không nhích lên được."}]},{"word":"進める","reading":"すすめる","meaning":"đẩy tiến, thúc đẩy (có tác động) [他動詞]","notes":["Có người chủ động thúc đẩy tiến độ → 計画を進める."],"examples":[{"example":"社長は計画を進めました。","example_reading":"しゃちょうはけいかくをすすめました。","example_meaning":"Giám đốc đã thúc đẩy kế hoạch tiến triển."},{"example":"会議を進めるために、みんなで意見を出しました。","example_reading":"かいぎをすすめるために、みんなでいけんをだしました。","example_meaning":"Để thúc đẩy cuộc họp, mọi người đã cùng đưa ra ý kiến."}]}],"level":"n4"},
{"word":"温まる・温める","reading":"あたたまる・あたためる","pair":[{"word":"温まる","reading":"あたたまる","meaning":"ấm lên, ấm dần (tự nhiên) [自動詞]","notes":["Nhiệt độ tự thay đổi → 温まる."],"examples":[{"example":"湯が少しずつ温まりました。","example_reading":"ゆがすこしずつあたたまりました。","example_meaning":"Nước nóng đã dần ấm lên."},{"example":"ストーブをつけると、部屋がすぐ温まります。","example_reading":"すとーぶをつけると、へやがすぐあたたまります。","example_meaning":"Bật lò sưởi lên là phòng ấm ngay."}]},{"word":"温める","reading":"あたためる","meaning":"làm ấm lên, hâm nóng (có tác động) [他動詞]","notes":["Có người chủ động làm ấm → お湯を温める."],"examples":[{"example":"母はお湯を温めました。","example_reading":"はははおゆをあたためました。","example_meaning":"Mẹ đã hâm nóng nước."},{"example":"冷めたスープを、電子レンジで温めました。","example_reading":"さめたすーぷを、でんしれんじであたためました。","example_meaning":"Tôi đã hâm nóng bát súp nguội bằng lò vi sóng."}]}],"level":"n4"},
{"word":"溶ける・溶かす","reading":"とける・とかす","pair":[{"word":"溶ける","reading":"とける","meaning":"tan chảy, tan ra (tự nhiên) [自動詞]","notes":["Băng tan chảy tự nhiên → 氷が溶ける."],"examples":[{"example":"氷が溶けました。","example_reading":"こおりがとけました。","example_meaning":"Băng đã tan chảy."},{"example":"アイスクリームが溶けてしまいました。","example_reading":"あいすくりーむがとけてしまいました。","example_meaning":"Cây kem bị tan chảy mất rồi."}]},{"word":"溶かす","reading":"とかす","meaning":"làm tan chảy (có tác động) [他動詞]","notes":["Có người chủ động làm tan chảy → 氷を溶かす."],"examples":[{"example":"彼は氷を溶かしました。","example_reading":"かれはこおりをとかしました。","example_meaning":"Anh ấy đã làm tan băng."},{"example":"バターを溶かして、フライパンに入れます。","example_reading":"ばたーをとかして、ふらいぱんにいれます。","example_meaning":"Làm tan chảy bơ rồi cho vào chảo."}]}],"level":"n4"},
{"word":"焼ける・焼く","reading":"やける・やく","pair":[{"word":"焼ける","reading":"やける","meaning":"bị cháy, chín da (tự nhiên) [自動詞]","notes":["Trạng thái bị nướng/chín tự nhiên → 料理が焼ける."],"examples":[{"example":"料理が焼けました。","example_reading":"りょうりがやけました。","example_meaning":"Món ăn đã chín/đã nướng."},{"example":"パンがおいしそうに焼けました。","example_reading":"ぱんがおいしそうにやけました。","example_meaning":"Bánh mì đã nướng chín trông rất ngon."}]},{"word":"焼く","reading":"やく","meaning":"nướng, quay, thiêu (có tác động) [他動詞]","notes":["Có người chủ động nướng → 魚を焼く."],"examples":[{"example":"母は魚を焼きました。","example_reading":"はははさかなをやきました。","example_meaning":"Mẹ đã nướng cá."},{"example":"日曜日に、友達とクッキーを焼きました。","example_reading":"にちようびに、ともだちとくっきーをやきました。","example_meaning":"Chủ nhật, tôi đã nướng bánh quy cùng bạn."}]}],"level":"n4"},
{"word":"破れる・破る","reading":"やぶれる・やぶる","pair":[{"word":"破れる","reading":"やぶれる","meaning":"rách, nứt, hỏng (tự nhiên) [自動詞]","notes":["Túi tự rách → 袋が破れる."],"examples":[{"example":"袋が破れました。","example_reading":"ふくろがやぶれました。","example_meaning":"Túi đã rách."},{"example":"古いズボンが、破れてしまいました。","example_reading":"ふるいずぼんが、やぶれてしまいました。","example_meaning":"Chiếc quần cũ bị rách mất rồi."}]},{"word":"破る","reading":"やぶる","meaning":"xé rách, phá vỡ (có tác động) [他動詞]","notes":["Có người chủ động xé rách → 紙を破る."],"examples":[{"example":"子どもが紙を破りました。","example_reading":"こどもがかみをやぶりました。","example_meaning":"Đứa trẻ đã xé giấy."},{"example":"大切な約束を破ってはいけません。","example_reading":"たいせつなやくそくをやぶってはいけません。","example_meaning":"Không được phá vỡ lời hứa quan trọng."}]}],"level":"n4"},
{"word":"壊れる・壊す","reading":"こわれる・こわす","pair":[{"word":"壊れる","reading":"こわれる","meaning":"hỏng, vỡ, nứt (tự nhiên) [自動詞]","notes":["Thiết bị tự hỏng → スマホが壊れる."],"examples":[{"example":"スマホが壊れました。","example_reading":"すまほがこわれました。","example_meaning":"Điện thoại đã hỏng."},{"example":"洗濯機が壊れたので、新しいのを買いました。","example_reading":"せんたくきがこわれたので、あたらしいのをかいました。","example_meaning":"Máy giặt bị hỏng nên tôi đã mua cái mới."}]},{"word":"壊す","reading":"こわす","meaning":"làm hỏng, phá vỡ (có tác động) [他動詞]","notes":["Có người chủ động làm hỏng → コップを壊す."],"examples":[{"example":"私はコップを壊しました。","example_reading":"わたしはこっぷをこわしました。","example_meaning":"Tôi đã làm vỡ chiếc cốc."},{"example":"弟はおもちゃを壊して、泣いています。","example_reading":"おとうとはおもちゃをこわして、ないています。","example_meaning":"Em trai làm hỏng đồ chơi và đang khóc."}]}],"level":"n4"},
{"word":"増える・増やす","reading":"ふえる・ふやす","pair":[{"word":"増える","reading":"ふえる","meaning":"tăng lên, nhiều hơn (tự nhiên) [自動詞]","notes":["Sự tăng lên diễn ra tự nhiên → 人が増える."],"examples":[{"example":"人が増えました。","example_reading":"ひとがふえました。","example_meaning":"Số người đã tăng lên."},{"example":"最近、外国から来る観光客が増えました。","example_reading":"さいきん、がいこくからくるかんこうきゃくがふえました。","example_meaning":"Gần đây, du khách đến từ nước ngoài đã tăng lên."}]},{"word":"増やす","reading":"ふやす","meaning":"tăng thêm, làm nhiều hơn (có tác động) [他動詞]","notes":["Có người chủ động làm tăng → 生産を増やす."],"examples":[{"example":"会社は生産を増やしました。","example_reading":"かいしゃはせいさんをふやしました。","example_meaning":"Công ty đã tăng sản xuất."},{"example":"健康のために、運動する時間を増やしました。","example_reading":"けんこうのために、うんどうするじかんをふやしました。","example_meaning":"Vì sức khỏe, tôi đã tăng thời gian tập thể dục."}]}],"level":"n4"},
{"word":"減る・減らす","reading":"へる・へらす","pair":[{"word":"減る","reading":"へる","meaning":"giảm xuống, bớt đi (tự nhiên) [自動詞]","notes":["Sự giảm xảy ra tự thân → 体重が減る."],"examples":[{"example":"体重が減りました。","example_reading":"たいじゅうがへりました。","example_meaning":"Cân nặng đã giảm."},{"example":"若い人の数が、だんだん減っています。","example_reading":"わかいひとのかずが、だんだんへっています。","example_meaning":"Số người trẻ đang giảm dần."}]},{"word":"減らす","reading":"へらす","meaning":"làm giảm, bớt đi (có tác động) [他動詞]","notes":["Có người chủ động làm giảm → 食費を減らす."],"examples":[{"example":"私は食費を減らしました。","example_reading":"わたしはしょくひをへらしました。","example_meaning":"Tôi đã giảm chi phí ăn uống."},{"example":"お菓子を減らして、ダイエットしています。","example_reading":"おかしをへらして、だいえっとしています。","example_meaning":"Tôi giảm đồ ngọt để ăn kiêng."}]}],"level":"n4"},
{"word":"掛かる・掛ける","reading":"かかる・かける","pair":[{"word":"掛かる","reading":"かかる","meaning":"được treo, bị khóa (tự nhiên) [自動詞]","notes":["Trạng thái đang treo/đang khóa, không nhấn mạnh ai làm → 鍵が掛かる."],"examples":[{"example":"壁に絵が掛かっています。","example_reading":"かべにえがかかっています。","example_meaning":"Trên tường có treo một bức tranh."},{"example":"ドアに鍵が掛かっています。","example_reading":"どあにかぎがかかっています。","example_meaning":"Cửa đã bị khóa."}]},{"word":"掛ける","reading":"かける","meaning":"treo, khóa lại (có tác động) [他動詞]","notes":["Có người chủ động treo/khóa → 鍵を掛ける."],"examples":[{"example":"壁に絵を掛けました。","example_reading":"かべにえをかけました。","example_meaning":"Tôi đã treo tranh lên tường."},{"example":"出かける前に、ドアに鍵を掛けます。","example_reading":"でかけるまえに、どあにかぎをかけます。","example_meaning":"Trước khi ra ngoài tôi khóa cửa."}]}],"level":"n4"},
{"word":"助かる・助ける","reading":"たすかる・たすける","pair":[{"word":"助かる","reading":"たすかる","meaning":"được cứu, đỡ vất vả (tự nhiên) [自動詞]","notes":["Kết quả được cứu/được giúp, không nói ai cứu → 命が助かる."],"examples":[{"example":"事故にあったが、全員助かりました。","example_reading":"じこにあったが、ぜんいんたすかりました。","example_meaning":"Dù gặp tai nạn nhưng tất cả đều được cứu."},{"example":"手伝ってくれて、本当に助かりました。","example_reading":"てつだってくれて、ほんとうにたすかりました。","example_meaning":"Bạn giúp nên tôi đỡ vất vả thật sự."}]},{"word":"助ける","reading":"たすける","meaning":"cứu, giúp đỡ (có tác động) [他動詞]","notes":["Có người chủ động giúp/cứu → 人を助ける."],"examples":[{"example":"消防士が川で溺れた子供を助けました。","example_reading":"しょうぼうしがかわでおぼれたこどもをたすけました。","example_meaning":"Lính cứu hỏa đã cứu đứa trẻ bị đuối nước ở sông."},{"example":"困っている友達を助けました。","example_reading":"こまっているともだちをたすけました。","example_meaning":"Tôi đã giúp người bạn đang gặp khó khăn."}]}],"level":"n4"},
{"word":"泊まる・泊める","reading":"とまる・とめる","pair":[{"word":"泊まる","reading":"とまる","meaning":"trọ lại, ngủ lại (tự nhiên) [自動詞]","notes":["Chủ thể tự ở lại qua đêm → ホテルに泊まる."],"examples":[{"example":"友達の家に泊まりました。","example_reading":"ともだちのいえにとまりました。","example_meaning":"Tôi đã ngủ lại nhà bạn."},{"example":"旅行中は、小さな旅館に泊まりました。","example_reading":"りょこうちゅうは、ちいさなりょかんにとまりました。","example_meaning":"Trong chuyến du lịch tôi đã ở một nhà trọ nhỏ."}]},{"word":"泊める","reading":"とめる","meaning":"cho ai ngủ lại (có tác động) [他動詞]","notes":["Có người chủ động cho người khác ở lại → 客を泊める."],"examples":[{"example":"友達を家に泊めました。","example_reading":"ともだちをいえにとめました。","example_meaning":"Tôi đã cho bạn ngủ lại nhà."},{"example":"雨がひどいので、お客さんを一晩泊めることにしました。","example_reading":"あめがひどいので、おきゃくさんをひとばんとめることにしました。","example_meaning":"Mưa to quá nên tôi quyết định cho khách ngủ lại một đêm."}]}],"level":"n4"},
{"word":"動く・動かす","reading":"うごく・うごかす","pair":[{"word":"動く","reading":"うごく","meaning":"chuyển động, chạy (tự nhiên) [自動詞]","notes":["Vật tự chuyển động/vận hành → 機械が動く."],"examples":[{"example":"時計が動いています。","example_reading":"とけいがうごいています。","example_meaning":"Đồng hồ đang chạy."},{"example":"故障して、機械が動かなくなりました。","example_reading":"こしょうして、きかいがうごかなくなりました。","example_meaning":"Máy bị hỏng nên không hoạt động nữa."}]},{"word":"動かす","reading":"うごかす","meaning":"làm chuyển động, di chuyển (có tác động) [他動詞]","notes":["Có người chủ động di chuyển vật → 机を動かす."],"examples":[{"example":"彼は重い机を動かしました。","example_reading":"かれはおもいつくえをうごかしました。","example_meaning":"Anh ấy đã di chuyển cái bàn nặng."},{"example":"体を動かすのが好きです。","example_reading":"からだをうごかすのがすきです。","example_meaning":"Tôi thích vận động cơ thể."}]}],"level":"n4"},
{"word":"沸く・沸かす","reading":"わく・わかす","pair":[{"word":"沸く","reading":"わく","meaning":"sôi (tự nhiên) [自動詞]","notes":["Nước tự sôi lên → お湯が沸く."],"examples":[{"example":"お湯が沸きました。","example_reading":"おゆがわきました。","example_meaning":"Nước đã sôi."},{"example":"やかんの水が沸くまで、少し待ってください。","example_reading":"やかんのみずがわくまで、すこしまってください。","example_meaning":"Hãy đợi một chút cho đến khi nước trong ấm sôi."}]},{"word":"沸かす","reading":"わかす","meaning":"đun sôi (có tác động) [他動詞]","notes":["Có người chủ động đun nước → お湯を沸かす."],"examples":[{"example":"母がお湯を沸かしました。","example_reading":"はははおゆをわかしました。","example_meaning":"Mẹ đã đun nước sôi."},{"example":"お風呂を沸かして、家族が入るのを待ちます。","example_reading":"おふろをわかして、かぞくがはいるのをまちます。","example_meaning":"Tôi đun nước bồn tắm rồi đợi cả nhà vào tắm."}]}],"level":"n4"},
{"word":"乾く・乾かす","reading":"かわく・かわかす","pair":[{"word":"乾く","reading":"かわく","meaning":"khô (tự nhiên) [自動詞]","notes":["Đồ vật tự khô → 洗濯物が乾く."],"examples":[{"example":"洗濯物が乾きました。","example_reading":"せんたくものがかわきました。","example_meaning":"Đồ giặt đã khô."},{"example":"天気がいいので、すぐ乾きます。","example_reading":"てんきがいいので、すぐかわきます。","example_meaning":"Trời đẹp nên sẽ khô ngay."}]},{"word":"乾かす","reading":"かわかす","meaning":"làm khô, phơi khô (có tác động) [他動詞]","notes":["Có người chủ động làm khô → 髪を乾かす."],"examples":[{"example":"私は洗濯物を乾かしました。","example_reading":"わたしはせんたくものをかわかしました。","example_meaning":"Tôi đã phơi khô đồ giặt."},{"example":"髪をドライヤーで乾かしてから寝ます。","example_reading":"かみをどらいやーでかわかしてからねます。","example_meaning":"Tôi sấy khô tóc rồi mới đi ngủ."}]}],"level":"n4"},
{"word":"隠れる・隠す","reading":"かくれる・かくす","pair":[{"word":"隠れる","reading":"かくれる","meaning":"trốn, ẩn nấp (tự nhiên) [自動詞]","notes":["Chủ thể tự trốn/bị che khuất → 猫が隠れる."],"examples":[{"example":"猫がソファの後ろに隠れました。","example_reading":"ねこがそふぁのうしろにかくれました。","example_meaning":"Con mèo đã trốn sau ghế sofa."},{"example":"月が雲に隠れて、暗くなりました。","example_reading":"つきがくもにかくれて、くらくなりました。","example_meaning":"Trăng bị mây che nên trời tối đi."}]},{"word":"隠す","reading":"かくす","meaning":"giấu, che giấu (có tác động) [他動詞]","notes":["Có người chủ động giấu → 物を隠す."],"examples":[{"example":"子供はおもちゃを箱に隠しました。","example_reading":"こどもはおもちゃをはこにかくしました。","example_meaning":"Đứa trẻ đã giấu đồ chơi vào hộp."},{"example":"彼は本当の気持ちを隠しています。","example_reading":"かれはほんとうのきもちをかくしています。","example_meaning":"Anh ấy đang giấu cảm xúc thật."}]}],"level":"n4"},
{"word":"流れる・流す","reading":"ながれる・ながす","pair":[{"word":"流れる","reading":"ながれる","meaning":"chảy, trôi (tự nhiên) [自動詞]","notes":["Nước/âm thanh tự chảy → 水が流れる."],"examples":[{"example":"川の水が流れています。","example_reading":"かわのみずがながれています。","example_meaning":"Nước sông đang chảy."},{"example":"部屋に静かな音楽が流れています。","example_reading":"へやにしずかなおんがくがながれています。","example_meaning":"Trong phòng đang vang lên bản nhạc nhẹ nhàng."}]},{"word":"流す","reading":"ながす","meaning":"làm chảy, xả, bật (nhạc) (có tác động) [他動詞]","notes":["Có người chủ động xả/cho chảy → 水を流す."],"examples":[{"example":"トイレの水を流しました。","example_reading":"といれのみずをながしました。","example_meaning":"Tôi đã xả nước toilet."},{"example":"店で、静かな音楽を流しています。","example_reading":"みせで、しずかなおんがくをながしています。","example_meaning":"Cửa hàng đang mở nhạc nhẹ."}]}],"level":"n4"},
{"word":"汚れる・汚す","reading":"よごれる・よごす","pair":[{"word":"汚れる","reading":"よごれる","meaning":"bị bẩn (tự nhiên) [自動詞]","notes":["Vật tự bị bẩn → 靴が汚れる."],"examples":[{"example":"靴が泥で汚れました。","example_reading":"くつがどろでよごれました。","example_meaning":"Giày bị bẩn vì bùn."},{"example":"白いシャツが汚れてしまいました。","example_reading":"しろいしゃつがよごれてしまいました。","example_meaning":"Chiếc áo sơ mi trắng bị bẩn mất rồi."}]},{"word":"汚す","reading":"よごす","meaning":"làm bẩn (có tác động) [他動詞]","notes":["Có người chủ động làm bẩn → 服を汚す."],"examples":[{"example":"子供が服を汚しました。","example_reading":"こどもがふくをよごしました。","example_meaning":"Đứa trẻ đã làm bẩn quần áo."},{"example":"コーヒーをこぼして、机を汚してしまいました。","example_reading":"こーひーをこぼして、つくえをよごしてしまいました。","example_meaning":"Tôi làm đổ cà phê và làm bẩn cái bàn mất rồi."}]}],"level":"n4"},
{"word":"育つ・育てる","reading":"そだつ・そだてる","pair":[{"word":"育つ","reading":"そだつ","meaning":"lớn lên, được nuôi lớn (tự nhiên) [自動詞]","notes":["Cây/người tự lớn lên → 花が育つ."],"examples":[{"example":"庭の花がきれいに育ちました。","example_reading":"にわのはながきれいにそだちました。","example_meaning":"Hoa trong vườn đã lớn lên thật đẹp."},{"example":"彼は田舎で育ちました。","example_reading":"かれはいなかでそだちました。","example_meaning":"Anh ấy lớn lên ở quê."}]},{"word":"育てる","reading":"そだてる","meaning":"nuôi, trồng, nuôi dạy (có tác động) [他動詞]","notes":["Có người chủ động nuôi dưỡng → 子供を育てる."],"examples":[{"example":"母は私を一人で育てました。","example_reading":"はははわたしをひとりでそだてました。","example_meaning":"Mẹ đã nuôi tôi lớn một mình."},{"example":"ベランダでトマトを育てています。","example_reading":"べらんだでとまとをそだてています。","example_meaning":"Tôi đang trồng cà chua ở ban công."}]}],"level":"n4"},
{"word":"生まれる・生む","reading":"うまれる・うむ","pair":[{"word":"生まれる","reading":"うまれる","meaning":"được sinh ra (tự nhiên) [自動詞]","notes":["Em bé tự chào đời, chủ ngữ là em bé → 赤ちゃんが生まれる."],"examples":[{"example":"昨日、赤ちゃんが生まれました。","example_reading":"きのう、あかちゃんがうまれました。","example_meaning":"Hôm qua em bé đã chào đời."},{"example":"私は東京で生まれました。","example_reading":"わたしはとうきょうでうまれました。","example_meaning":"Tôi sinh ra ở Tokyo."}]},{"word":"生む","reading":"うむ","meaning":"sinh ra, tạo ra (có tác động) [他動詞]","notes":["Người mẹ chủ động sinh con → 子供を生む. Cũng dùng với nghĩa tạo ra → 利益を生む."],"examples":[{"example":"彼女は元気な男の子を生みました。","example_reading":"かのじょはげんきなおとこのこをうみました。","example_meaning":"Cô ấy đã sinh một bé trai khỏe mạnh."},{"example":"この技術は、大きな利益を生みました。","example_reading":"このぎじゅつは、おおきなりえきをうみました。","example_meaning":"Công nghệ này đã tạo ra lợi nhuận lớn."}]}],"level":"n4"},
{"word":"負ける・負かす","reading":"まける・まかす","pair":[{"word":"負ける","reading":"まける","meaning":"thua (tự nhiên) [自動詞]","notes":["Chủ thể bị thua, dùng が → 試合に負ける."],"examples":[{"example":"昨日の試合で、私たちのチームが負けました。","example_reading":"きのうのしあいで、わたしたちのちーむがまけました。","example_meaning":"Trong trận hôm qua đội chúng tôi đã thua."},{"example":"最後まで頑張ったが、負けてしまいました。","example_reading":"さいごまでがんばったが、まけてしまいました。","example_meaning":"Dù cố gắng đến cuối nhưng tôi vẫn thua mất."}]},{"word":"負かす","reading":"まかす","meaning":"đánh bại (có tác động) [他動詞]","notes":["Có người chủ động đánh bại đối thủ → 相手を負かす."],"examples":[{"example":"弟は将棋で私を負かしました。","example_reading":"おとうとはしょうぎでわたしをまかしました。","example_meaning":"Em trai đã đánh bại tôi ở cờ shogi."},{"example":"彼は強い相手を負かして、優勝しました。","example_reading":"かれはつよいあいてをまかして、ゆうしょうしました。","example_meaning":"Anh ấy hạ đối thủ mạnh và giành chức vô địch."}]}],"level":"n4"},
{"word":"取れる・取る","reading":"とれる・とる","pair":[{"word":"取れる","reading":"とれる","meaning":"bị đứt ra, hết, thu được (tự nhiên) [自動詞]","notes":["Vật tự bung ra hoặc cảm giác tự hết → ボタンが取れる."],"examples":[{"example":"シャツのボタンが取れました。","example_reading":"しゃつのぼたんがとれました。","example_meaning":"Cúc áo sơ mi đã bị đứt ra."},{"example":"疲れが取れて、元気になりました。","example_reading":"つかれがとれて、げんきになりました。","example_meaning":"Hết mệt nên tôi đã khỏe lại."}]},{"word":"取る","reading":"とる","meaning":"lấy, cầm (có tác động) [他動詞]","notes":["Có người chủ động lấy → 本を取る."],"examples":[{"example":"彼は棚から本を取りました。","example_reading":"かれはたなからほんをとりました。","example_meaning":"Anh ấy đã lấy sách từ trên kệ."},{"example":"手を伸ばして、高い所の箱を取りました。","example_reading":"てをのばして、たかいところのはこをとりました。","example_meaning":"Tôi với tay lấy cái hộp ở chỗ cao."}]}],"level":"n4"},
{"word":"片付く・片付ける","reading":"かたづく・かたづける","pair":[{"word":"片付く","reading":"かたづく","meaning":"được dọn gọn, được giải quyết (tự nhiên) [自動詞]","notes":["Trạng thái đã gọn gàng/xong xuôi → 部屋が片付く."],"examples":[{"example":"部屋が片付きました。","example_reading":"へやがかたづきました。","example_meaning":"Phòng đã được dọn gọn."},{"example":"やっと問題が片付いて、ほっとしました。","example_reading":"やっともんだいがかたづいて、ほっとしました。","example_meaning":"Cuối cùng vấn đề cũng được giải quyết xong nên tôi thở phào."}]},{"word":"片付ける","reading":"かたづける","meaning":"dọn dẹp, giải quyết (có tác động) [他動詞]","notes":["Có người chủ động dọn dẹp → 部屋を片付ける."],"examples":[{"example":"私は部屋を片付けました。","example_reading":"わたしはへやをかたづけました。","example_meaning":"Tôi đã dọn dẹp phòng."},{"example":"食事のあとで、お皿を片付けます。","example_reading":"しょくじのあとで、おさらをかたづけます。","example_meaning":"Sau bữa ăn tôi dọn bát đĩa."}]}],"level":"n4"},
{"word":"空く・空ける","reading":"あく・あける","pair":[{"word":"空く","reading":"あく","meaning":"trống, còn chỗ (tự nhiên) [自動詞]","notes":["Chỗ ngồi/phòng tự trống ra → 席が空く. Khác với 開く (mở ra)."],"examples":[{"example":"席が空きました。","example_reading":"せきがあきました。","example_meaning":"Chỗ ngồi đã trống."},{"example":"部屋が一つ空いています。","example_reading":"へやがひとつあいています。","example_meaning":"Còn một phòng trống."}]},{"word":"空ける","reading":"あける","meaning":"để trống, làm trống (có tác động) [他動詞]","notes":["Có người chủ động để trống → 時間を空ける. Khác với 開ける (mở ra)."],"examples":[{"example":"私は荷物のために、棚を空けました。","example_reading":"わたしはにもつのために、たなをあけました。","example_meaning":"Tôi để trống kệ cho hành lý."},{"example":"週末の予定を空けておいてください。","example_reading":"しゅうまつのよていをあけておいてください。","example_meaning":"Hãy để trống lịch cuối tuần giúp tôi."}]}],"level":"n4"},
{"word":"残る・残す","reading":"のこる・のこす","pair":[{"word":"残る","reading":"のこる","meaning":"còn lại, ở lại (tự nhiên) [自動詞]","notes":["Vật/người tự còn lại → お金が残る."],"examples":[{"example":"教室に誰かが残っています。","example_reading":"きょうしつにだれかがのこっています。","example_meaning":"Có ai đó còn ở lại trong phòng học."},{"example":"机の上に、お金が少し残っています。","example_reading":"つくえのうえに、おかねがすこしのこっています。","example_meaning":"Trên bàn còn lại một ít tiền."}]},{"word":"残す","reading":"のこす","meaning":"để lại, bỏ thừa (có tác động) [他動詞]","notes":["Có người chủ động để lại → 料理を残す."],"examples":[{"example":"彼は料理を残しました。","example_reading":"かれはりょうりをのこしました。","example_meaning":"Anh ấy đã để thừa thức ăn."},{"example":"母は私に、手紙を残しました。","example_reading":"はははわたしに、てがみをのこしました。","example_meaning":"Mẹ đã để lại cho tôi một lá thư."}]}],"level":"n4"},
{"word":"遅れる・遅らせる","reading":"おくれる・おくらせる","pair":[{"word":"遅れる","reading":"おくれる","meaning":"bị trễ (tự nhiên) [自動詞]","notes":["Chủ thể bị trễ, thường do hoàn cảnh → 電車が遅れる."],"examples":[{"example":"電車が遅れて、会議に間に合いませんでした。","example_reading":"でんしゃがおくれて、かいぎにまにあいませんでした。","example_meaning":"Tàu bị trễ nên tôi không kịp cuộc họp."},{"example":"雪で、バスが三十分遅れました。","example_reading":"ゆきで、ばすがさんじゅっぷんおくれました。","example_meaning":"Vì tuyết xe buýt đã trễ 30 phút."}]},{"word":"遅らせる","reading":"おくらせる","meaning":"làm chậm lại, hoãn lại (dùng thể sai khiến) [他動詞]","notes":["Có người chủ động làm chậm lại → 予定を遅らせる. Đây là dạng sai khiến của 遅れる."],"examples":[{"example":"彼は出発を一日遅らせました。","example_reading":"かれはしゅっぱつをいちにちおくらせました。","example_meaning":"Anh ấy đã hoãn khởi hành một ngày."},{"example":"都合が悪くなったので、会議の時間を遅らせました。","example_reading":"つごうがわるくなったので、かいぎのじかんをおくらせました。","example_meaning":"Có việc bất tiện nên tôi dời giờ họp muộn lại."}]}],"level":"n4"},
{"word":"渡る・渡す","reading":"わたる・わたす","pair":[{"word":"渡る","reading":"わたる","meaning":"đi qua, băng qua (tự nhiên) [自動詞]","notes":["Chủ thể tự băng qua, を chỉ nơi đi qua → 道を渡る."],"examples":[{"example":"信号が青になってから、道を渡ります。","example_reading":"しんごうがあおになってから、みちをわたります。","example_meaning":"Tôi qua đường sau khi đèn xanh."},{"example":"子供が一人で橋を渡りました。","example_reading":"こどもがひとりではしをわたりました。","example_meaning":"Đứa trẻ đã một mình đi qua cầu."}]},{"word":"渡す","reading":"わたす","meaning":"đưa, trao cho (có tác động) [他動詞]","notes":["Có người chủ động trao cho người khác → 本を渡す."],"examples":[{"example":"彼は友達に本を渡しました。","example_reading":"かれはともだちにほんをわたしました。","example_meaning":"Anh ấy đã đưa sách cho bạn."},{"example":"受付で、書類を渡してください。","example_reading":"うけつけで、しょるいをわたしてください。","example_meaning":"Hãy đưa giấy tờ ở quầy lễ tân."}]}],"level":"n4"},
{"word":"冷める・冷ます","reading":"さめる・さます","pair":[{"word":"冷める","reading":"さめる","meaning":"nguội đi (tự nhiên) [自動詞]","notes":["Thức ăn/đồ uống tự nguội → スープが冷める."],"examples":[{"example":"スープが冷めてしまいました。","example_reading":"すーぷがさめてしまいました。","example_meaning":"Súp đã nguội mất rồi."},{"example":"話しているうちに、コーヒーが冷めました。","example_reading":"はなしているうちに、こーひーがさめました。","example_meaning":"Trong lúc nói chuyện cà phê đã nguội."}]},{"word":"冷ます","reading":"さます","meaning":"để cho nguội, làm nguội (có tác động) [他動詞]","notes":["Có người chủ động để nguội → お茶を冷ます."],"examples":[{"example":"私はお茶を冷まして、飲みました。","example_reading":"わたしはおちゃをさまして、のみました。","example_meaning":"Tôi để trà nguội bớt rồi uống."},{"example":"熱いので、息をかけてスープを冷まします。","example_reading":"あついので、いきをかけてすーぷをさまします。","example_meaning":"Nóng quá nên tôi thổi cho súp nguội bớt."}]}],"level":"n4"},
{"word":"着く・着ける","reading":"つく・つける","pair":[{"word":"着く","reading":"つく","meaning":"đến nơi (tự nhiên) [自動詞]","notes":["Chủ thể tự đến một địa điểm → 駅に着く. Khác với 付く, つく (sáng)."],"examples":[{"example":"電車が駅に着きました。","example_reading":"でんしゃがえきにつきました。","example_meaning":"Tàu đã đến ga."},{"example":"荷物が、やっと家に着きました。","example_reading":"にもつが、やっといえにつきました。","example_meaning":"Kiện hàng cuối cùng cũng đã đến nhà."}]},{"word":"着ける","reading":"つける","meaning":"đỗ sát vào, cho cập (bến) (có tác động) [他動詞]","notes":["Có người chủ động cho xe/thuyền cập sát → 車を着ける."],"examples":[{"example":"運転手は、車を店の前に着けました。","example_reading":"うんてんしゅは、くるまをみせのまえにつけました。","example_meaning":"Tài xế đã đỗ xe sát trước cửa tiệm."},{"example":"彼は船を岸に着けました。","example_reading":"かれはふねをきしにつけました。","example_meaning":"Anh ấy đã cho thuyền cập bờ."}]}],"level":"n4"},
{"word":"ぶつかる・ぶつける","reading":"ぶつかる・ぶつける","pair":[{"word":"ぶつかる","reading":"ぶつかる","meaning":"va vào, đâm vào (tự nhiên) [自動詞]","notes":["Chủ thể tự va vào vật khác → 車にぶつかる."],"examples":[{"example":"自転車が車にぶつかりました。","example_reading":"じてんしゃがくるまにぶつかりました。","example_meaning":"Xe đạp đã đâm vào ô tô."},{"example":"暗くて、ドアにぶつかってしまいました。","example_reading":"くらくて、どあにぶつかってしまいました。","example_meaning":"Tối quá nên tôi đã va vào cửa."}]},{"word":"ぶつける","reading":"ぶつける","meaning":"làm va vào, đụng phải (có tác động) [他動詞]","notes":["Có người làm cho vật/bộ phận cơ thể va vào → 頭をぶつける."],"examples":[{"example":"彼は車を壁にぶつけました。","example_reading":"かれはくるまをかべにぶつけました。","example_meaning":"Anh ấy đã đâm xe vào tường."},{"example":"私は机の角に、足をぶつけました。","example_reading":"わたしはつくえのかどに、あしをぶつけました。","example_meaning":"Tôi đã đụng chân vào góc bàn."}]}],"level":"n4"},
{"word":"合う・合わせる","reading":"あう・あわせる","pair":[{"word":"合う","reading":"あう","meaning":"khớp, vừa, hợp (tự nhiên) [自動詞]","notes":["Vật tự khớp/vừa với nhau → 足に合う."],"examples":[{"example":"この靴は、私の足にぴったり合います。","example_reading":"このくつは、わたしのあしにぴったりあいます。","example_meaning":"Đôi giày này vừa khít chân tôi."},{"example":"計算が合いません。","example_reading":"けいさんがあいません。","example_meaning":"Phép tính không khớp."}]},{"word":"合わせる","reading":"あわせる","meaning":"làm cho khớp, gộp lại (có tác động) [他動詞]","notes":["Có người chủ động chỉnh cho khớp/gộp lại → 時間を合わせる."],"examples":[{"example":"彼は時計を正しい時間に合わせました。","example_reading":"かれはとけいをただしいじかんにあわせました。","example_meaning":"Anh ấy chỉnh đồng hồ cho đúng giờ."},{"example":"みんなで、力を合わせて、頑張りましょう。","example_reading":"みんなで、ちからをあわせて、がんばりましょう。","example_meaning":"Mọi người hãy cùng chung sức cố gắng."}]}],"level":"n4"},
{"word":"飛ぶ・飛ばす","reading":"とぶ・とばす","pair":[{"word":"飛ぶ","reading":"とぶ","meaning":"bay (tự nhiên) [自動詞]","notes":["Chủ thể tự bay → 飛行機が飛ぶ."],"examples":[{"example":"飛行機が、東京に向かって飛んでいます。","example_reading":"ひこうきが、とうきょうにむかってとんでいます。","example_meaning":"Máy bay đang bay hướng về Tokyo."},{"example":"風で、帽子が飛んでいきました。","example_reading":"かぜで、ぼうしがとんでいきました。","example_meaning":"Mũ bị gió thổi bay đi."}]},{"word":"飛ばす","reading":"とばす","meaning":"làm bay, phóng đi (có tác động) [他動詞]","notes":["Có người chủ động làm bay/phóng → 車を飛ばす."],"examples":[{"example":"子供は、紙飛行機を飛ばしました。","example_reading":"こどもは、かみひこうきをとばしました。","example_meaning":"Đứa trẻ đã phi chiếc máy bay giấy."},{"example":"彼は車を飛ばして、空港へ向かいました。","example_reading":"かれはくるまをとばして、くうこうへむかいました。","example_meaning":"Anh ấy phóng xe đến sân bay."}]}],"level":"n4"},
{"word":"教わる・教える","reading":"おそわる・おしえる","pair":[{"word":"教わる","reading":"おそわる","meaning":"được dạy, được chỉ (tự nhiên) [自動詞]","notes":["Phía người học, nhận kiến thức từ người khác → 先生に教わる. (Không phải tự động từ hoàn toàn, nhưng là phía đối ứng của 教える.)"],"examples":[{"example":"私は先生から、漢字を教わりました。","example_reading":"わたしはせんせいから、かんじをおそわりました。","example_meaning":"Tôi đã được thầy dạy chữ Hán."},{"example":"友達から、料理の作り方を教わりました。","example_reading":"ともだちから、りょうりのつくりかたをおそわりました。","example_meaning":"Tôi đã được bạn chỉ cách nấu ăn."}]},{"word":"教える","reading":"おしえる","meaning":"dạy, chỉ cho (có tác động) [他動詞]","notes":["Phía người dạy, chủ động truyền đạt → 日本語を教える."],"examples":[{"example":"先生は学生に、日本語を教えています。","example_reading":"せんせいはがくせいに、にほんごをおしえています。","example_meaning":"Thầy giáo đang dạy tiếng Nhật cho học sinh."},{"example":"駅への行き方を、教えてください。","example_reading":"えきへのいきかたを、おしえてください。","example_meaning":"Xin hãy chỉ giúp tôi cách đi đến ga."}]}],"level":"n4"},
{"word":"寝る・寝かせる","reading":"ねる・ねかせる","pair":[{"word":"寝る","reading":"ねる","meaning":"ngủ (tự nhiên) [自動詞]","notes":["Chủ thể tự ngủ → 十一時に寝る."],"examples":[{"example":"私は毎晩、十一時に寝ます。","example_reading":"わたしはまいばん、じゅういちじにねます。","example_meaning":"Mỗi tối tôi ngủ lúc 11 giờ."},{"example":"昨日は、疲れて、すぐに寝ました。","example_reading":"きのうは、つかれて、すぐにねました。","example_meaning":"Hôm qua mệt nên tôi ngủ ngay."}]},{"word":"寝かせる","reading":"ねかせる","meaning":"cho ngủ, đặt nằm xuống (có tác động) [他動詞]","notes":["Có người chủ động cho ai ngủ/đặt nằm → 子供を寝かせる. Dạng sai khiến của 寝る."],"examples":[{"example":"母は、赤ちゃんをベッドに寝かせました。","example_reading":"ははは、あかちゃんをべっどにねかせました。","example_meaning":"Mẹ đặt em bé nằm xuống giường."},{"example":"私は、病気の友達を、部屋で寝かせました。","example_reading":"わたしは、びょうきのともだちを、へやでねかせました。","example_meaning":"Tôi cho người bạn bị ốm nằm nghỉ trong phòng."}]}],"level":"n4"},
{"word":"笑う・笑わせる","reading":"わらう・わらわせる","pair":[{"word":"笑う","reading":"わらう","meaning":"cười (tự nhiên) [自動詞]","notes":["Chủ thể tự cười → 大声で笑う."],"examples":[{"example":"みんなが、大きな声で笑いました。","example_reading":"みんなが、おおきなこえでわらいました。","example_meaning":"Mọi người cười thật to."},{"example":"赤ちゃんが、にこにこ笑っています。","example_reading":"あかちゃんが、にこにこわらっています。","example_meaning":"Em bé đang cười tươi."}]},{"word":"笑わせる","reading":"わらわせる","meaning":"làm cho cười (có tác động) [他動詞]","notes":["Có người chủ động làm người khác cười → 人を笑わせる. Dạng sai khiến của 笑う."],"examples":[{"example":"彼は、面白い話で、みんなを笑わせました。","example_reading":"かれは、おもしろいはなしで、みんなをわらわせました。","example_meaning":"Anh ấy kể chuyện hài làm mọi người cười."},{"example":"私は子供を笑わせるのが、好きです。","example_reading":"わたしはこどもをわらわせるのが、すきです。","example_meaning":"Tôi thích làm trẻ con cười."}]}],"level":"n4"},
{"word":"着る・着せる","reading":"きる・きせる","pair":[{"word":"着る","reading":"きる","meaning":"mặc (tự nhiên) [自動詞]","notes":["Chủ thể tự mặc đồ → 服を着る."],"examples":[{"example":"私は毎朝、制服を着ます。","example_reading":"わたしはまいあさ、せいふくをきます。","example_meaning":"Mỗi sáng tôi mặc đồng phục."},{"example":"寒いので、コートを着ました。","example_reading":"さむいので、こーとをきました。","example_meaning":"Trời lạnh nên tôi mặc áo khoác."}]},{"word":"着せる","reading":"きせる","meaning":"mặc đồ cho ai (có tác động) [他動詞]","notes":["Có người chủ động mặc đồ cho người khác → 子供に服を着せる."],"examples":[{"example":"母は、赤ちゃんに服を着せました。","example_reading":"はははあかちゃんにふくをきせました。","example_meaning":"Mẹ mặc quần áo cho em bé."},{"example":"寒いので、子供に厚いコートを着せました。","example_reading":"さむいので、こどもにあついこーとをきせました。","example_meaning":"Trời lạnh nên tôi mặc áo khoác dày cho con."}]}],"level":"n4"},
{"word":"鳴る・鳴らす","reading":"なる・ならす","pair":[{"word":"鳴る","reading":"なる","meaning":"kêu, reo (tự nhiên) [自動詞]","notes":["Âm thanh tự phát ra → 電話が鳴る."],"examples":[{"example":"電話が鳴っています。","example_reading":"でんわがなっています。","example_meaning":"Điện thoại đang reo."},{"example":"学校のチャイムが、鳴りました。","example_reading":"がっこうのちゃいむが、なりました。","example_meaning":"Chuông trường đã reo."}]},{"word":"鳴らす","reading":"ならす","meaning":"làm kêu, bấm chuông (có tác động) [他動詞]","notes":["Có người chủ động làm phát ra âm thanh → ベルを鳴らす."],"examples":[{"example":"私は、玄関のベルを鳴らしました。","example_reading":"わたしは、げんかんのべるをならしました。","example_meaning":"Tôi đã bấm chuông cửa."},{"example":"彼は、車のクラクションを鳴らしました。","example_reading":"かれは、くるまのくらくしょんをならしました。","example_meaning":"Anh ấy đã bấm còi xe."}]}],"level":"n4"},
{"word":"伝わる・伝える","reading":"つたわる・つたえる","pair":[{"word":"伝わる","reading":"つたわる","meaning":"được truyền đạt, lan truyền [自動詞]","notes":["Tập trung vào kết quả 'đến được' → 気持ちが伝わる."],"examples":[{"example":"私の気持ちが彼に伝わりました。","example_reading":"わたしのきもちがかれにつたわりました。","example_meaning":"Tình cảm của tôi đã được truyền đến anh ấy."},{"example":"このニュースは、すぐに町中に伝わりました。","example_reading":"このにゅーすは、すぐにまちじゅうにつたわりました。","example_meaning":"Tin này đã lan ra khắp thị trấn ngay lập tức."}]},{"word":"伝える","reading":"つたえる","meaning":"truyền đạt [他動詞]","notes":["Tập trung vào hành động chủ động truyền đạt → 気持ちを伝える."],"examples":[{"example":"私は自分の気持ちを彼に伝えました。","example_reading":"わたしはじぶんのきもちをかれにつたえました。","example_meaning":"Tôi đã truyền đạt tình cảm của mình cho anh ấy."},{"example":"社長に、私が遅れると伝えてください。","example_reading":"しゃちょうに、わたしがおくれるとつたえてください。","example_meaning":"Xin hãy nhắn với giám đốc rằng tôi sẽ đến trễ."}]}],"level":"n3"},
{"word":"折れる・折る","reading":"おれる・おる","pair":[{"word":"折れる","reading":"おれる","meaning":"gãy (tự nhiên) [自動詞]","notes":["Cành tự gãy do gió, không rõ ai làm → 枝が折れる."],"examples":[{"example":"木の枝が折れました。","example_reading":"きのえだがおれました。","example_meaning":"Cành cây đã gãy."},{"example":"スキーで転んで、足の骨が折れました。","example_reading":"すきーでころんで、あしのほねがおれました。","example_meaning":"Tôi ngã khi trượt tuyết và bị gãy xương chân."}]},{"word":"折る","reading":"おる","meaning":"bẻ gãy [他動詞]","notes":["彼 là người chủ động bẻ → 枝を折る."],"examples":[{"example":"彼は木の枝を折りました。","example_reading":"かれはきのえだをおりました。","example_meaning":"Anh ấy đã bẻ gãy cành cây."},{"example":"紙を半分に折って、飛行機を作りました。","example_reading":"かみをはんぶんにおって、ひこうきをつくりました。","example_meaning":"Tôi gấp đôi tờ giấy lại và làm thành chiếc máy bay."}]}],"level":"n3"},
{"word":"腐る・腐らせる","reading":"くさる・くさらせる","pair":[{"word":"腐る","reading":"くさる","meaning":"bị thối, hỏng (không có tha động từ tương ứng) [自動詞]","notes":["腐る không có tha động từ hình thái tương ứng."],"examples":[{"example":"野菜が腐りました。","example_reading":"やさいがくさりました。","example_meaning":"Rau đã bị thối."},{"example":"夏は、食べ物がすぐ腐ります。","example_reading":"なつは、たべものがすぐくさります。","example_meaning":"Mùa hè, đồ ăn rất mau bị thiu."}]},{"word":"腐らせる","reading":"くさらせる","meaning":"làm cho hỏng (dùng thể sai khiến) [他動詞]","notes":["Theo lý thuyết: khi tự động từ không có tha động từ, dùng THỂ SAI KHIẾN (使役形) 腐らせる để diễn tả 'làm cho ai/cái gì bị...'."],"examples":[{"example":"忙しくて、野菜を腐らせてしまいました。","example_reading":"いそがしくて、やさいをくさらせてしまいました。","example_meaning":"Vì bận nên tôi đã lỡ để rau bị hỏng."},{"example":"冷蔵庫に入れ忘れて、肉を腐らせてしまいました。","example_reading":"れいぞうこにいれわすれて、にくをくさらせてしまいました。","example_meaning":"Tôi quên bỏ vào tủ lạnh nên đã để thịt bị hỏng mất."}]}],"level":"n3"},
{"word":"凍る・凍らせる","reading":"こおる・こおらせる","pair":[{"word":"凍る","reading":"こおる","meaning":"đóng băng (không có tha động từ tương ứng) [自動詞]","notes":["凍る là tự động từ vô ý chí, không có dạng tha động từ riêng."],"examples":[{"example":"水が凍りました。","example_reading":"みずがこおりました。","example_meaning":"Nước đã đóng băng."},{"example":"寒い朝は、道が凍って滑りやすいです。","example_reading":"さむいあさは、みちがこおってすべりやすいです。","example_meaning":"Những sáng lạnh, đường đóng băng nên rất dễ trơn trượt."}]},{"word":"凍らせる","reading":"こおらせる","meaning":"làm đông (dùng thể sai khiến) [他動詞]","notes":["Dùng 凍らせる (thể sai khiến của 凍る) để nói 'làm cho... đông lại'."],"examples":[{"example":"ジュースを凍らせて、シャーベットを作ります。","example_reading":"じゅーすをこおらせて、しゃーべっとをつくります。","example_meaning":"Tôi làm đông nước ép để làm món kem đá bào."},{"example":"ペットボトルの水を凍らせて、持って行きます。","example_reading":"ぺっとぼとるのみずをこおらせて、もっていきます。","example_meaning":"Tôi đông lạnh nước trong chai rồi mang đi."}]}],"level":"n3"},
{"word":"空を飛ぶ","reading":"そらをとぶ","meaning":"bay qua bầu trời (tự động từ dùng với を chỉ nơi đi qua)","note":"⚠ 飛ぶ vẫn là TỰ ĐỘNG TỪ dù đi với を. 「空を」ở đây không phải mục đích ngữ mà chỉ nơi chốn đi qua/thông qua, giống 「高速道路を走る」「橋を渡る」.","example":"鳥が空を飛んでいます。","example_reading":"とりがそらをとんでいます。","example_meaning":"Con chim đang bay trên bầu trời.","level":"n3"},
{"word":"部屋を出る","reading":"へやをでる","meaning":"ra khỏi phòng (tự động từ dùng với を chỉ điểm xuất phát)","note":"⚠ 出る là TỰ ĐỘNG TỪ. 「部屋を」ở đây chỉ điểm xuất phát/khởi điểm, không phải đối tượng bị tác động, giống 「タクシーを降りる」「大学を卒業する」.","example":"彼は静かに部屋を出ました。","example_reading":"かれはしずかにへやをでました。","example_meaning":"Anh ấy lặng lẽ ra khỏi phòng.","level":"n3"},
{"word":"橋を渡る","reading":"はしをわたる","meaning":"đi qua cầu (tự động từ dùng với を chỉ nơi đi qua)","note":"⚠ 渡る là TỰ ĐỘNG TỪ. 「橋を」chỉ nơi đi qua/thông qua, không phải mục đích ngữ.","example":"毎朝、この橋を渡って学校へ行きます。","example_reading":"まいあさ、このはしをわたってがっこうへいきます。","example_meaning":"Sáng nào tôi cũng đi qua cây cầu này để đến trường.","level":"n3"},
{"word":"浮く・浮かべる","reading":"うく・うかべる","pair":[{"word":"浮く","reading":"うく","meaning":"nổi lên, trôi lên (tự nhiên) [自動詞]","notes":["Vật tự nổi lên → ボールが浮く."],"examples":[{"example":"ボールが水面に浮きました。","example_reading":"ぼーるがすいめんにうきました。","example_meaning":"Quả bóng đã nổi lên mặt nước."},{"example":"油は水に浮きます。","example_reading":"あぶらはみずにうきます。","example_meaning":"Dầu nổi trên mặt nước."}]},{"word":"浮かべる","reading":"うかべる","meaning":"đặt nổi, cho nổi (có tác động) [他動詞]","notes":["Có người chủ động làm cho vật nổi → 船を浮かべる."],"examples":[{"example":"彼は小さな船を川に浮かべました。","example_reading":"かれはちいさなふねをかわにうかべました。","example_meaning":"Anh ấy đã đặt chiếc thuyền nhỏ nổi trên sông."},{"example":"彼女は、やさしい笑顔を浮かべました。","example_reading":"かのじょは、やさしいえがおをうかべました。","example_meaning":"Cô ấy nở một nụ cười dịu dàng."}]}],"level":"n3"},
{"word":"揺れる・揺らす","reading":"ゆれる・ゆらす","pair":[{"word":"揺れる","reading":"ゆれる","meaning":"rung, lắc, dao động (tự nhiên) [自動詞]","notes":["Cây tự rung do gió → 木が揺れる."],"examples":[{"example":"木が風で揺れています。","example_reading":"きがかぜでゆれています。","example_meaning":"Cây đang gió rung."},{"example":"船が大きく揺れて、気分が悪くなりました。","example_reading":"ふねがおおきくゆれて、きぶんがわるくなりました。","example_meaning":"Thuyền chao đảo mạnh khiến tôi thấy khó chịu trong người."}]},{"word":"揺らす","reading":"ゆらす","meaning":"lắc, làm rung (có tác động) [他動詞]","notes":["Có người chủ động làm rung → 肩を揺らす."],"examples":[{"example":"彼は肩を揺らしました。","example_reading":"かれはかたをゆらしました。","example_meaning":"Anh ấy đã lắc vai."},{"example":"母は赤ちゃんを抱いて、そっと揺らしています。","example_reading":"はははあかちゃんをだいて、そっとゆらしています。","example_meaning":"Mẹ bế em bé và nhẹ nhàng đung đưa."}]}],"level":"n3"},
{"word":"曲がる・曲げる","reading":"まがる・まげる","pair":[{"word":"曲がる","reading":"まがる","meaning":"rẽ, cong, uốn (tự nhiên) [自動詞]","notes":["Đường tự rẽ → 道が曲がる."],"examples":[{"example":"道が右に曲がっています。","example_reading":"みちがみぎにまがっています。","example_meaning":"Con đường rẽ phải."},{"example":"おじいさんは、年をとって腰が曲がってきました。","example_reading":"おじいさんは、としをとってこしがまがってきました。","example_meaning":"Ông tôi tuổi cao nên lưng đã bắt đầu còng xuống."}]},{"word":"曲げる","reading":"まげる","meaning":"uốn cong, bẻ gập (có tác động) [他動詞]","notes":["Có người chủ động uốn cong → 金属を曲げる."],"examples":[{"example":"彼は金属を曲げました。","example_reading":"かれはきんぞくをまげました。","example_meaning":"Anh ấy đã uốn cong kim loại."},{"example":"膝を曲げて、ゆっくり座ってください。","example_reading":"ひざをまげて、ゆっくりすわってください。","example_meaning":"Hãy gập đầu gối rồi từ từ ngồi xuống."}]}],"level":"n3"},
{"word":"回る・回す","reading":"まわる・まわす","pair":[{"word":"回る","reading":"まわる","meaning":"quay, xoay tròn (tự nhiên) [自動詞]","notes":["Vật tự xoay tròn → 地球が回る."],"examples":[{"example":"地球は太陽の周りを回ります。","example_reading":"ちきゅうはたいようのまわりをまわります。","example_meaning":"Trái đất quay quanh mặt trời."},{"example":"このおもちゃは、ボタンを押すと回ります。","example_reading":"このおもちゃは、ぼたんをおすとまわります。","example_meaning":"Đồ chơi này cứ ấn nút là sẽ quay."}]},{"word":"回す","reading":"まわす","meaning":"quay, xoay (có tác động) [他動詞]","notes":["Có người chủ động xoay → 鍵を回す."],"examples":[{"example":"私は鍵を回しました。","example_reading":"わたしはかぎをまわしました。","example_meaning":"Tôi đã xoay khóa."},{"example":"ネジを右に回すと、固くなります。","example_reading":"ねじをみぎにまわすと、かたくなります。","example_meaning":"Vặn ốc sang phải thì nó sẽ chặt lại."}]}],"level":"n3"},
{"word":"伸びる・伸ばす","reading":"のびる・のばす","pair":[{"word":"伸びる","reading":"のびる","meaning":"mở rộng, dài ra (tự nhiên) [自動詞]","notes":["Tóc tự dài ra → 髪が伸びる."],"examples":[{"example":"髪が伸びました。","example_reading":"かみがのびました。","example_meaning":"Tóc đã dài ra."},{"example":"子供の背が、一年で五センチ伸びました。","example_reading":"こどものせが、いちねんでごせんちのびました。","example_meaning":"Chiều cao của con tôi đã tăng thêm 5 cm trong một năm."}]},{"word":"伸ばす","reading":"のばす","meaning":"kéo dài, mở rộng (có tác động) [他動詞]","notes":["Có người chủ động kéo dài → 手を伸ばす."],"examples":[{"example":"私は手を伸ばしました。","example_reading":"わたしはてをのばしました。","example_meaning":"Tôi đã duỗi tay ra."},{"example":"髪を伸ばしたいので、しばらく切りません。","example_reading":"かみをのばしたいので、しばらくきりません。","example_meaning":"Vì muốn nuôi tóc dài nên tôi sẽ chưa cắt trong một thời gian."}]}],"level":"n3"},
{"word":"縮む・縮める","reading":"ちぢむ・ちぢめる","pair":[{"word":"縮む","reading":"ちぢむ","meaning":"co lại, rút lại (tự nhiên) [自動詞]","notes":["Vải tự co lại → 布が縮む."],"examples":[{"example":"布が乾くと縮みました。","example_reading":"ぬのがかわくとちぢみました。","example_meaning":"Vải đã co lại khi khô."},{"example":"セーターを洗ったら、縮んでしまいました。","example_reading":"せーたーをあらったら、ちぢんでしまいました。","example_meaning":"Giặt cái áo len xong thì nó bị co lại mất rồi."}]},{"word":"縮める","reading":"ちぢめる","meaning":"co lại, rút ngắn (có tác động) [他動詞]","notes":["Có người chủ động co lại → 長さを縮める."],"examples":[{"example":"彼はスカートの丈を縮めました。","example_reading":"かれはすかーとのたけをちぢめました。","example_meaning":"Anh ấy đã rút ngắn chiều dài váy."},{"example":"社長は、会議の時間を三十分に縮めました。","example_reading":"しゃちょうは、かいぎのじかんをさんじゅっぷんにちぢめました。","example_meaning":"Giám đốc đã rút ngắn thời gian họp xuống còn 30 phút."}]}],"level":"n3"},
{"word":"広がる・広げる","reading":"ひろがる・ひろげる","pair":[{"word":"広がる","reading":"ひろがる","meaning":"mở rộng, lan ra (tự nhiên) [自動詞]","notes":["Thông tin tự lan ra → 情報が広がる."],"examples":[{"example":"情報が広がっています。","example_reading":"じょうほうがひろがっています。","example_meaning":"Thông tin đang lan rộng."},{"example":"目の前に、きれいな海が広がっています。","example_reading":"めのまえに、きれいなうみがひろがっています。","example_meaning":"Trước mắt tôi là biển xanh đẹp trải rộng ra."}]},{"word":"広げる","reading":"ひろげる","meaning":"mở rộng, trải ra (có tác động) [他動詞]","notes":["Có người chủ động mở rộng → 新聞を広げる."],"examples":[{"example":"私は新聞を広げました。","example_reading":"わたしはしんぶんをひろげました。","example_meaning":"Tôi đã trải tờ báo ra."},{"example":"友達の輪を広げるために、サークルに入りました。","example_reading":"ともだちのわをひろげるために、さーくるにはいりました。","example_meaning":"Để mở rộng vòng bạn bè, tôi đã gia nhập câu lạc bộ."}]}],"level":"n3"},
{"word":"当たる・当てる","reading":"あたる・あてる","pair":[{"word":"当たる","reading":"あたる","meaning":"trúng, va phải (tự nhiên) [自動詞]","notes":["Vật tự trúng/va vào một điểm → ボールが当たる."],"examples":[{"example":"ボールが窓に当たりました。","example_reading":"ぼーるがまどにあたりました。","example_meaning":"Quả bóng đã trúng cửa sổ."},{"example":"宝くじが当たって、みんなびっくりしました。","example_reading":"たからくじがあたって、みんなびっくりしました。","example_meaning":"Trúng xổ số nên ai cũng giật mình."}]},{"word":"当てる","reading":"あてる","meaning":"làm trúng, áp vào (có tác động) [他動詞]","notes":["Có người chủ động ném trúng/áp vào → 的に当てる."],"examples":[{"example":"彼はボールを的に当てました。","example_reading":"かれはぼーるをまとにあてました。","example_meaning":"Anh ấy đã ném bóng trúng mục tiêu."},{"example":"額に手を当てて、熱を測りました。","example_reading":"ひたいにてをあてて、ねつをはかりました。","example_meaning":"Tôi đặt tay lên trán để đo sốt."}]}],"level":"n3"},
{"word":"沈む・沈める","reading":"しずむ・しずめる","pair":[{"word":"沈む","reading":"しずむ","meaning":"chìm, lặn (tự nhiên) [自動詞]","notes":["Mặt trời/tàu tự chìm xuống → 太陽が沈む."],"examples":[{"example":"太陽が西に沈みます。","example_reading":"たいようがにしにしずみます。","example_meaning":"Mặt trời lặn ở phía tây."},{"example":"古い船が海に沈みました。","example_reading":"ふるいふねがうみにしずみました。","example_meaning":"Con tàu cũ đã chìm xuống biển."}]},{"word":"沈める","reading":"しずめる","meaning":"dìm xuống, làm chìm (có tác động) [他動詞]","notes":["Có người chủ động dìm vật xuống → 石を沈める."],"examples":[{"example":"彼は石を池に沈めました。","example_reading":"かれはいしをいけにしずめました。","example_meaning":"Anh ấy đã thả viên đá chìm xuống ao."},{"example":"お風呂で、肩まで体を沈めました。","example_reading":"おふろで、かたまでからだをしずめました。","example_meaning":"Trong bồn tắm tôi ngâm mình đến tận vai."}]}],"level":"n3"},
{"word":"倒れる・倒す","reading":"たおれる・たおす","pair":[{"word":"倒れる","reading":"たおれる","meaning":"đổ, ngã (tự nhiên) [自動詞]","notes":["Vật/người tự đổ xuống → 木が倒れる."],"examples":[{"example":"強い風で、木が倒れました。","example_reading":"つよいかぜで、きがたおれました。","example_meaning":"Cây đổ vì gió mạnh."},{"example":"疲れすぎて、道で倒れてしまいました。","example_reading":"つかれすぎて、みちでたおれてしまいました。","example_meaning":"Mệt quá nên tôi ngã quỵ ngoài đường."}]},{"word":"倒す","reading":"たおす","meaning":"làm đổ, đánh bại (có tác động) [他動詞]","notes":["Có người chủ động làm đổ/đánh bại → 木を倒す."],"examples":[{"example":"彼は木を倒しました。","example_reading":"かれはきをたおしました。","example_meaning":"Anh ấy đã đốn ngã cái cây."},{"example":"試合で、強いチームを倒しました。","example_reading":"しあいで、つよいちーむをたおしました。","example_meaning":"Trong trận đấu, chúng tôi đã đánh bại đội mạnh."}]}],"level":"n3"},
{"word":"濡れる・濡らす","reading":"ぬれる・ぬらす","pair":[{"word":"濡れる","reading":"ぬれる","meaning":"bị ướt (tự nhiên) [自動詞]","notes":["Vật tự bị ướt → 服が濡れる."],"examples":[{"example":"雨で、服が濡れました。","example_reading":"あめで、ふくがぬれました。","example_meaning":"Quần áo bị ướt vì mưa."},{"example":"傘がなくて、髪が濡れてしまいました。","example_reading":"かさがなくて、かみがぬれてしまいました。","example_meaning":"Không có ô nên tóc bị ướt mất."}]},{"word":"濡らす","reading":"ぬらす","meaning":"làm ướt (có tác động) [他動詞]","notes":["Có người chủ động làm ướt → タオルを濡らす."],"examples":[{"example":"子供が服を水で濡らしました。","example_reading":"こどもがふくをみずでぬらしました。","example_meaning":"Đứa trẻ làm ướt quần áo bằng nước."},{"example":"タオルを濡らして、顔をふきました。","example_reading":"たおるをぬらして、かおをふきました。","example_meaning":"Tôi làm ướt khăn rồi lau mặt."}]}],"level":"n3"},
{"word":"燃える・燃やす","reading":"もえる・もやす","pair":[{"word":"燃える","reading":"もえる","meaning":"cháy (tự nhiên) [自動詞]","notes":["Vật tự cháy → ごみが燃える."],"examples":[{"example":"ごみが燃えています。","example_reading":"ごみがもえています。","example_meaning":"Rác đang cháy."},{"example":"火事で、古い家が燃えました。","example_reading":"かじで、ふるいいえがもえました。","example_meaning":"Ngôi nhà cũ đã cháy trong vụ hỏa hoạn."}]},{"word":"燃やす","reading":"もやす","meaning":"đốt (có tác động) [他動詞]","notes":["Có người chủ động đốt → 手紙を燃やす."],"examples":[{"example":"彼は庭で枯れ葉を燃やしました。","example_reading":"かれはにわでかれはをもやしました。","example_meaning":"Anh ấy đã đốt lá khô trong vườn."},{"example":"いらない手紙を燃やしました。","example_reading":"いらないてがみをもやしました。","example_meaning":"Tôi đã đốt những lá thư không cần."}]}],"level":"n3"},
{"word":"繋がる・繋ぐ","reading":"つながる・つなぐ","pair":[{"word":"繋がる","reading":"つながる","meaning":"được nối, kết nối (tự nhiên) [自動詞]","notes":["Trạng thái được nối liền → 電話が繋がる."],"examples":[{"example":"電話がやっと繋がりました。","example_reading":"でんわがやっとつながりました。","example_meaning":"Cuối cùng điện thoại cũng kết nối được."},{"example":"この道は、駅に繋がっています。","example_reading":"このみちは、えきにつながっています。","example_meaning":"Con đường này nối thẳng đến nhà ga."}]},{"word":"繋ぐ","reading":"つなぐ","meaning":"nối, buộc, nắm (có tác động) [他動詞]","notes":["Có người chủ động nối/buộc → 手を繋ぐ."],"examples":[{"example":"彼は犬を木に繋ぎました。","example_reading":"かれはいぬをきにつなぎました。","example_meaning":"Anh ấy đã buộc con chó vào cây."},{"example":"二人は手を繋いで、歩いています。","example_reading":"ふたりはてをつないで、あるいています。","example_meaning":"Hai người đang nắm tay nhau đi bộ."}]}],"level":"n3"},
{"word":"外れる・外す","reading":"はずれる・はずす","pair":[{"word":"外れる","reading":"はずれる","meaning":"bị tuột, trật, sai (tự nhiên) [自動詞]","notes":["Vật tự tuột ra hoặc dự đoán bị sai → ボタンが外れる."],"examples":[{"example":"ボタンが外れました。","example_reading":"ぼたんがはずれました。","example_meaning":"Cúc áo đã bị tuột."},{"example":"天気予報が外れて、雨が降りました。","example_reading":"てんきよほうがはずれて、あめがふりました。","example_meaning":"Dự báo thời tiết sai nên trời đã mưa."}]},{"word":"外す","reading":"はずす","meaning":"tháo ra, rời khỏi (có tác động) [他動詞]","notes":["Có người chủ động tháo ra → めがねを外す."],"examples":[{"example":"彼はめがねを外しました。","example_reading":"かれはめがねをはずしました。","example_meaning":"Anh ấy đã tháo kính ra."},{"example":"会議のあいだ、少し席を外します。","example_reading":"かいぎのあいだ、すこしせきをはずします。","example_meaning":"Trong lúc họp tôi xin phép rời chỗ một chút."}]}],"level":"n3"},
{"word":"抜ける・抜く","reading":"ぬける・ぬく","pair":[{"word":"抜ける","reading":"ぬける","meaning":"rụng, tuột ra, thoát ra (tự nhiên) [自動詞]","notes":["Vật tự rụng/tuột ra → 歯が抜ける."],"examples":[{"example":"髪の毛が抜けました。","example_reading":"かみのけがぬけました。","example_meaning":"Tóc đã rụng."},{"example":"歯が抜けて、子供が笑っています。","example_reading":"はがぬけて、こどもがわらっています。","example_meaning":"Răng bị rụng, đứa trẻ vừa cười."}]},{"word":"抜く","reading":"ぬく","meaning":"nhổ, rút ra (có tác động) [他動詞]","notes":["Có người chủ động nhổ/rút → 草を抜く."],"examples":[{"example":"医者が虫歯を抜きました。","example_reading":"いしゃがむしばをぬきました。","example_meaning":"Bác sĩ đã nhổ chiếc răng sâu."},{"example":"庭の草を抜きました。","example_reading":"にわのくさをぬきました。","example_meaning":"Tôi đã nhổ cỏ trong vườn."}]}],"level":"n3"},
{"word":"混ざる・混ぜる","reading":"まざる・まぜる","pair":[{"word":"混ざる","reading":"まざる","meaning":"bị trộn lẫn (tự nhiên) [自動詞]","notes":["Hai thứ tự hòa lẫn vào nhau → 色が混ざる."],"examples":[{"example":"水と油は混ざりません。","example_reading":"みずとあぶらはまざりません。","example_meaning":"Nước và dầu không trộn lẫn được."},{"example":"絵の具の色が混ざって、新しい色になりました。","example_reading":"えのぐのいろがまざって、あたらしいいろになりました。","example_meaning":"Màu thuốc vẽ hòa vào nhau thành màu mới."}]},{"word":"混ぜる","reading":"まぜる","meaning":"trộn, pha (có tác động) [他動詞]","notes":["Có người chủ động trộn → 卵と砂糖を混ぜる."],"examples":[{"example":"卵と砂糖を混ぜてください。","example_reading":"たまごとさとうをまぜてください。","example_meaning":"Hãy trộn trứng với đường."},{"example":"コーヒーにミルクを混ぜて飲みます。","example_reading":"こーひーにみるくをまぜてのみます。","example_meaning":"Tôi pha sữa vào cà phê rồi uống."}]}],"level":"n3"},
{"word":"重なる・重ねる","reading":"かさなる・かさねる","pair":[{"word":"重なる","reading":"かさなる","meaning":"chồng lên nhau, trùng (tự nhiên) [自動詞]","notes":["Vật tự chồng lên nhau hoặc sự việc trùng nhau → 本が重なる."],"examples":[{"example":"机の上に、本が重なっています。","example_reading":"つくえのうえに、ほんがかさなっています。","example_meaning":"Sách chất chồng lên nhau trên bàn."},{"example":"休みと祝日が重なりました。","example_reading":"やすみとしゅくじつがかさなりました。","example_meaning":"Ngày nghỉ trùng với ngày lễ."}]},{"word":"重ねる","reading":"かさねる","meaning":"xếp chồng, lặp lại (có tác động) [他動詞]","notes":["Có người chủ động xếp chồng → 椅子を重ねる."],"examples":[{"example":"彼は椅子を重ねて、部屋の隅に置きました。","example_reading":"かれはいすをかさねて、へやのすみにおきました。","example_meaning":"Anh ấy xếp chồng ghế rồi để ở góc phòng."},{"example":"失敗を重ねても、あきらめません。","example_reading":"しっぱいをかさねても、あきらめません。","example_meaning":"Dù thất bại nhiều lần tôi cũng không bỏ cuộc."}]}],"level":"n3"},
{"word":"積もる・積む","reading":"つもる・つむ","pair":[{"word":"積もる","reading":"つもる","meaning":"chất đống, phủ dày (tự nhiên) [自動詞]","notes":["Tuyết/bụi tự đọng lại thành lớp → 雪が積もる."],"examples":[{"example":"山に雪が積もりました。","example_reading":"やまにゆきがつもりました。","example_meaning":"Tuyết đã phủ dày trên núi."},{"example":"机の上に、ほこりが積もっています。","example_reading":"つくえのうえに、ほこりがつもっています。","example_meaning":"Bụi đã đóng dày trên bàn."}]},{"word":"積む","reading":"つむ","meaning":"chất lên, tích lũy (có tác động) [他動詞]","notes":["Có người chủ động chất lên → 荷物を積む."],"examples":[{"example":"彼はトラックに荷物を積みました。","example_reading":"かれはとらっくににもつをつみました。","example_meaning":"Anh ấy đã chất hàng lên xe tải."},{"example":"若いうちに、いろいろな経験を積みたいです。","example_reading":"わかいうちに、いろいろなけいけんをつみたいです。","example_meaning":"Khi còn trẻ tôi muốn tích lũy nhiều kinh nghiệm."}]}],"level":"n3"},
{"word":"埋まる・埋める","reading":"うまる・うめる","pair":[{"word":"埋まる","reading":"うまる","meaning":"bị vùi, bị lấp đầy (tự nhiên) [自動詞]","notes":["Vật tự bị vùi/lấp kín → 席が埋まる."],"examples":[{"example":"雪で、車が半分埋まりました。","example_reading":"ゆきで、くるまがはんぶんうまりました。","example_meaning":"Chiếc xe bị tuyết vùi mất một nửa."},{"example":"今日の会議室は、予定でいっぱい埋まっています。","example_reading":"きょうのかいぎしつは、よていでいっぱいうまっています。","example_meaning":"Phòng họp hôm nay đã kín lịch."}]},{"word":"埋める","reading":"うめる","meaning":"chôn, lấp, điền kín (có tác động) [他動詞]","notes":["Có người chủ động chôn/lấp/điền → 穴を埋める."],"examples":[{"example":"犬が庭に骨を埋めました。","example_reading":"いぬがにわにほねをうめました。","example_meaning":"Con chó đã chôn xương trong vườn."},{"example":"空いている欄を、全部埋めてください。","example_reading":"あいているらんを、ぜんぶうめてください。","example_meaning":"Hãy điền kín tất cả các ô còn trống."}]}],"level":"n3"},
{"word":"詰まる・詰める","reading":"つまる・つめる","pair":[{"word":"詰まる","reading":"つまる","meaning":"bị tắc, bị nghẹt, bị nhồi đầy (tự nhiên) [自動詞]","notes":["Vật tự bị tắc/nghẹt → 鼻が詰まる."],"examples":[{"example":"トイレが詰まってしまいました。","example_reading":"といれがつまってしまいました。","example_meaning":"Toilet bị tắc mất rồi."},{"example":"鼻が詰まって、息が苦しいです。","example_reading":"はながつまって、いきがくるしいです。","example_meaning":"Mũi bị nghẹt nên khó thở."}]},{"word":"詰める","reading":"つめる","meaning":"nhét vào, xếp đầy (có tác động) [他動詞]","notes":["Có người chủ động nhét/xếp đầy → 箱に詰める."],"examples":[{"example":"母は弁当箱にご飯を詰めました。","example_reading":"はははべんとうばこにごはんをつめました。","example_meaning":"Mẹ đã xếp cơm vào hộp cơm."},{"example":"スーツケースに、服を詰めました。","example_reading":"すーつけーすに、ふくをつめました。","example_meaning":"Tôi đã nhét quần áo vào vali."}]}],"level":"n3"},
{"word":"解ける・解く","reading":"とける・とく","pair":[{"word":"解ける","reading":"とける","meaning":"được giải ra, được tháo ra (tự nhiên) [自動詞]","notes":["Vấn đề tự được giải đáp, chú ý kết quả → 問題が解ける."],"examples":[{"example":"問題が解けました。","example_reading":"もんだいがとけました。","example_meaning":"Bài toán đã được giải ra."},{"example":"難しかった謎が、やっと解けました。","example_reading":"むずかしかったなぞが、やっととけました。","example_meaning":"Câu đố khó cuối cùng cũng được giải."}]},{"word":"解く","reading":"とく","meaning":"giải, cởi, tháo (có tác động) [他動詞]","notes":["Có người chủ động giải/cởi → 問題を解く."],"examples":[{"example":"私は難しい問題を解きました。","example_reading":"わたしはむずかしいもんだいをときました。","example_meaning":"Tôi đã giải bài toán khó."},{"example":"彼は荷物のひもを解きました。","example_reading":"かれはにもつのひもをときました。","example_meaning":"Anh ấy đã cởi dây buộc hành lý."}]}],"level":"n3"},
{"word":"揃う・揃える","reading":"そろう・そろえる","pair":[{"word":"揃う","reading":"そろう","meaning":"đủ bộ, đồng đều (tự nhiên) [自動詞]","notes":["Mọi thứ tự có đủ/đồng đều → 全員が揃う."],"examples":[{"example":"全員が揃ったので、会議を始めます。","example_reading":"ぜんいんがそろったので、かいぎをはじめます。","example_meaning":"Mọi người đã đến đủ nên bắt đầu họp."},{"example":"材料が全部揃いました。","example_reading":"ざいりょうがぜんぶそろいました。","example_meaning":"Nguyên liệu đã đủ cả."}]},{"word":"揃える","reading":"そろえる","meaning":"gom cho đủ, xếp cho đều (có tác động) [他動詞]","notes":["Có người chủ động gom đủ/xếp đều → 靴を揃える."],"examples":[{"example":"彼は靴をきちんと揃えました。","example_reading":"かれはくつをきちんとそろえました。","example_meaning":"Anh ấy xếp giày ngay ngắn cho đều."},{"example":"書類を揃えて、会議に出ます。","example_reading":"しょるいをそろえて、かいぎにでます。","example_meaning":"Tôi chuẩn bị đủ tài liệu rồi tham dự cuộc họp."}]}],"level":"n3"},
{"word":"整う・整える","reading":"ととのう・ととのえる","pair":[{"word":"整う","reading":"ととのう","meaning":"được chuẩn bị xong, gọn gàng (tự nhiên) [自動詞]","notes":["Trạng thái đã chỉnh tề/sẵn sàng → 準備が整う."],"examples":[{"example":"準備が整いました。","example_reading":"じゅんびがととのいました。","example_meaning":"Việc chuẩn bị đã hoàn tất."},{"example":"部屋の中が、きれいに整っています。","example_reading":"へやのなかが、きれいにととのっています。","example_meaning":"Trong phòng được sắp xếp gọn gàng."}]},{"word":"整える","reading":"ととのえる","meaning":"chuẩn bị, chỉnh sửa cho gọn (có tác động) [他動詞]","notes":["Có người chủ động chỉnh đốn → 髪を整える."],"examples":[{"example":"母は朝、髪を整えました。","example_reading":"はははあさ、かみをととのえました。","example_meaning":"Buổi sáng mẹ đã chỉnh lại mái tóc."},{"example":"試合の前に、体の調子を整えます。","example_reading":"しあいのまえに、からだのちょうしをととのえます。","example_meaning":"Trước trận đấu tôi điều chỉnh thể trạng cho tốt."}]}],"level":"n3"},
{"word":"定まる・定める","reading":"さだまる・さだめる","pair":[{"word":"定まる","reading":"さだまる","meaning":"được định, được ổn định (tự nhiên) [自動詞]","notes":["Trạng thái đã được xác định, chú ý kết quả → 目標が定まる."],"examples":[{"example":"目標がまだ定まっていません。","example_reading":"もくひょうがまださだまっていません。","example_meaning":"Mục tiêu vẫn chưa được xác định."},{"example":"大会の場所がやっと定まりました。","example_reading":"たいかいのばしょがやっとさだまりました。","example_meaning":"Địa điểm tổ chức giải đấu cuối cùng cũng được định."}]},{"word":"定める","reading":"さだめる","meaning":"định ra, quy định (có tác động) [他動詞]","notes":["Có người chủ động đặt ra → 目標を定める."],"examples":[{"example":"私は今年の目標を定めました。","example_reading":"わたしはことしのもくひょうをさだめました。","example_meaning":"Tôi đã đặt ra mục tiêu năm nay."},{"example":"学校は新しいルールを定めました。","example_reading":"がっこうはあたらしいるーるをさだめました。","example_meaning":"Nhà trường đã quy định luật lệ mới."}]}],"level":"n3"},
{"word":"固まる・固める","reading":"かたまる・かためる","pair":[{"word":"固まる","reading":"かたまる","meaning":"đông cứng, vững chắc (tự nhiên) [自動詞]","notes":["Vật tự đông cứng lại → セメントが固まる."],"examples":[{"example":"セメントが固まりました。","example_reading":"せめんとがかたまりました。","example_meaning":"Xi măng đã đông cứng."},{"example":"ゼリーが冷蔵庫で固まりました。","example_reading":"ぜりーがれいぞうこでかたまりました。","example_meaning":"Thạch đã đông lại trong tủ lạnh."}]},{"word":"固める","reading":"かためる","meaning":"làm cứng, củng cố (có tác động) [他動詞]","notes":["Có người chủ động làm cứng/củng cố → 決意を固める."],"examples":[{"example":"彼は土を固めて、道を作りました。","example_reading":"かれはつちをかためて、みちをつくりました。","example_meaning":"Anh ấy nén chặt đất để làm đường."},{"example":"私は大学に行くという決意を固めました。","example_reading":"わたしはだいがくにいくというけついをかためました。","example_meaning":"Tôi đã củng cố quyết tâm học đại học."}]}],"level":"n3"},
{"word":"緩む・緩める","reading":"ゆるむ・ゆるめる","pair":[{"word":"緩む","reading":"ゆるむ","meaning":"bị lỏng ra (tự nhiên) [自動詞]","notes":["Vật tự bị lỏng → ネジが緩む."],"examples":[{"example":"ネジが緩んでいます。","example_reading":"ねじがゆるんでいます。","example_meaning":"Con ốc đang bị lỏng."},{"example":"靴のひもが緩んでしまいました。","example_reading":"くつのひもがゆるんでしまいました。","example_meaning":"Dây giày bị lỏng mất rồi."}]},{"word":"緩める","reading":"ゆるめる","meaning":"nới lỏng (có tác động) [他動詞]","notes":["Có người chủ động nới lỏng → ネクタイを緩める."],"examples":[{"example":"彼はネクタイを緩めました。","example_reading":"かれはねくたいをゆるめました。","example_meaning":"Anh ấy đã nới lỏng cà vạt."},{"example":"食べすぎたので、ベルトを緩めました。","example_reading":"たべすぎたので、べるとをゆるめました。","example_meaning":"Ăn nhiều quá nên tôi nới lỏng thắt lưng."}]}],"level":"n3"},
{"word":"締まる・締める","reading":"しまる・しめる","pair":[{"word":"締まる","reading":"しまる","meaning":"được siết chặt, khít (tự nhiên) [自動詞]","notes":["Vật ở trạng thái siết chặt/khít → ネジが締まる."],"examples":[{"example":"ネジがしっかり締まっています。","example_reading":"ねじがしっかりしまっています。","example_meaning":"Con ốc đã được siết chặt."},{"example":"この蓋はよく締まります。","example_reading":"このふたはよくしまります。","example_meaning":"Cái nắp này đóng rất khít."}]},{"word":"締める","reading":"しめる","meaning":"thắt, siết chặt (có tác động) [他動詞]","notes":["Có người chủ động thắt/siết → ネクタイを締める."],"examples":[{"example":"私はネクタイを締めました。","example_reading":"わたしはねくたいをしめました。","example_meaning":"Tôi đã thắt cà vạt."},{"example":"車に乗ったら、シートベルトを締めてください。","example_reading":"くるまにのったら、しーとべるとをしめてください。","example_meaning":"Khi lên xe hãy thắt dây an toàn."}]}],"level":"n3"},
{"word":"塞がる・塞ぐ","reading":"ふさがる・ふさぐ","pair":[{"word":"塞がる","reading":"ふさがる","meaning":"bị chặn, khép lại (tự nhiên) [自動詞]","notes":["Vật tự bị chặn hoặc vết thương tự khép lại → 傷口が塞がる."],"examples":[{"example":"傷口が塞がりました。","example_reading":"きずぐちがふさがりました。","example_meaning":"Vết thương đã khép miệng."},{"example":"荷物で通路が塞がっています。","example_reading":"にもつでつうろがふさがっています。","example_meaning":"Lối đi bị hành lý chắn mất."}]},{"word":"塞ぐ","reading":"ふさぐ","meaning":"bịt, chặn lại (có tác động) [他動詞]","notes":["Có người chủ động bịt/chặn → 耳を塞ぐ."],"examples":[{"example":"彼は耳を塞ぎました。","example_reading":"かれはみみをふさぎました。","example_meaning":"Anh ấy đã bịt tai lại."},{"example":"トラックが道を塞いでいます。","example_reading":"とらっくがみちをふさいでいます。","example_meaning":"Chiếc xe tải đang chắn ngang đường."}]}],"level":"n3"},
{"word":"満ちる・満たす","reading":"みちる・みたす","pair":[{"word":"満ちる","reading":"みちる","meaning":"đầy, tràn ngập (tự nhiên) [自動詞]","notes":["Không gian tự đầy lên → 水が満ちる."],"examples":[{"example":"部屋が笑い声で満ちています。","example_reading":"へやがわらいごえでみちています。","example_meaning":"Căn phòng tràn ngập tiếng cười."},{"example":"潮が満ちて、海岸の道が消えました。","example_reading":"しおがみちて、かいがんのみちがきえました。","example_meaning":"Thủy triều lên nên con đường ven biển biến mất."}]},{"word":"満たす","reading":"みたす","meaning":"làm đầy, đáp ứng (có tác động) [他動詞]","notes":["Có người chủ động làm đầy/đáp ứng → 条件を満たす."],"examples":[{"example":"彼は水でコップを満たしました。","example_reading":"かれはみずでこっぷをみたしました。","example_meaning":"Anh ấy đã rót đầy cốc nước."},{"example":"この店は、お客様の要望を満たす商品を作っています。","example_reading":"このみせは、おきゃくさまのようぼうをみたすしょうひんをつくっています。","example_meaning":"Cửa hàng này làm sản phẩm đáp ứng nhu cầu của khách."}]}],"level":"n3"},
{"word":"欠ける・欠く","reading":"かける・かく","pair":[{"word":"欠ける","reading":"かける","meaning":"bị sứt, thiếu (tự nhiên) [自動詞]","notes":["Vật tự bị sứt/thiếu một phần → お皿が欠ける."],"examples":[{"example":"お皿の端が欠けています。","example_reading":"おさらのはしがかけています。","example_meaning":"Mép cái đĩa bị sứt."},{"example":"歯が欠けて、歯医者に行きました。","example_reading":"はがかけて、はいしゃにいきました。","example_meaning":"Răng bị sứt nên tôi đã đi nha sĩ."}]},{"word":"欠く","reading":"かく","meaning":"thiếu, bỏ sót (có tác động) [他動詞]","notes":["Chủ thể thiếu mất một điều gì → 礼儀を欠く."],"examples":[{"example":"彼は必要な注意を欠きました。","example_reading":"かれはひつようなちゅういをかきました。","example_meaning":"Anh ấy đã thiếu sự chú ý cần thiết."},{"example":"彼はいつも礼儀を欠いています。","example_reading":"かれはいつもれいぎをかいています。","example_meaning":"Anh ấy lúc nào cũng thiếu lễ độ."}]}],"level":"n3"},
{"word":"余る・余す","reading":"あまる・あます","pair":[{"word":"余る","reading":"あまる","meaning":"thừa, dư (tự nhiên) [自動詞]","notes":["Vật tự dư ra → ご飯が余る."],"examples":[{"example":"ご飯が余りました。","example_reading":"ごはんがあまりました。","example_meaning":"Cơm bị thừa."},{"example":"時間が余ったので、少し休みました。","example_reading":"じかんがあまったので、すこしやすみました。","example_meaning":"Thừa thời gian nên tôi nghỉ một chút."}]},{"word":"余す","reading":"あます","meaning":"để thừa, chừa lại (có tác động) [他動詞]","notes":["Có người chủ động để thừa → 余さず食べる."],"examples":[{"example":"彼は食べ物を余さず食べました。","example_reading":"かれはたべものをあまさずたべました。","example_meaning":"Anh ấy ăn hết sạch đồ ăn không bỏ thừa."},{"example":"試験の時間を十分余して、答案を出しました。","example_reading":"しけんのじかんをじゅうぶんあまして、とうあんをだしました。","example_meaning":"Tôi nộp bài khi còn dư nhiều thời gian thi."}]}],"level":"n3"},
{"word":"散る・散らす","reading":"ちる・ちらす","pair":[{"word":"散る","reading":"ちる","meaning":"rụng, tản mác (tự nhiên) [自動詞]","notes":["Hoa/lá tự rụng → 花が散る."],"examples":[{"example":"風で桜の花が散りました。","example_reading":"かぜでさくらのはながちりました。","example_meaning":"Hoa anh đào rụng vì gió."},{"example":"秋になると、木の葉が散ります。","example_reading":"あきになると、きのはがちります。","example_meaning":"Cứ đến mùa thu lá cây lại rụng."}]},{"word":"散らす","reading":"ちらす","meaning":"làm vương vãi, rải ra (có tác động) [他動詞]","notes":["Có người chủ động làm vương vãi → 紙を散らす."],"examples":[{"example":"子供がおもちゃを散らしました。","example_reading":"こどもがおもちゃをちらしました。","example_meaning":"Đứa trẻ làm vương vãi đồ chơi."},{"example":"彼は紙を床に散らしました。","example_reading":"かれはかみをゆかにちらしました。","example_meaning":"Anh ấy rải giấy ra sàn."}]}],"level":"n3"},
{"word":"散らかる・散らかす","reading":"ちらかる・ちらかす","pair":[{"word":"散らかる","reading":"ちらかる","meaning":"bừa bộn (tự nhiên) [自動詞]","notes":["Trạng thái đồ đạc bừa bãi → 部屋が散らかる."],"examples":[{"example":"部屋が散らかっています。","example_reading":"へやがちらかっています。","example_meaning":"Phòng bừa bộn."},{"example":"机の上に、書類が散らかっています。","example_reading":"つくえのうえに、しょるいがちらかっています。","example_meaning":"Giấy tờ bừa bãi trên bàn."}]},{"word":"散らかす","reading":"ちらかす","meaning":"làm bừa bộn (có tác động) [他動詞]","notes":["Có người chủ động làm bừa bộn → 部屋を散らかす."],"examples":[{"example":"子供が部屋を散らかしました。","example_reading":"こどもがへやをちらかしました。","example_meaning":"Đứa trẻ làm bừa bộn căn phòng."},{"example":"彼はいつもおもちゃを散らかします。","example_reading":"かれはいつもおもちゃをちらかします。","example_meaning":"Cậu bé lúc nào cũng vứt bừa đồ chơi."}]}],"level":"n3"},
{"word":"乱れる・乱す","reading":"みだれる・みだす","pair":[{"word":"乱れる","reading":"みだれる","meaning":"bị rối, lộn xộn (tự nhiên) [自動詞]","notes":["Vật tự bị rối loạn → 髪が乱れる."],"examples":[{"example":"風で髪が乱れました。","example_reading":"かぜでかみがみだれました。","example_meaning":"Tóc bị rối vì gió."},{"example":"事故で、電車のダイヤが乱れています。","example_reading":"じこで、でんしゃのだいやがみだれています。","example_meaning":"Vì tai nạn nên lịch tàu bị rối loạn."}]},{"word":"乱す","reading":"みだす","meaning":"làm rối, làm xáo trộn (có tác động) [他動詞]","notes":["Có người chủ động làm xáo trộn → 列を乱す."],"examples":[{"example":"彼は列を乱しました。","example_reading":"かれはれつをみだしました。","example_meaning":"Anh ấy đã làm rối hàng."},{"example":"夜遅くまで起きていると、生活のリズムを乱します。","example_reading":"よるおそくまでおきていると、せいかつのりずむをみだします。","example_meaning":"Thức khuya sẽ làm rối loạn nhịp sống."}]}],"level":"n3"},
{"word":"崩れる・崩す","reading":"くずれる・くずす","pair":[{"word":"崩れる","reading":"くずれる","meaning":"sập, sạt lở, đổ vỡ (tự nhiên) [自動詞]","notes":["Vật tự sụp đổ → 建物が崩れる."],"examples":[{"example":"古い建物が崩れました。","example_reading":"ふるいたてものがくずれました。","example_meaning":"Tòa nhà cũ đã sập."},{"example":"雨で、山の道が崩れました。","example_reading":"あめで、やまのみちがくずれました。","example_meaning":"Con đường núi bị sạt lở vì mưa."}]},{"word":"崩す","reading":"くずす","meaning":"làm sập, làm đổ, phá vỡ (có tác động) [他動詞]","notes":["Có người chủ động làm đổ → 体調を崩す."],"examples":[{"example":"子供が積み木を崩しました。","example_reading":"こどもがつみきをくずしました。","example_meaning":"Đứa trẻ làm đổ đống khối xếp hình."},{"example":"食べすぎて、体調を崩してしまいました。","example_reading":"たべすぎて、たいちょうをくずしてしまいました。","example_meaning":"Ăn quá nhiều nên tôi bị suy giảm sức khỏe."}]}],"level":"n3"},
{"word":"潰れる・潰す","reading":"つぶれる・つぶす","pair":[{"word":"潰れる","reading":"つぶれる","meaning":"bị bẹp, sập tiệm (tự nhiên) [自動詞]","notes":["Vật tự bị đè bẹp/phá sản → 店が潰れる."],"examples":[{"example":"古い家が地震で潰れました。","example_reading":"ふるいいえがじしんでつぶれました。","example_meaning":"Căn nhà cũ bị sập vì động đất."},{"example":"不景気で、店が潰れました。","example_reading":"ふけいきで、みせがつぶれました。","example_meaning":"Cửa hàng phá sản vì kinh tế suy thoái."}]},{"word":"潰す","reading":"つぶす","meaning":"đè bẹp, làm sập, giết (thời gian) (có tác động) [他動詞]","notes":["Có người chủ động đè bẹp → 時間を潰す."],"examples":[{"example":"彼は空き缶を潰しました。","example_reading":"かれはあきかんをつぶしました。","example_meaning":"Anh ấy đã đạp bẹp cái lon rỗng."},{"example":"友達と話して、時間を潰しました。","example_reading":"ともだちとはなして、じかんをつぶしました。","example_meaning":"Tôi nói chuyện với bạn để giết thời gian."}]}],"level":"n3"},
{"word":"傷つく・傷つける","reading":"きずつく・きずつける","pair":[{"word":"傷つく","reading":"きずつく","meaning":"bị thương, bị trầy, bị tổn thương (tự nhiên) [自動詞]","notes":["Chủ thể tự bị tổn hại, chú ý trạng thái → 心が傷つく."],"examples":[{"example":"彼の言葉に、心が傷つきました。","example_reading":"かれのことばに、こころがきずつきました。","example_meaning":"Tôi bị tổn thương trước lời nói của anh ấy."},{"example":"引っ越しの時に、床が傷つきました。","example_reading":"ひっこしのときに、ゆかがきずつきました。","example_meaning":"Sàn nhà bị trầy khi chuyển nhà."}]},{"word":"傷つける","reading":"きずつける","meaning":"làm trầy, làm tổn thương (có tác động) [他動詞]","notes":["Có người chủ động gây tổn hại → 人を傷つける."],"examples":[{"example":"彼は車を傷つけてしまいました。","example_reading":"かれはくるまをきずつけてしまいました。","example_meaning":"Anh ấy lỡ làm trầy xe."},{"example":"彼女の言葉が、友達を傷つけました。","example_reading":"かのじょのことばが、ともだちをきずつけました。","example_meaning":"Lời nói của cô ấy đã làm bạn tổn thương."}]}],"level":"n3"},
{"word":"剥がれる・剥がす","reading":"はがれる・はがす","pair":[{"word":"剥がれる","reading":"はがれる","meaning":"bị bong ra, bị tróc (tự nhiên) [自動詞]","notes":["Lớp ngoài tự bong ra → ペンキが剥がれる."],"examples":[{"example":"壁のペンキが剥がれました。","example_reading":"かべのぺんきがはがれました。","example_meaning":"Lớp sơn trên tường đã bong ra."},{"example":"古いシールが剥がれてしまいました。","example_reading":"ふるいしーるがはがれてしまいました。","example_meaning":"Miếng dán cũ đã bong mất rồi."}]},{"word":"剥がす","reading":"はがす","meaning":"bóc ra, gỡ ra (có tác động) [他動詞]","notes":["Có người chủ động bóc/gỡ → ポスターを剥がす."],"examples":[{"example":"私は壁のポスターを剥がしました。","example_reading":"わたしはかべのぽすたーをはがしました。","example_meaning":"Tôi đã gỡ tấm áp phích trên tường."},{"example":"箱からテープを剥がしてください。","example_reading":"はこからてーぷをはがしてください。","example_meaning":"Hãy bóc băng dính khỏi cái hộp."}]}],"level":"n3"},
{"word":"裂ける・裂く","reading":"さける・さく","pair":[{"word":"裂ける","reading":"さける","meaning":"bị rách, nứt toạc (tự nhiên) [自動詞]","notes":["Vật tự bị rách toạc → 袋が裂ける."],"examples":[{"example":"服が釘に引っかかって、裂けました。","example_reading":"ふくがくぎにひっかかって、さけました。","example_meaning":"Áo mắc vào cái đinh nên bị rách."},{"example":"袋が裂けて、中身が出てしまいました。","example_reading":"ふくろがさけて、なかみがでてしまいました。","example_meaning":"Túi bị rách nên đồ bên trong rơi ra."}]},{"word":"裂く","reading":"さく","meaning":"xé ra, chia cắt (có tác động) [他動詞]","notes":["Có người chủ động xé → 紙を裂く."],"examples":[{"example":"彼は紙を二つに裂きました。","example_reading":"かれはかみをふたつにさきました。","example_meaning":"Anh ấy xé tờ giấy làm đôi."},{"example":"母は肉を手で裂いて、サラダにのせました。","example_reading":"はははにくをてでさいて、さらだにのせました。","example_meaning":"Mẹ xé thịt bằng tay rồi cho lên salad."}]}],"level":"n3"},
{"word":"砕ける・砕く","reading":"くだける・くだく","pair":[{"word":"砕ける","reading":"くだける","meaning":"vỡ vụn, vỡ tan (tự nhiên) [自動詞]","notes":["Vật tự vỡ thành mảnh nhỏ → 氷が砕ける."],"examples":[{"example":"氷が落ちて、粉々に砕けました。","example_reading":"こおりがおちて、こなごなにくだけました。","example_meaning":"Cục đá rơi xuống vỡ vụn."},{"example":"波が岩に当たって、砕けました。","example_reading":"なみがいわにあたって、くだけました。","example_meaning":"Sóng đập vào đá rồi vỡ tung."}]},{"word":"砕く","reading":"くだく","meaning":"đập vỡ, nghiền nhỏ (có tác động) [他動詞]","notes":["Có người chủ động đập vỡ → 石を砕く."],"examples":[{"example":"彼はハンマーで石を砕きました。","example_reading":"かれははんまーでいしをくだきました。","example_meaning":"Anh ấy đã đập vỡ đá bằng búa."},{"example":"ナッツを細かく砕いて、ケーキにのせます。","example_reading":"なっつをこまかくくだいて、けーきにのせます。","example_meaning":"Tôi nghiền nhỏ hạt rồi rắc lên bánh."}]}],"level":"n3"},
{"word":"擦れる・擦る","reading":"すれる・する","pair":[{"word":"擦れる","reading":"すれる","meaning":"bị cọ xát, mòn (tự nhiên) [自動詞]","notes":["Vật tự bị cọ xát vào nhau → 靴が擦れる."],"examples":[{"example":"靴が擦れて、足が痛いです。","example_reading":"くつがすれて、あしがいたいです。","example_meaning":"Giày cọ vào chân làm chân đau."},{"example":"袖が擦れて、穴が開きました。","example_reading":"そでがすれて、あながあきました。","example_meaning":"Tay áo bị cọ mòn nên thủng lỗ."}]},{"word":"擦る","reading":"する","meaning":"quẹt, mài, cọ (có tác động) [他動詞]","notes":["Có người chủ động quẹt/mài → マッチを擦る."],"examples":[{"example":"彼はマッチを擦って、火をつけました。","example_reading":"かれはまっちをすって、ひをつけました。","example_meaning":"Anh ấy quẹt diêm để châm lửa."},{"example":"彼は墨を擦って、字を書きました。","example_reading":"かれはすみをすって、じをかきました。","example_meaning":"Anh ấy mài mực rồi viết chữ."}]}],"level":"n3"},
{"word":"晴れる・晴らす","reading":"はれる・はらす","pair":[{"word":"晴れる","reading":"はれる","meaning":"quang đãng, tạnh (tự nhiên) [自動詞]","notes":["Trời tự quang → 天気が晴れる."],"examples":[{"example":"午後から、天気が晴れました。","example_reading":"ごごから、てんきがはれました。","example_meaning":"Từ chiều trời đã quang."},{"example":"雨が止んで、空が晴れてきました。","example_reading":"あめがやんで、そらがはれてきました。","example_meaning":"Mưa tạnh, bầu trời bắt đầu quang đãng."}]},{"word":"晴らす","reading":"はらす","meaning":"làm tan, giải tỏa (có tác động) [他動詞]","notes":["Có người chủ động giải tỏa/xóa bỏ → 疑いを晴らす."],"examples":[{"example":"彼は友達と遊んで、気分を晴らしました。","example_reading":"かれはともだちとあそんで、きぶんをはらしました。","example_meaning":"Anh ấy chơi với bạn để giải tỏa tâm trạng."},{"example":"彼は疑いを晴らすために、証拠を出しました。","example_reading":"かれはうたがいをはらすために、しょうこをだしました。","example_meaning":"Anh ấy đưa ra bằng chứng để xóa bỏ nghi ngờ."}]}],"level":"n3"},
{"word":"弱まる・弱める","reading":"よわまる・よわめる","pair":[{"word":"弱まる","reading":"よわまる","meaning":"yếu đi (tự nhiên) [自動詞]","notes":["Sức mạnh tự yếu đi → 風が弱まる."],"examples":[{"example":"台風の勢いが弱まりました。","example_reading":"たいふうのいきおいがよわまりました。","example_meaning":"Sức mạnh của bão đã yếu đi."},{"example":"夜になると、雨が弱まりました。","example_reading":"よるになると、あめがよわまりました。","example_meaning":"Khi đêm xuống mưa yếu đi."}]},{"word":"弱める","reading":"よわめる","meaning":"làm yếu đi, giảm (có tác động) [他動詞]","notes":["Có người chủ động giảm bớt → 火を弱める."],"examples":[{"example":"彼は火を弱めました。","example_reading":"かれはひをよわめました。","example_meaning":"Anh ấy đã vặn nhỏ lửa."},{"example":"部屋が寒いので、エアコンの風を弱めました。","example_reading":"へやがさむいので、えあこんのかぜをよわめました。","example_meaning":"Phòng lạnh nên tôi giảm gió điều hòa."}]}],"level":"n3"},
{"word":"強まる・強める","reading":"つよまる・つよめる","pair":[{"word":"強まる","reading":"つよまる","meaning":"mạnh lên (tự nhiên) [自動詞]","notes":["Sức mạnh tự tăng lên → 風が強まる."],"examples":[{"example":"午後から、風が強まりました。","example_reading":"ごごから、かぜがつよまりました。","example_meaning":"Từ chiều gió mạnh lên."},{"example":"二人の友情が強まりました。","example_reading":"ふたりのゆうじょうがつよまりました。","example_meaning":"Tình bạn của hai người đã bền chặt hơn."}]},{"word":"強める","reading":"つよめる","meaning":"làm mạnh lên, tăng cường (có tác động) [他動詞]","notes":["Có người chủ động tăng cường → 火を強める."],"examples":[{"example":"彼は火を強めました。","example_reading":"かれはひをつよめました。","example_meaning":"Anh ấy đã vặn lớn lửa."},{"example":"警察は、町の警備を強めました。","example_reading":"けいさつは、まちのけいびをつよめました。","example_meaning":"Cảnh sát đã tăng cường an ninh thị trấn."}]}],"level":"n3"},
{"word":"高まる・高める","reading":"たかまる・たかめる","pair":[{"word":"高まる","reading":"たかまる","meaning":"dâng cao, tăng lên (tự nhiên) [自動詞]","notes":["Mức độ tự tăng cao → 関心が高まる."],"examples":[{"example":"試合の前に、緊張が高まりました。","example_reading":"しあいのまえに、きんちょうがたかまりました。","example_meaning":"Trước trận đấu sự căng thẳng tăng lên."},{"example":"環境への関心が高まっています。","example_reading":"かんきょうへのかんしんがたかまっています。","example_meaning":"Mối quan tâm đến môi trường đang tăng cao."}]},{"word":"高める","reading":"たかめる","meaning":"nâng cao (có tác động) [他動詞]","notes":["Có người chủ động nâng cao → 技術を高める."],"examples":[{"example":"彼は毎日練習して、技術を高めました。","example_reading":"かれはまいにちれんしゅうして、ぎじゅつをたかめました。","example_meaning":"Anh ấy luyện tập mỗi ngày để nâng cao kỹ thuật."},{"example":"先生の言葉が、学生のやる気を高めました。","example_reading":"せんせいのことばが、がくせいのやるきをたかめました。","example_meaning":"Lời thầy cô đã nâng cao động lực của học sinh."}]}],"level":"n3"},
{"word":"深まる・深める","reading":"ふかまる・ふかめる","pair":[{"word":"深まる","reading":"ふかまる","meaning":"trở nên sâu sắc (tự nhiên) [自動詞]","notes":["Mức độ tự sâu thêm → 秋が深まる."],"examples":[{"example":"秋が深まりました。","example_reading":"あきがふかまりました。","example_meaning":"Mùa thu đã sâu hơn (đã vào giữa thu)."},{"example":"留学して、友達との絆が深まりました。","example_reading":"りゅうがくして、ともだちとのきずながふかまりました。","example_meaning":"Đi du học nên mối gắn bó với bạn bè đã sâu đậm hơn."}]},{"word":"深める","reading":"ふかめる","meaning":"làm sâu sắc thêm (có tác động) [他動詞]","notes":["Có người chủ động đào sâu → 知識を深める."],"examples":[{"example":"彼は本を読んで、知識を深めました。","example_reading":"かれはほんをよんで、ちしきをふかめました。","example_meaning":"Anh ấy đọc sách để đào sâu kiến thức."},{"example":"話し合いで、お互いの理解を深めました。","example_reading":"はなしあいで、おたがいのりかいをふかめました。","example_meaning":"Qua trao đổi, chúng tôi hiểu nhau hơn."}]}],"level":"n3"},
{"word":"狭まる・狭める","reading":"せばまる・せばめる","pair":[{"word":"狭まる","reading":"せばまる","meaning":"bị thu hẹp (tự nhiên) [自動詞]","notes":["Phạm vi tự hẹp lại → 道が狭まる."],"examples":[{"example":"道が狭まっています。","example_reading":"みちがせばまっています。","example_meaning":"Con đường đang hẹp lại."},{"example":"差が少しずつ狭まってきました。","example_reading":"さがすこしずつせばまってきました。","example_meaning":"Khoảng cách đã dần thu hẹp lại."}]},{"word":"狭める","reading":"せばめる","meaning":"thu hẹp (có tác động) [他動詞]","notes":["Có người chủ động thu hẹp → 範囲を狭める."],"examples":[{"example":"工事で、道の幅を狭めました。","example_reading":"こうじで、みちのはばをせばめました。","example_meaning":"Do thi công nên người ta đã thu hẹp bề rộng con đường."},{"example":"検索の条件を狭めて、探しました。","example_reading":"けんさくのじょうけんをせばめて、さがしました。","example_meaning":"Tôi thu hẹp điều kiện tìm kiếm để tìm."}]}],"level":"n3"},
{"word":"早まる・早める","reading":"はやまる・はやめる","pair":[{"word":"早まる","reading":"はやまる","meaning":"được dời sớm lên (tự nhiên) [自動詞]","notes":["Thời gian tự sớm hơn, chú ý kết quả → 予定が早まる."],"examples":[{"example":"予定が一日早まりました。","example_reading":"よていがいちにちはやまりました。","example_meaning":"Kế hoạch đã sớm hơn một ngày."},{"example":"会議の時間が早まりました。","example_reading":"かいぎのじかんがはやまりました。","example_meaning":"Giờ họp đã được dời sớm lên."}]},{"word":"早める","reading":"はやめる","meaning":"làm sớm lên, đẩy nhanh (có tác động) [他動詞]","notes":["Có người chủ động dời sớm → 時間を早める."],"examples":[{"example":"私は出発の時間を早めました。","example_reading":"わたしはしゅっぱつのじかんをはやめました。","example_meaning":"Tôi đã dời giờ khởi hành sớm lên."},{"example":"雨が降りそうなので、帰る時間を早めました。","example_reading":"あめがふりそうなので、かえるじかんをはやめました。","example_meaning":"Trời sắp mưa nên tôi về sớm hơn."}]}],"level":"n3"},
{"word":"改まる・改める","reading":"あらたまる・あらためる","pair":[{"word":"改まる","reading":"あらたまる","meaning":"được đổi mới, trở nên trang trọng (tự nhiên) [自動詞]","notes":["Trạng thái tự đổi mới → 年が改まる."],"examples":[{"example":"年が改まりました。","example_reading":"としがあらたまりました。","example_meaning":"Năm mới đã đến."},{"example":"新しい制度で、ルールが改まりました。","example_reading":"あたらしいせいどで、るーるがあらたまりました。","example_meaning":"Với chế độ mới, quy tắc đã được đổi mới."}]},{"word":"改める","reading":"あらためる","meaning":"sửa đổi, cải thiện (có tác động) [他動詞]","notes":["Có người chủ động sửa đổi → 態度を改める."],"examples":[{"example":"私は自分の態度を改めました。","example_reading":"わたしはじぶんのたいどをあらためました。","example_meaning":"Tôi đã sửa lại thái độ của mình."},{"example":"会社は古い規則を改めました。","example_reading":"かいしゃはふるいきそくをあらためました。","example_meaning":"Công ty đã sửa đổi quy định cũ."}]}],"level":"n3"},
{"word":"収まる・収める","reading":"おさまる・おさめる","pair":[{"word":"収まる","reading":"おさまる","meaning":"nằm gọn, lắng xuống (tự nhiên) [自動詞]","notes":["Vật tự nằm gọn vào chỗ hoặc tự lắng dịu → 痛みが収まる."],"examples":[{"example":"荷物がうまく箱に収まりました。","example_reading":"にもつがうまくはこにおさまりました。","example_meaning":"Hành lý đã nhét vừa vặn vào hộp."},{"example":"痛みが収まって、楽になりました。","example_reading":"いたみがおさまって、らくになりました。","example_meaning":"Cơn đau đã dịu đi nên tôi thấy dễ chịu."}]},{"word":"収める","reading":"おさめる","meaning":"cất vào, đạt được (có tác động) [他動詞]","notes":["Có người chủ động cất gọn hoặc đạt được → 成功を収める."],"examples":[{"example":"彼は荷物を箱に収めました。","example_reading":"かれはにもつをはこにおさめました。","example_meaning":"Anh ấy đã cất hành lý vào hộp."},{"example":"チームは大きな成功を収めました。","example_reading":"ちーむはおおきなせいこうをおさめました。","example_meaning":"Đội đã đạt được thành công lớn."}]}],"level":"n3"},
{"word":"納まる・納める","reading":"おさまる・おさめる","pair":[{"word":"納まる","reading":"おさまる","meaning":"nằm gọn vào, được nộp vào (tự nhiên) [自動詞]","notes":["Vật tự nằm gọn đúng vị trí → 棚に納まる."],"examples":[{"example":"本が本棚にきちんと納まりました。","example_reading":"ほんがほんだなにきちんとおさまりました。","example_meaning":"Sách đã nằm gọn gàng trong giá sách."},{"example":"荷物がうまくトランクに納まりました。","example_reading":"にもつがうまくとらんくにおさまりました。","example_meaning":"Hành lý nằm gọn trong cốp xe."}]},{"word":"納める","reading":"おさめる","meaning":"nộp, giao, cất vào (có tác động) [他動詞]","notes":["Có người chủ động nộp/giao → 税金を納める."],"examples":[{"example":"私は税金を納めました。","example_reading":"わたしはぜいきんをおさめました。","example_meaning":"Tôi đã nộp thuế."},{"example":"彼は会社に製品を納めました。","example_reading":"かれはかいしゃにせいひんをおさめました。","example_meaning":"Anh ấy đã giao sản phẩm cho công ty."}]}],"level":"n3"},
{"word":"治まる・治める","reading":"おさまる・おさめる","pair":[{"word":"治まる","reading":"おさまる","meaning":"lắng xuống, yên ổn (tự nhiên) [自動詞]","notes":["Tình trạng tự lắng dịu → 咳が治まる."],"examples":[{"example":"咳が治まりました。","example_reading":"せきがおさまりました。","example_meaning":"Cơn ho đã dịu."},{"example":"争いが治まって、町が静かになりました。","example_reading":"あらそいがおさまって、まちがしずかになりました。","example_meaning":"Cuộc tranh chấp lắng xuống, thị trấn trở lại yên tĩnh."}]},{"word":"治める","reading":"おさめる","meaning":"cai trị, quản lý (có tác động) [他動詞]","notes":["Có người chủ động cai quản → 国を治める."],"examples":[{"example":"王様は国を治めました。","example_reading":"おうさまはくにをおさめました。","example_meaning":"Nhà vua đã cai trị đất nước."},{"example":"彼は上手に町を治めました。","example_reading":"かれはじょうずにまちをおさめました。","example_meaning":"Ông ấy cai quản thị trấn một cách khéo léo."}]}],"level":"n3"},
{"word":"当てはまる・当てはめる","reading":"あてはまる・あてはめる","pair":[{"word":"当てはまる","reading":"あてはまる","meaning":"phù hợp, áp dụng được (tự nhiên) [自動詞]","notes":["Điều kiện tự khớp với đối tượng → 条件に当てはまる."],"examples":[{"example":"この条件に当てはまる人は、手を挙げてください。","example_reading":"このじょうけんにあてはまるひとは、てをあげてください。","example_meaning":"Ai phù hợp với điều kiện này xin hãy giơ tay."},{"example":"この規則は、全員に当てはまります。","example_reading":"このきそくは、ぜんいんにあてはまります。","example_meaning":"Quy tắc này áp dụng cho tất cả mọi người."}]},{"word":"当てはめる","reading":"あてはめる","meaning":"áp dụng, điền vào (có tác động) [他動詞]","notes":["Có người chủ động áp dụng/điền vào → 規則を当てはめる."],"examples":[{"example":"彼は新しい規則を全員に当てはめました。","example_reading":"かれはあたらしいきそくをぜんいんにあてはめました。","example_meaning":"Anh ấy đã áp dụng quy tắc mới cho mọi người."},{"example":"例を参考にして、空いている所に言葉を当てはめてください。","example_reading":"れいをさんこうにして、あいているところにことばをあてはめてください。","example_meaning":"Hãy tham khảo ví dụ và điền từ vào chỗ trống."}]}],"level":"n3"},
{"word":"現れる・現す","reading":"あらわれる・あらわす","pair":[{"word":"現れる","reading":"あらわれる","meaning":"xuất hiện, lộ ra (tự nhiên) [自動詞]","notes":["Vật/người tự xuất hiện → 姿が現れる."],"examples":[{"example":"空に虹が現れました。","example_reading":"そらににじがあらわれました。","example_meaning":"Cầu vồng đã xuất hiện trên bầu trời."},{"example":"約束の時間に、彼がやっと現れました。","example_reading":"やくそくのじかんに、かれがやっとあらわれました。","example_meaning":"Đến giờ hẹn cuối cùng anh ấy cũng xuất hiện."}]},{"word":"現す","reading":"あらわす","meaning":"làm lộ ra, để lộ (có tác động) [他動詞]","notes":["Có người chủ động để lộ ra → 姿を現す."],"examples":[{"example":"太陽が雲の間から姿を現しました。","example_reading":"たいようがくものあいからすがたをあらわしました。","example_meaning":"Mặt trời đã lộ diện giữa những đám mây."},{"example":"彼はついに本当の姿を現しました。","example_reading":"かれはついにほんとうのすがたをあらわしました。","example_meaning":"Cuối cùng anh ta đã lộ rõ bộ mặt thật."}]}],"level":"n3"},
{"word":"表れる・表す","reading":"あらわれる・あらわす","pair":[{"word":"表れる","reading":"あらわれる","meaning":"được biểu lộ, hiện rõ (tự nhiên) [自動詞]","notes":["Cảm xúc/kết quả tự biểu lộ ra → 気持ちが表れる."],"examples":[{"example":"彼の気持ちが顔に表れています。","example_reading":"かれのきもちがかおにあらわれています。","example_meaning":"Cảm xúc của anh ấy hiện rõ trên mặt."},{"example":"練習の成果が、結果に表れました。","example_reading":"れんしゅうのせいかが、けっかにあらわれました。","example_meaning":"Thành quả luyện tập đã thể hiện trong kết quả."}]},{"word":"表す","reading":"あらわす","meaning":"biểu thị, bày tỏ (có tác động) [他動詞]","notes":["Có người chủ động bày tỏ/biểu thị → 気持ちを表す."],"examples":[{"example":"彼は言葉で感謝の気持ちを表しました。","example_reading":"かれはことばでかんしゃのきもちをあらわしました。","example_meaning":"Anh ấy đã bày tỏ lòng biết ơn bằng lời."},{"example":"この記号は、温度を表しています。","example_reading":"このきごうは、おんどをあらわしています。","example_meaning":"Ký hiệu này biểu thị nhiệt độ."}]}],"level":"n3"},
{"word":"映る・映す","reading":"うつる・うつす","pair":[{"word":"映る","reading":"うつる","meaning":"được phản chiếu, hiện lên (tự nhiên) [自動詞]","notes":["Hình ảnh tự phản chiếu/hiện lên → 鏡に映る."],"examples":[{"example":"湖に山が映っています。","example_reading":"みずうみにやまがうつっています。","example_meaning":"Ngọn núi phản chiếu trên mặt hồ."},{"example":"テレビに、きれいな風景が映っています。","example_reading":"てれびに、きれいなふうけいがうつっています。","example_meaning":"Phong cảnh đẹp đang hiện trên tivi."}]},{"word":"映す","reading":"うつす","meaning":"chiếu, phản chiếu (có tác động) [他動詞]","notes":["Có người chủ động chiếu/soi → スクリーンに映す."],"examples":[{"example":"彼は鏡に自分の姿を映しました。","example_reading":"かれはかがみにじぶんのすがたをうつしました。","example_meaning":"Anh ấy soi hình mình vào gương."},{"example":"先生は、スクリーンに資料を映しました。","example_reading":"せんせいは、すくりーんにしりょうをうつしました。","example_meaning":"Thầy giáo chiếu tài liệu lên màn hình."}]}],"level":"n3"},
{"word":"写る・写す","reading":"うつる・うつす","pair":[{"word":"写る","reading":"うつる","meaning":"được chụp vào ảnh (tự nhiên) [自動詞]","notes":["Người/vật hiện trong ảnh → 写真に写る."],"examples":[{"example":"この写真には、私の家族が写っています。","example_reading":"このしゃしんには、わたしのかぞくがうつっています。","example_meaning":"Trong bức ảnh này có gia đình tôi."},{"example":"写真に、知らない人が写っていました。","example_reading":"しゃしんに、しらないひとがうつっていました。","example_meaning":"Trong ảnh có một người lạ."}]},{"word":"写す","reading":"うつす","meaning":"chụp ảnh, chép lại (có tác động) [他動詞]","notes":["Có người chủ động chụp/chép → 写真を写す."],"examples":[{"example":"私は旅行で、たくさん写真を写しました。","example_reading":"わたしはりょこうで、たくさんしゃしんをうつしました。","example_meaning":"Tôi đã chụp nhiều ảnh trong chuyến du lịch."},{"example":"彼は黒板の字をノートに写しました。","example_reading":"かれはこくばんのじをのーとにうつしました。","example_meaning":"Anh ấy chép chữ trên bảng vào vở."}]}],"level":"n3"},
{"word":"移る・移す","reading":"うつる・うつす","pair":[{"word":"移る","reading":"うつる","meaning":"chuyển sang, lây sang (tự nhiên) [自動詞]","notes":["Chủ thể tự chuyển chỗ hoặc bệnh tự lây → 家に移る. Chú ý: 風邪が移る."],"examples":[{"example":"私は来月、新しい家に移ります。","example_reading":"わたしはらいげつ、あたらしいいえにうつります。","example_meaning":"Tháng sau tôi chuyển sang nhà mới."},{"example":"風邪が、弟に移りました。","example_reading":"かぜが、おとうとにうつりました。","example_meaning":"Cảm đã lây sang em trai."}]},{"word":"移す","reading":"うつす","meaning":"chuyển, dời, lây (có tác động) [他動詞]","notes":["Có người chủ động chuyển/dời → 荷物を移す."],"examples":[{"example":"彼は荷物を新しい部屋に移しました。","example_reading":"かれはにもつをあたらしいへやにうつしました。","example_meaning":"Anh ấy đã chuyển hành lý sang phòng mới."},{"example":"会社は、事務所を東京に移しました。","example_reading":"かいしゃは、じむしょをとうきょうにうつしました。","example_meaning":"Công ty đã chuyển văn phòng đến Tokyo."}]}],"level":"n3"},
{"word":"返る・返す","reading":"かえる・かえす","pair":[{"word":"返る","reading":"かえる","meaning":"trở lại, được trả lại (tự nhiên) [自動詞]","notes":["Vật tự quay về chủ cũ → 手元に返る."],"examples":[{"example":"貸したお金が、やっと返ってきました。","example_reading":"かしたおかねが、やっとかえってきました。","example_meaning":"Số tiền cho mượn cuối cùng cũng được trả lại."},{"example":"忘れ物が、私の手に返ってきました。","example_reading":"わすれものが、わたしのてにかえってきました。","example_meaning":"Đồ để quên đã được trả về tay tôi."}]},{"word":"返す","reading":"かえす","meaning":"trả lại (có tác động) [他動詞]","notes":["Có người chủ động trả lại → 本を返す."],"examples":[{"example":"私は図書館に本を返しました。","example_reading":"わたしはとしょかんにほんをかえしました。","example_meaning":"Tôi đã trả sách cho thư viện."},{"example":"借りたお金は、来週返します。","example_reading":"かりたおかねは、らいしゅうかえします。","example_meaning":"Tiền mượn tôi sẽ trả vào tuần sau."}]}],"level":"n3"},
{"word":"帰る・帰す","reading":"かえる・かえす","pair":[{"word":"帰る","reading":"かえる","meaning":"về (nhà, nơi xuất phát) (tự nhiên) [自動詞]","notes":["Chủ thể tự về nhà → 家に帰る."],"examples":[{"example":"私は六時に家に帰ります。","example_reading":"わたしはろくじにいえにかえります。","example_meaning":"Tôi về nhà lúc 6 giờ."},{"example":"授業が終わったので、学生は家に帰りました。","example_reading":"じゅぎょうがおわったので、がくせいはいえにかえりました。","example_meaning":"Học xong nên học sinh đã về nhà."}]},{"word":"帰す","reading":"かえす","meaning":"cho về, tiễn về (có tác động) [他動詞]","notes":["Có người chủ động cho ai đó về → 学生を帰す."],"examples":[{"example":"先生は、学生を早く家に帰しました。","example_reading":"せんせいは、がくせいをはやくいえにかえしました。","example_meaning":"Thầy giáo cho học sinh về nhà sớm."},{"example":"雨が強くなったので、客を帰しました。","example_reading":"あめがつよくなったので、きゃくをかえしました。","example_meaning":"Mưa to lên nên tôi cho khách ra về."}]}],"level":"n3"},
{"word":"通る・通す","reading":"とおる・とおす","pair":[{"word":"通る","reading":"とおる","meaning":"đi qua, thông qua (tự nhiên) [自動詞]","notes":["Chủ thể tự đi qua, を chỉ nơi đi qua → 道を通る."],"examples":[{"example":"家の前を、バスが通ります。","example_reading":"いえのまえを、ばすがとおります。","example_meaning":"Xe buýt chạy qua trước nhà."},{"example":"この道は、車が多く通ります。","example_reading":"このみちは、くるまがおおくとおります。","example_meaning":"Con đường này có nhiều xe qua lại."}]},{"word":"通す","reading":"とおす","meaning":"cho đi qua, xuyên qua, giữ vững (có tác động) [他動詞]","notes":["Có người chủ động cho đi qua hoặc giữ vững → 意見を通す."],"examples":[{"example":"彼は人を通すために、横によけました。","example_reading":"かれはひとをとおすために、よこによけました。","example_meaning":"Anh ấy tránh sang bên để nhường người đi qua."},{"example":"最後まで自分の意見を通しました。","example_reading":"さいごまでじぶんのいけんをとおしました。","example_meaning":"Tôi giữ vững ý kiến của mình đến cuối cùng."}]}],"level":"n3"},
{"word":"過ぎる・過ごす","reading":"すぎる・すごす","pair":[{"word":"過ぎる","reading":"すぎる","meaning":"trôi qua, quá (tự nhiên) [自動詞]","notes":["Thời gian tự trôi qua → 時間が過ぎる."],"examples":[{"example":"時間が過ぎるのは、早いです。","example_reading":"じかんがすぎるのは、はやいです。","example_meaning":"Thời gian trôi nhanh thật."},{"example":"楽しい休みが、あっという間に過ぎました。","example_reading":"たのしいやすみが、あっというまにすぎました。","example_meaning":"Kỳ nghỉ vui vẻ đã trôi qua trong chớp mắt."}]},{"word":"過ごす","reading":"すごす","meaning":"trải qua, sống qua (có tác động) [他動詞]","notes":["Có người chủ động trải qua thời gian → 休みを過ごす."],"examples":[{"example":"私は夏休みを田舎で過ごしました。","example_reading":"わたしはなつやすみをいなかですごしました。","example_meaning":"Tôi đã trải qua kỳ nghỉ hè ở quê."},{"example":"家族と楽しい時間を過ごしました。","example_reading":"かぞくとたのしいじかんをすごしました。","example_meaning":"Tôi đã có khoảng thời gian vui vẻ bên gia đình."}]}],"level":"n3"},
{"word":"滑る・滑らす","reading":"すべる・すべらす","pair":[{"word":"滑る","reading":"すべる","meaning":"trượt, trơn (tự nhiên) [自動詞]","notes":["Chủ thể tự bị trượt → 足が滑る."],"examples":[{"example":"雪道で、足が滑りました。","example_reading":"ゆきみちで、あしがすべりました。","example_meaning":"Tôi trượt chân trên đường tuyết."},{"example":"雨の日は、床が滑りやすいです。","example_reading":"あめのひは、ゆかがすべりやすいです。","example_meaning":"Ngày mưa sàn nhà dễ trơn trượt."}]},{"word":"滑らす","reading":"すべらす","meaning":"làm trượt, để trượt (có tác động) [他動詞]","notes":["Vô tình làm trượt, thường là 手を滑らす / 口を滑らす."],"examples":[{"example":"彼は手を滑らして、コップを落としました。","example_reading":"かれはてをすべらして、こっぷをおとしました。","example_meaning":"Anh ấy trượt tay làm rơi cái cốc."},{"example":"うっかり口を滑らして、秘密を話してしまいました。","example_reading":"うっかりくちをすべらして、ひみつをはなしてしまいました。","example_meaning":"Lỡ lời nên tôi đã nói ra bí mật."}]}],"level":"n3"},
{"word":"転がる・転がす","reading":"ころがる・ころがす","pair":[{"word":"転がる","reading":"ころがる","meaning":"lăn (tự nhiên) [自動詞]","notes":["Vật tự lăn đi → ボールが転がる."],"examples":[{"example":"ボールが坂を転がっています。","example_reading":"ぼーるがさかをころがっています。","example_meaning":"Quả bóng đang lăn xuống dốc."},{"example":"石が山から転がってきました。","example_reading":"いしがやまからころがってきました。","example_meaning":"Hòn đá lăn từ trên núi xuống."}]},{"word":"転がす","reading":"ころがす","meaning":"làm lăn, lăn (có tác động) [他動詞]","notes":["Có người chủ động làm lăn → ボールを転がす."],"examples":[{"example":"彼はボールを転がして、犬と遊びました。","example_reading":"かれはぼーるをころがして、いぬとあそびました。","example_meaning":"Anh ấy lăn bóng để chơi với con chó."},{"example":"子供が箱を転がして、運びました。","example_reading":"こどもがはこをころがして、はこびました。","example_meaning":"Đứa trẻ lăn cái hộp để chuyển đi."}]}],"level":"n3"},
{"word":"傾く・傾ける","reading":"かたむく・かたむける","pair":[{"word":"傾く","reading":"かたむく","meaning":"nghiêng, xế (tự nhiên) [自動詞]","notes":["Vật tự nghiêng đi → 建物が傾く."],"examples":[{"example":"地震で、建物が少し傾きました。","example_reading":"じしんで、たてものがすこしかたむきました。","example_meaning":"Do động đất, tòa nhà bị nghiêng đi một chút."},{"example":"日が傾いて、空が赤くなりました。","example_reading":"ひがかたむいて、そらがあかくなりました。","example_meaning":"Mặt trời xế bóng, bầu trời đỏ ửng."}]},{"word":"傾ける","reading":"かたむける","meaning":"nghiêng, dốc (có tác động) [他動詞]","notes":["Có người chủ động nghiêng → 首を傾ける. Cũng dùng 耳を傾ける (lắng nghe)."],"examples":[{"example":"彼は首を傾けて、話を聞きました。","example_reading":"かれはくびをかたむけて、はなしをききました。","example_meaning":"Anh ấy nghiêng đầu lắng nghe câu chuyện."},{"example":"彼は耳を傾けて、先生の話を聞きました。","example_reading":"かれはみみをかたむけて、せんせいのはなしをききました。","example_meaning":"Anh ấy chăm chú lắng nghe lời thầy."}]}],"level":"n3"},
{"word":"歪む・歪める","reading":"ゆがむ・ゆがめる","pair":[{"word":"歪む","reading":"ゆがむ","meaning":"bị méo, bị cong vẹo (tự nhiên) [自動詞]","notes":["Vật tự bị méo → 形が歪む."],"examples":[{"example":"古い窓ガラスで、景色が歪んで見えます。","example_reading":"ふるいまどがらすで、けしきがゆがんでみえます。","example_meaning":"Qua tấm kính cũ, phong cảnh trông méo mó."},{"example":"箱が重みで歪んでしまいました。","example_reading":"はこがおもみでゆがんでしまいました。","example_meaning":"Cái hộp bị méo vì sức nặng."}]},{"word":"歪める","reading":"ゆがめる","meaning":"làm méo, bóp méo (có tác động) [他動詞]","notes":["Có người chủ động làm méo/bóp méo → 顔を歪める."],"examples":[{"example":"彼は痛みで顔を歪めました。","example_reading":"かれはいたみでかおをゆがめました。","example_meaning":"Anh ấy nhăn mặt vì đau."},{"example":"彼は事実を歪めて話しました。","example_reading":"かれはじじつをゆがめてはなしました。","example_meaning":"Anh ta đã bóp méo sự thật khi kể."}]}],"level":"n3"},
{"word":"膨らむ・膨らます","reading":"ふくらむ・ふくらます","pair":[{"word":"膨らむ","reading":"ふくらむ","meaning":"phồng lên, nở ra (tự nhiên) [自動詞]","notes":["Vật tự phồng lên → 風船が膨らむ."],"examples":[{"example":"風船が膨らみました。","example_reading":"ふうせんがふくらみました。","example_meaning":"Quả bóng bay đã phồng lên."},{"example":"パンがオーブンの中で膨らみました。","example_reading":"ぱんがおーぶんのなかでふくらみました。","example_meaning":"Bánh mì nở phồng trong lò."}]},{"word":"膨らます","reading":"ふくらます","meaning":"làm phồng lên, thổi phồng (có tác động) [他動詞]","notes":["Có người chủ động làm phồng → 風船を膨らます."],"examples":[{"example":"子供は口で風船を膨らましました。","example_reading":"こどもはくちでふうせんをふくらましました。","example_meaning":"Đứa trẻ thổi phồng quả bóng bay bằng miệng."},{"example":"彼は頬を膨らまして、怒りました。","example_reading":"かれはほほをふくらまして、おこりました。","example_meaning":"Cậu bé phồng má giận dỗi."}]}],"level":"n3"},
{"word":"絡む・絡める","reading":"からむ・からめる","pair":[{"word":"絡む","reading":"からむ","meaning":"bị rối, quấn vào nhau (tự nhiên) [自動詞]","notes":["Vật tự quấn rối vào nhau → 糸が絡む."],"examples":[{"example":"糸が絡んでしまいました。","example_reading":"いとがからんでしまいました。","example_meaning":"Sợi chỉ bị rối vào nhau mất rồi."},{"example":"イヤホンのコードが絡んで、ほどけません。","example_reading":"いやほんのこーどがからんで、ほどけません。","example_meaning":"Dây tai nghe bị rối nên không gỡ được."}]},{"word":"絡める","reading":"からめる","meaning":"quấn vào, trộn cho thấm (có tác động) [他動詞]","notes":["Có người chủ động quấn/trộn thấm → ソースを絡める."],"examples":[{"example":"彼は腕を私の腕に絡めました。","example_reading":"かれはうでをわたしのうでにからめました。","example_meaning":"Anh ấy khoác tay vào tay tôi."},{"example":"パスタにソースを絡めて、食べます。","example_reading":"ぱすたにそーすをからめて、たべます。","example_meaning":"Tôi trộn cho sốt thấm đều vào mì rồi ăn."}]}],"level":"n3"},
{"word":"覚める・覚ます","reading":"さめる・さます","pair":[{"word":"覚める","reading":"さめる","meaning":"tỉnh (giấc) (tự nhiên) [自動詞]","notes":["Chủ thể tự tỉnh giấc → 目が覚める."],"examples":[{"example":"夜中に、目が覚めました。","example_reading":"よなかに、めがさめました。","example_meaning":"Giữa đêm tôi tỉnh giấc."},{"example":"大きな音で、眠りが覚めました。","example_reading":"おおきなおとで、ねむりがさめました。","example_meaning":"Tôi tỉnh ngủ vì tiếng động lớn."}]},{"word":"覚ます","reading":"さます","meaning":"đánh thức, làm tỉnh (có tác động) [他動詞]","notes":["Có người chủ động làm tỉnh → 目を覚ます."],"examples":[{"example":"彼は大きな声で、赤ちゃんの目を覚ましました。","example_reading":"かれはおおきなこえで、あかちゃんのめをさましました。","example_meaning":"Anh ấy làm em bé thức giấc bằng giọng nói lớn."},{"example":"眠気を覚ますために、コーヒーを飲みました。","example_reading":"ねむけをさますために、こーひーをのみました。","example_meaning":"Tôi uống cà phê để xua cơn buồn ngủ."}]}],"level":"n3"},
{"word":"向く・向ける","reading":"むく・むける","pair":[{"word":"向く","reading":"むく","meaning":"hướng về, quay về (tự nhiên) [自動詞]","notes":["Chủ thể tự quay mặt/hướng về → 南を向く."],"examples":[{"example":"窓は南を向いています。","example_reading":"まどはみなみをむいています。","example_meaning":"Cửa sổ hướng về phía nam."},{"example":"呼ばれて、彼女がこちらを向きました。","example_reading":"よばれて、かのじょがこちらをむきました。","example_meaning":"Được gọi nên cô ấy quay về phía này."}]},{"word":"向ける","reading":"むける","meaning":"hướng (cái gì) về phía (có tác động) [他動詞]","notes":["Có người chủ động hướng vật về phía nào đó → カメラを向ける."],"examples":[{"example":"私は彼に顔を向けました。","example_reading":"わたしはかれにかおをむけました。","example_meaning":"Tôi quay mặt về phía anh ấy."},{"example":"彼はカメラをこちらに向けました。","example_reading":"かれはかめらをこちらにむけました。","example_meaning":"Anh ấy hướng máy ảnh về phía này."}]}],"level":"n3"},
{"word":"薄まる・薄める","reading":"うすまる・うすめる","pair":[{"word":"薄まる","reading":"うすまる","meaning":"bị loãng, nhạt đi (tự nhiên) [自動詞]","notes":["Nồng độ tự loãng ra → 味が薄まる."],"examples":[{"example":"水を入れすぎて、味が薄まりました。","example_reading":"みずをいれすぎて、あじがうすまりました。","example_meaning":"Cho nhiều nước quá nên vị bị nhạt đi."},{"example":"ジュースが氷で薄まりました。","example_reading":"じゅーすがこおりでうすまりました。","example_meaning":"Nước ép bị loãng đi vì đá."}]},{"word":"薄める","reading":"うすめる","meaning":"pha loãng, làm nhạt (có tác động) [他動詞]","notes":["Có người chủ động pha loãng → 水で薄める."],"examples":[{"example":"母は味噌汁をお湯で薄めました。","example_reading":"はははみそしるをおゆでうすめました。","example_meaning":"Mẹ pha loãng canh miso bằng nước nóng."},{"example":"絵の具を水で薄めて、色を塗りました。","example_reading":"えのぐをみずでうすめて、いろをぬりました。","example_meaning":"Tôi pha loãng màu vẽ bằng nước rồi tô."}]}],"level":"n3"},
{"word":"溜まる・溜める","reading":"たまる・ためる","pair":[{"word":"溜まる","reading":"たまる","meaning":"dồn lại, ứ đọng (tự nhiên) [自動詞]","notes":["Vật tự dồn lại/tích tụ → 仕事が溜まる."],"examples":[{"example":"洗濯物が溜まってしまいました。","example_reading":"せんたくものがたまってしまいました。","example_meaning":"Đồ giặt dồn lại nhiều mất rồi."},{"example":"仕事が溜まって、毎日遅くまで残っています。","example_reading":"しごとがたまって、まいにちおそくまでのこっています。","example_meaning":"Công việc dồn đống nên ngày nào tôi cũng ở lại muộn."}]},{"word":"溜める","reading":"ためる","meaning":"để dồn lại, tích trữ (có tác động) [他動詞]","notes":["Có người chủ động để dồn/tích trữ → ストレスを溜める."],"examples":[{"example":"彼は雨水をバケツに溜めました。","example_reading":"かれはあまみずをばけつにためました。","example_meaning":"Anh ấy hứng nước mưa vào xô."},{"example":"彼はストレスを溜めないように、運動しています。","example_reading":"かれはすとれすをためないように、うんどうしています。","example_meaning":"Anh ấy tập thể dục để không dồn nén căng thẳng."}]}],"level":"n3"},
{"word":"貯まる・貯める","reading":"たまる・ためる","pair":[{"word":"貯まる","reading":"たまる","meaning":"được tích lũy (tiền, điểm) (tự nhiên) [自動詞]","notes":["Tiền/điểm tự tích lũy lên → お金が貯まる."],"examples":[{"example":"毎月貯金して、お金が貯まりました。","example_reading":"まいつきちょきんして、おかねがたまりました。","example_meaning":"Tháng nào cũng gửi tiết kiệm nên tiền đã tích lũy được."},{"example":"ポイントが貯まったので、割引になります。","example_reading":"ぽいんとがたまったので、わりびきになります。","example_meaning":"Điểm đã tích lũy đủ nên được giảm giá."}]},{"word":"貯める","reading":"ためる","meaning":"tiết kiệm, tích góp (có tác động) [他動詞]","notes":["Có người chủ động tiết kiệm → お金を貯める."],"examples":[{"example":"私は旅行のために、お金を貯めています。","example_reading":"わたしはりょこうのために、おかねをためています。","example_meaning":"Tôi đang tiết kiệm tiền để đi du lịch."},{"example":"彼はアルバイトで、お金を貯めました。","example_reading":"かれはあるばいとで、おかねをためました。","example_meaning":"Anh ấy đã tích góp tiền nhờ làm thêm."}]}],"level":"n3"},
{"word":"儲かる・儲ける","reading":"もうかる・もうける","pair":[{"word":"儲かる","reading":"もうかる","meaning":"có lời, sinh lợi (tự nhiên) [自動詞]","notes":["Việc kinh doanh tự sinh lời → 店が儲かる."],"examples":[{"example":"この店は、よく儲かっています。","example_reading":"このみせは、よくもうかっています。","example_meaning":"Cửa hàng này kiếm được nhiều lời."},{"example":"今年は、会社がたくさん儲かりました。","example_reading":"ことしは、かいしゃがたくさんもうかりました。","example_meaning":"Năm nay công ty đã lời được nhiều."}]},{"word":"儲ける","reading":"もうける","meaning":"kiếm lời, thu lợi (có tác động) [他動詞]","notes":["Có người chủ động kiếm lời → お金を儲ける."],"examples":[{"example":"彼は株で、お金を儲けました。","example_reading":"かれはかぶで、おかねをもうけました。","example_meaning":"Anh ấy kiếm được tiền nhờ chứng khoán."},{"example":"彼は商売で、大きな利益を儲けました。","example_reading":"かれはしょうばいで、おおきなりえきをもうけました。","example_meaning":"Anh ấy thu được lợi nhuận lớn từ buôn bán."}]}],"level":"n3"},
{"word":"苦しむ・苦しめる","reading":"くるしむ・くるしめる","pair":[{"word":"苦しむ","reading":"くるしむ","meaning":"khổ sở, đau khổ (tự nhiên) [自動詞]","notes":["Chủ thể tự chịu đau khổ → 病気で苦しむ."],"examples":[{"example":"彼は長い間、病気で苦しみました。","example_reading":"かれはながいあいだ、びょうきでくるしみました。","example_meaning":"Anh ấy đã khổ sở vì bệnh trong thời gian dài."},{"example":"国民は、物価の上昇に苦しんでいます。","example_reading":"こくみんは、ぶっかのじょうしょうにくるしんでいます。","example_meaning":"Người dân đang khổ sở vì giá cả leo thang."}]},{"word":"苦しめる","reading":"くるしめる","meaning":"làm khổ, hành hạ (có tác động) [他動詞]","notes":["Có người/vật chủ động làm người khác khổ → 人を苦しめる."],"examples":[{"example":"騒音が、近所の人を苦しめています。","example_reading":"そうおんが、きんじょのひとをくるしめています。","example_meaning":"Tiếng ồn đang làm khổ người hàng xóm."},{"example":"彼の冗談が、友達を苦しめました。","example_reading":"かれのじょうだんが、ともだちをくるしめました。","example_meaning":"Lời đùa của anh ta đã làm bạn khổ tâm."}]}],"level":"n3"},
{"word":"驚く・驚かす","reading":"おどろく・おどろかす","pair":[{"word":"驚く","reading":"おどろく","meaning":"ngạc nhiên, giật mình (tự nhiên) [自動詞]","notes":["Chủ thể tự bị bất ngờ → 音に驚く."],"examples":[{"example":"大きな音を聞いて、驚きました。","example_reading":"おおきなおとをきいて、おどろきました。","example_meaning":"Nghe tiếng động lớn nên tôi giật mình."},{"example":"彼の成績に、先生も驚きました。","example_reading":"かれのせいせきに、せんせいもおどろきました。","example_meaning":"Ngay cả thầy giáo cũng ngạc nhiên về thành tích của cậu ấy."}]},{"word":"驚かす","reading":"おどろかす","meaning":"làm cho giật mình, gây bất ngờ (có tác động) [他動詞]","notes":["Có người chủ động làm ai đó giật mình → 人を驚かす."],"examples":[{"example":"彼は急に大声を出して、私を驚かしました。","example_reading":"かれはきゅうにおおごえをだして、わたしをおどろかしました。","example_meaning":"Anh ấy bất ngờ hét lên làm tôi giật mình."},{"example":"誕生日に、友達を驚かすために、パーティーを準備しました。","example_reading":"たんじょうびに、ともだちをおどろかすために、ぱーてぃーをじゅんびしました。","example_meaning":"Tôi chuẩn bị tiệc để làm bạn bất ngờ vào ngày sinh nhật."}]}],"level":"n3"},
{"word":"悩む・悩ます","reading":"なやむ・なやます","pair":[{"word":"悩む","reading":"なやむ","meaning":"phiền não, phân vân (tự nhiên) [自動詞]","notes":["Chủ thể tự trăn trở → 進路で悩む."],"examples":[{"example":"進路のことで、悩んでいます。","example_reading":"しんろのことで、なやんでいます。","example_meaning":"Tôi đang phân vân về hướng đi tương lai."},{"example":"彼は人間関係に、長い間悩みました。","example_reading":"かれはにんげんかんけいに、ながいあいだなやみました。","example_meaning":"Anh ấy đã trăn trở rất lâu về các mối quan hệ."}]},{"word":"悩ます","reading":"なやます","meaning":"làm phiền não, quấy rầy (có tác động) [他動詞]","notes":["Có người/vật chủ động làm ai đó phiền não → 人を悩ます."],"examples":[{"example":"隣の騒音が、私を悩ましています。","example_reading":"となりのそうおんが、わたしをなやましています。","example_meaning":"Tiếng ồn nhà bên đang làm tôi phiền não."},{"example":"子供の病気が、母親を悩ましました。","example_reading":"こどものびょうきが、ははおやをなやましました。","example_meaning":"Bệnh của con đã làm người mẹ lo lắng."}]}],"level":"n3"},
{"word":"建つ・建てる","reading":"たつ・たてる","pair":[{"word":"建つ","reading":"たつ","meaning":"được xây lên (tự nhiên) [自動詞]","notes":["Công trình được xây, chú ý kết quả → ビルが建つ. Khác với 立つ (đứng)."],"examples":[{"example":"駅の前に、新しいビルが建ちました。","example_reading":"えきのまえに、あたらしいびるがたちました。","example_meaning":"Trước ga đã xây lên một tòa nhà mới."},{"example":"隣に、大きな家が建っています。","example_reading":"となりに、おおきないえがたっています。","example_meaning":"Bên cạnh có một ngôi nhà lớn được xây."}]},{"word":"建てる","reading":"たてる","meaning":"xây dựng (có tác động) [他動詞]","notes":["Có người chủ động xây → 家を建てる. Khác với 立てる (dựng lên)."],"examples":[{"example":"彼は海の近くに家を建てました。","example_reading":"かれはうみのちかくにいえをたてました。","example_meaning":"Anh ấy đã xây nhà gần biển."},{"example":"市は、公園の中に図書館を建てました。","example_reading":"しは、こうえんのなかにとしょかんをたてました。","example_meaning":"Thành phố đã xây thư viện trong công viên."}]}],"level":"n3"},
{"word":"生える・生やす","reading":"はえる・はやす","pair":[{"word":"生える","reading":"はえる","meaning":"mọc (tự nhiên) [自動詞]","notes":["Cỏ/răng/lông tự mọc → 草が生える."],"examples":[{"example":"庭に草が生えました。","example_reading":"にわにくさがはえました。","example_meaning":"Cỏ đã mọc trong vườn."},{"example":"赤ちゃんに、歯が生えてきました。","example_reading":"あかちゃんに、はがはえてきました。","example_meaning":"Em bé đã mọc răng."}]},{"word":"生やす","reading":"はやす","meaning":"để mọc, nuôi (râu, tóc) (có tác động) [他動詞]","notes":["Có người chủ động để cho mọc → ひげを生やす."],"examples":[{"example":"彼はひげを生やしています。","example_reading":"かれはひげをはやしています。","example_meaning":"Anh ấy đang để râu."},{"example":"兄は口ひげを生やして、大人っぽくなりました。","example_reading":"あにはくちひげをはやして、おとなっぽくなりました。","example_meaning":"Anh trai để ria mép nên trông người lớn hơn."}]}],"level":"n3"},
{"word":"載る・載せる","reading":"のる・のせる","pair":[{"word":"載る","reading":"のる","meaning":"được đăng, được đặt lên (tự nhiên) [自動詞]","notes":["Thông tin/vật nằm trên một bề mặt → 新聞に載る. Khác với 乗る (lên xe)."],"examples":[{"example":"私の名前が新聞に載りました。","example_reading":"わたしのなまえがしんぶんにのりました。","example_meaning":"Tên tôi đã được đăng trên báo."},{"example":"この料理は、本に載っています。","example_reading":"このりょうりは、ほんにのっています。","example_meaning":"Món ăn này có đăng trong sách."}]},{"word":"載せる","reading":"のせる","meaning":"đặt lên, đăng lên (có tác động) [他動詞]","notes":["Có người chủ động đặt/đăng lên → 棚に載せる. Khác với 乗せる (cho lên xe)."],"examples":[{"example":"彼は荷物を棚に載せました。","example_reading":"かれはにもつをたなにのせました。","example_meaning":"Anh ấy đã đặt hành lý lên kệ."},{"example":"会社は、ホームページに新しい情報を載せました。","example_reading":"かいしゃは、ほーむぺーじにあたらしいじょうほうをのせました。","example_meaning":"Công ty đã đăng thông tin mới lên trang web."}]}],"level":"n3"},
{"word":"煮える・煮る","reading":"にえる・にる","pair":[{"word":"煮える","reading":"にえる","meaning":"chín mềm (do nấu) (tự nhiên) [自動詞]","notes":["Thức ăn tự chín mềm trong nồi → 野菜が煮える."],"examples":[{"example":"野菜が煮えました。","example_reading":"やさいがにえました。","example_meaning":"Rau đã chín (nấu mềm)."},{"example":"鍋の中で、肉がよく煮えています。","example_reading":"なべのなかで、にくがよくにえています。","example_meaning":"Thịt trong nồi đã được nấu chín mềm."}]},{"word":"煮る","reading":"にる","meaning":"nấu, kho, ninh (có tác động) [他動詞]","notes":["Có người chủ động nấu/kho → 野菜を煮る."],"examples":[{"example":"母は野菜をやわらかく煮ました。","example_reading":"はははやさいをやわらかくにました。","example_meaning":"Mẹ đã nấu rau cho mềm."},{"example":"私は魚を醤油で煮ました。","example_reading":"わたしはさかなをしょうゆでにました。","example_meaning":"Tôi đã kho cá với xì dầu."}]}],"level":"n3"},
{"word":"炊ける・炊く","reading":"たける・たく","pair":[{"word":"炊ける","reading":"たける","meaning":"chín (cơm) (tự nhiên) [自動詞]","notes":["Cơm tự chín → ご飯が炊ける."],"examples":[{"example":"ご飯が炊けました。","example_reading":"ごはんがたけました。","example_meaning":"Cơm đã chín."},{"example":"炊飯器で、ご飯がおいしく炊けました。","example_reading":"すいはんきで、ごはんがおいしくたけました。","example_meaning":"Cơm trong nồi cơm điện đã chín thơm ngon."}]},{"word":"炊く","reading":"たく","meaning":"nấu (cơm) (có tác động) [他動詞]","notes":["Có người chủ động nấu cơm → ご飯を炊く."],"examples":[{"example":"母は毎朝、ご飯を炊きます。","example_reading":"はははまいあさ、ごはんをたきます。","example_meaning":"Mẹ nấu cơm mỗi sáng."},{"example":"今夜は、お米を二合炊きます。","example_reading":"こんやは、おこめをにごうたきます。","example_meaning":"Tối nay tôi sẽ nấu hai hợp gạo."}]}],"level":"n3"},
{"word":"焦げる・焦がす","reading":"こげる・こがす","pair":[{"word":"焦げる","reading":"こげる","meaning":"bị cháy khét (tự nhiên) [自動詞]","notes":["Thức ăn tự bị cháy → 魚が焦げる."],"examples":[{"example":"魚が焦げてしまいました。","example_reading":"さかながこげてしまいました。","example_meaning":"Cá bị cháy khét mất rồi."},{"example":"鍋の底が焦げています。","example_reading":"なべのそこがこげています。","example_meaning":"Đáy nồi bị cháy."}]},{"word":"焦がす","reading":"こがす","meaning":"làm cháy khét (có tác động) [他動詞]","notes":["Có người làm cháy (thường vô ý) → ご飯を焦がす."],"examples":[{"example":"彼はうっかりご飯を焦がしました。","example_reading":"かれはうっかりごはんをこがしました。","example_meaning":"Anh ấy lỡ làm cháy cơm."},{"example":"アイロンで、シャツを焦がしてしまいました。","example_reading":"あいろんで、しゃつをこがしてしまいました。","example_meaning":"Tôi lỡ làm cháy áo sơ mi bằng bàn ủi."}]}],"level":"n3"},
{"word":"蒸れる・蒸す","reading":"むれる・むす","pair":[{"word":"蒸れる","reading":"むれる","meaning":"bị hầm hơi, ủ chín (tự nhiên) [自動詞]","notes":["Vật tự bị ủ hơi nóng → 靴の中が蒸れる."],"examples":[{"example":"夏は、靴の中が蒸れます。","example_reading":"なつは、くつのなかがむれます。","example_meaning":"Mùa hè, bên trong giày bị hầm hơi."},{"example":"ご飯が蒸れて、おいしくなりました。","example_reading":"ごはんがむれて、おいしくなりました。","example_meaning":"Cơm được hấp ủ nên trở nên ngon."}]},{"word":"蒸す","reading":"むす","meaning":"hấp (có tác động) [他動詞]","notes":["Có người chủ động hấp → 野菜を蒸す."],"examples":[{"example":"母は野菜を蒸して、サラダを作りました。","example_reading":"はははやさいをむして、さらだをつくりました。","example_meaning":"Mẹ hấp rau rồi làm salad."},{"example":"肉まんを十分間蒸します。","example_reading":"にくまんをじっぷんかんむします。","example_meaning":"Tôi hấp bánh bao nhân thịt trong mười phút."}]}],"level":"n3"},
{"word":"揚がる・揚げる","reading":"あがる・あげる","pair":[{"word":"揚がる","reading":"あがる","meaning":"được chiên xong, bay lên (tự nhiên) [自動詞]","notes":["Đồ chiên tự chín vàng, hoặc diều tự bay lên → 天ぷらが揚がる. Khác với 上がる."],"examples":[{"example":"天ぷらが、きれいに揚がりました。","example_reading":"てんぷらが、きれいにあがりました。","example_meaning":"Tempura đã chiên vàng đẹp."},{"example":"コロッケが揚がるまで、少し待ってください。","example_reading":"ころっけがあがるまで、すこしまってください。","example_meaning":"Hãy đợi một chút cho đến khi croquette được chiên xong."}]},{"word":"揚げる","reading":"あげる","meaning":"chiên, thả (diều) (có tác động) [他動詞]","notes":["Có người chủ động chiên/thả diều → 鶏肉を揚げる. Khác với 上げる."],"examples":[{"example":"母は鶏肉を油で揚げました。","example_reading":"はははとりにくをあぶらであげました。","example_meaning":"Mẹ đã chiên thịt gà."},{"example":"父は凧を揚げて、子供と遊びました。","example_reading":"ちちはたこをあげて、こどもとあそびました。","example_meaning":"Bố thả diều chơi cùng con."}]}],"level":"n3"},
{"word":"煮詰まる・煮詰める","reading":"につまる・につめる","pair":[{"word":"煮詰まる","reading":"につまる","meaning":"bị cô đặc, đã chín muồi (tự nhiên) [自動詞]","notes":["Nước nấu tự cô lại, hoặc cuộc bàn bạc đã chín muồi → 議論が煮詰まる."],"examples":[{"example":"スープが煮詰まってしまいました。","example_reading":"すーぷがにつまってしまいました。","example_meaning":"Súp bị cô đặc lại mất rồi."},{"example":"議論が煮詰まって、結論が出そうです。","example_reading":"ぎろんがにつまって、けつろんがでそうです。","example_meaning":"Cuộc thảo luận đã chín muồi, sắp có kết luận."}]},{"word":"煮詰める","reading":"につめる","meaning":"đun cô đặc, bàn kỹ (có tác động) [他動詞]","notes":["Có người chủ động đun cô đặc hoặc bàn kỹ → 計画を煮詰める."],"examples":[{"example":"彼はソースを煮詰めました。","example_reading":"かれはそーすをにつめました。","example_meaning":"Anh ấy đã đun cô đặc nước sốt."},{"example":"会議で、計画を煮詰めてから、決定します。","example_reading":"かいぎで、けいかくをにつめてから、けっていします。","example_meaning":"Sau khi bàn kỹ kế hoạch trong cuộc họp, chúng tôi sẽ quyết định."}]}],"level":"n3"},
{"word":"浸かる・浸ける","reading":"つかる・つける","pair":[{"word":"浸かる","reading":"つかる","meaning":"ngập, ngâm mình (tự nhiên) [自動詞]","notes":["Chủ thể ở trong trạng thái ngập/ngâm → 水に浸かる."],"examples":[{"example":"洪水で、家が水に浸かりました。","example_reading":"こうずいで、いえがみずにつかりました。","example_meaning":"Do lũ nên ngôi nhà bị ngập trong nước."},{"example":"私は温泉に、ゆっくり浸かりました。","example_reading":"わたしはおんせんに、ゆっくりつかりました。","example_meaning":"Tôi đã ngâm mình thong thả trong suối nước nóng."}]},{"word":"浸ける","reading":"つける","meaning":"ngâm vào (có tác động) [他動詞]","notes":["Có người chủ động ngâm → 水に浸ける."],"examples":[{"example":"母は汚れた服を水に浸けました。","example_reading":"はははよごれたふくをみずにつけました。","example_meaning":"Mẹ ngâm quần áo bẩn vào nước."},{"example":"豆を一晩水に浸けておきます。","example_reading":"まめをひとばんみずにつけておきます。","example_meaning":"Tôi ngâm đậu trong nước qua đêm."}]}],"level":"n3"},
{"word":"漬かる・漬ける","reading":"つかる・つける","pair":[{"word":"漬かる","reading":"つかる","meaning":"được muối, thấm (tự nhiên) [自動詞]","notes":["Đồ muối tự thấm gia vị → 漬物が漬かる."],"examples":[{"example":"きゅうりがよく漬かりました。","example_reading":"きゅうりがよくつかりました。","example_meaning":"Dưa chuột đã muối thấm."},{"example":"この漬物は、まだ漬かっていません。","example_reading":"このつけものは、まだつかっていません。","example_meaning":"Món dưa muối này vẫn chưa thấm."}]},{"word":"漬ける","reading":"つける","meaning":"muối, ngâm (gia vị) (có tác động) [他動詞]","notes":["Có người chủ động muối → 白菜を漬ける."],"examples":[{"example":"母は白菜を塩で漬けました。","example_reading":"はははくさいをしおでつけました。","example_meaning":"Mẹ đã muối cải thảo bằng muối."},{"example":"梅を砂糖に漬けて、ジュースを作ります。","example_reading":"うめをさとうにつけて、じゅーすをつくります。","example_meaning":"Tôi ngâm mơ với đường để làm nước ép."}]}],"level":"n3"},
{"word":"染まる・染める","reading":"そまる・そめる","pair":[{"word":"染まる","reading":"そまる","meaning":"được nhuộm, nhuốm màu (tự nhiên) [自動詞]","notes":["Vật tự nhuốm màu → 空が赤く染まる."],"examples":[{"example":"空が夕日で赤く染まりました。","example_reading":"そらがゆうひであかくそまりました。","example_meaning":"Bầu trời nhuộm đỏ bởi ánh hoàng hôn."},{"example":"白いシャツが、ジュースで赤く染まりました。","example_reading":"しろいしゃつが、じゅーすであかくそまりました。","example_meaning":"Chiếc áo sơ mi trắng bị nước ép nhuộm đỏ."}]},{"word":"染める","reading":"そめる","meaning":"nhuộm (có tác động) [他動詞]","notes":["Có người chủ động nhuộm → 髪を染める."],"examples":[{"example":"彼女は髪を茶色に染めました。","example_reading":"かのじょはかみをちゃいろにそめました。","example_meaning":"Cô ấy đã nhuộm tóc màu nâu."},{"example":"母は古い布を青く染めました。","example_reading":"はははふるいぬのをあおくそめました。","example_meaning":"Mẹ đã nhuộm tấm vải cũ thành màu xanh."}]}],"level":"n3"},
{"word":"ほどける・ほどく","reading":"ほどける・ほどく","pair":[{"word":"ほどける","reading":"ほどける","meaning":"bị tuột, bị cởi ra (tự nhiên) [自動詞]","notes":["Nút buộc tự tuột → ひもがほどける."],"examples":[{"example":"靴のひもがほどけています。","example_reading":"くつのひもがほどけています。","example_meaning":"Dây giày đang bị tuột."},{"example":"リボンが、自然にほどけてしまいました。","example_reading":"りぼんが、しぜんにほどけてしまいました。","example_meaning":"Chiếc nơ tự tuột ra mất rồi."}]},{"word":"ほどく","reading":"ほどく","meaning":"tháo ra, cởi ra (có tác động) [他動詞]","notes":["Có người chủ động tháo nút → ひもをほどく."],"examples":[{"example":"彼は荷物のひもをほどきました。","example_reading":"かれはにもつのひもをほどきました。","example_meaning":"Anh ấy đã cởi dây buộc hành lý."},{"example":"母は古いセーターをほどいて、毛糸にしました。","example_reading":"はははふるいせーたーをほどいて、けいとにしました。","example_meaning":"Mẹ tháo chiếc áo len cũ ra thành sợi len."}]}],"level":"n3"},
{"word":"引っ掛かる・引っ掛ける","reading":"ひっかかる・ひっかける","pair":[{"word":"引っ掛かる","reading":"ひっかかる","meaning":"bị mắc vào (tự nhiên) [自動詞]","notes":["Vật tự bị mắc vào → 服が引っ掛かる."],"examples":[{"example":"服が釘に引っ掛かりました。","example_reading":"ふくがくぎにひっかかりました。","example_meaning":"Áo bị mắc vào cái đinh."},{"example":"凧が木に引っ掛かって、取れません。","example_reading":"たこがきにひっかかって、とれません。","example_meaning":"Con diều mắc vào cây nên không lấy xuống được."}]},{"word":"引っ掛ける","reading":"ひっかける","meaning":"móc lên, làm mắc vào (có tác động) [他動詞]","notes":["Có người chủ động móc/treo → 上着を引っ掛ける."],"examples":[{"example":"彼は上着をハンガーに引っ掛けました。","example_reading":"かれはうわぎをはんがーにひっかけました。","example_meaning":"Anh ấy móc áo khoác lên mắc."},{"example":"私は鍵を壁のフックに引っ掛けました。","example_reading":"わたしはかぎをかべのふっくにひっかけました。","example_meaning":"Tôi móc chìa khóa lên cái móc trên tường."}]}],"level":"n3"},
{"word":"引っ込む・引っ込める","reading":"ひっこむ・ひっこめる","pair":[{"word":"引っ込む","reading":"ひっこむ","meaning":"thụt vào, rút vào (tự nhiên) [自動詞]","notes":["Chủ thể tự thụt vào → 亀が引っ込む."],"examples":[{"example":"亀が、甲羅の中に引っ込みました。","example_reading":"かめが、こうらのなかにひっこみました。","example_meaning":"Con rùa đã thụt vào trong mai."},{"example":"犬は、驚いて、小屋に引っ込みました。","example_reading":"いぬは、おどろいて、こやにひっこみました。","example_meaning":"Con chó giật mình nên chui vào chuồng."}]},{"word":"引っ込める","reading":"ひっこめる","meaning":"rụt lại, rút lại (có tác động) [他動詞]","notes":["Có người chủ động rụt lại → 手を引っ込める."],"examples":[{"example":"彼は手を引っ込めました。","example_reading":"かれはてをひっこめました。","example_meaning":"Anh ấy đã rụt tay lại."},{"example":"彼は反対されて、意見を引っ込めました。","example_reading":"かれははんたいされて、いけんをひっこめました。","example_meaning":"Bị phản đối nên anh ấy rút lại ý kiến."}]}],"level":"n3"},
{"word":"入れ替わる・入れ替える","reading":"いれかわる・いれかえる","pair":[{"word":"入れ替わる","reading":"いれかわる","meaning":"được thay thế, đổi chỗ cho nhau (tự nhiên) [自動詞]","notes":["Người/vật tự thay phiên nhau → メンバーが入れ替わる."],"examples":[{"example":"チームのメンバーが入れ替わりました。","example_reading":"ちーむのめんばーがいれかわりました。","example_meaning":"Các thành viên trong đội đã thay đổi."},{"example":"電車の中で、乗客が入れ替わりました。","example_reading":"でんしゃのなかで、じょうきゃくがいれかわりました。","example_meaning":"Hành khách trên tàu đã thay phiên nhau lên xuống."}]},{"word":"入れ替える","reading":"いれかえる","meaning":"thay, hoán đổi (có tác động) [他動詞]","notes":["Có người chủ động thay/đổi chỗ → 空気を入れ替える."],"examples":[{"example":"私は部屋の空気を入れ替えました。","example_reading":"わたしはへやのくうきをいれかえました。","example_meaning":"Tôi đã thay không khí trong phòng."},{"example":"先生は席を入れ替えて、授業を始めました。","example_reading":"せんせいはせきをいれかえて、じゅぎょうをはじめました。","example_meaning":"Thầy giáo đổi chỗ ngồi rồi bắt đầu buổi học."}]}],"level":"n3"},
{"word":"切り替わる・切り替える","reading":"きりかわる・きりかえる","pair":[{"word":"切り替わる","reading":"きりかわる","meaning":"được chuyển đổi (tự nhiên) [自動詞]","notes":["Tình trạng tự chuyển sang trạng thái khác → 信号が切り替わる."],"examples":[{"example":"信号が、青に切り替わりました。","example_reading":"しんごうが、あおにきりかわりました。","example_meaning":"Đèn đã chuyển sang màu xanh."},{"example":"画面が、自動的に切り替わります。","example_reading":"がめんが、じどうてきにきりかわります。","example_meaning":"Màn hình tự động chuyển đổi."}]},{"word":"切り替える","reading":"きりかえる","meaning":"chuyển đổi (có tác động) [他動詞]","notes":["Có người chủ động chuyển đổi → チャンネルを切り替える."],"examples":[{"example":"彼はテレビのチャンネルを切り替えました。","example_reading":"かれはてれびのちゃんねるをきりかえました。","example_meaning":"Anh ấy đã chuyển kênh tivi."},{"example":"気持ちを切り替えて、勉強を始めました。","example_reading":"きもちをきりかえて、べんきょうをはじめました。","example_meaning":"Tôi đổi tâm trạng rồi bắt đầu học."}]}],"level":"n3"},
{"word":"慣れる・慣らす","reading":"なれる・ならす","pair":[{"word":"慣れる","reading":"なれる","meaning":"quen với (tự nhiên) [自動詞]","notes":["Chủ thể tự trở nên quen → 仕事に慣れる."],"examples":[{"example":"新しい仕事に、やっと慣れました。","example_reading":"あたらしいしごとに、やっとなれました。","example_meaning":"Cuối cùng tôi cũng quen với công việc mới."},{"example":"日本の生活には、もう慣れましたか。","example_reading":"にほんのせいかつには、もうなれましたか。","example_meaning":"Bạn đã quen với cuộc sống ở Nhật chưa?"}]},{"word":"慣らす","reading":"ならす","meaning":"tập cho quen (có tác động) [他動詞]","notes":["Có người chủ động tập cho quen → 体を慣らす."],"examples":[{"example":"彼は馬を人に慣らしました。","example_reading":"かれはうまをひとにならしました。","example_meaning":"Anh ấy đã tập cho con ngựa quen với con người."},{"example":"新しい靴は、少しずつ足に慣らして履きます。","example_reading":"あたらしいくつは、すこしずつあしにならしてはきます。","example_meaning":"Giày mới thì tôi đi dần cho quen chân."}]}],"level":"n3"},
{"word":"脱げる・脱ぐ","reading":"ぬげる・ぬぐ","pair":[{"word":"脱げる","reading":"ぬげる","meaning":"bị tuột ra (tự nhiên) [自動詞]","notes":["Giày/mũ tự tuột ra → 靴が脱げる."],"examples":[{"example":"走ったとき、靴が脱げました。","example_reading":"はしったとき、くつがぬげました。","example_meaning":"Lúc chạy, giày tôi bị tuột ra."},{"example":"風で帽子が脱げてしまいました。","example_reading":"かぜでぼうしがぬげてしまいました。","example_meaning":"Mũ bị gió thổi bay mất rồi."}]},{"word":"脱ぐ","reading":"ぬぐ","meaning":"cởi ra (có tác động) [他動詞]","notes":["Có người chủ động cởi → 靴を脱ぐ."],"examples":[{"example":"家に入る前に、靴を脱いでください。","example_reading":"いえにはいるまえに、くつをぬいでください。","example_meaning":"Trước khi vào nhà hãy cởi giày."},{"example":"暑いので、上着を脱ぎました。","example_reading":"あついので、うわぎをぬぎました。","example_meaning":"Nóng quá nên tôi cởi áo khoác."}]}],"level":"n3"},
{"word":"剥ける・剥く","reading":"むける・むく","pair":[{"word":"剥ける","reading":"むける","meaning":"bị bong ra, bóc ra (tự nhiên) [自動詞]","notes":["Lớp vỏ/da tự bong ra → 皮が剥ける."],"examples":[{"example":"日焼けして、背中の皮が剥けました。","example_reading":"ひやけして、せなかのかわがむけました。","example_meaning":"Bị cháy nắng nên da lưng bong ra."},{"example":"この果物は、皮が簡単に剥けます。","example_reading":"このくだものは、かわがかんたんにむけます。","example_meaning":"Trái này vỏ bóc rất dễ."}]},{"word":"剥く","reading":"むく","meaning":"gọt, bóc (có tác động) [他動詞]","notes":["Có người chủ động gọt/bóc → 皮を剥く."],"examples":[{"example":"母はりんごの皮を剥きました。","example_reading":"はははりんごのかわをむきました。","example_meaning":"Mẹ đã gọt vỏ táo."},{"example":"私は、みかんを剥いて、食べました。","example_reading":"わたしは、みかんをむいて、たべました。","example_meaning":"Tôi bóc quýt rồi ăn."}]}],"level":"n3"},
{"word":"退く・退ける","reading":"どく・どける","pair":[{"word":"退く","reading":"どく","meaning":"tránh ra, nhường chỗ (tự nhiên) [自動詞]","notes":["Chủ thể tự tránh sang bên → そこから退く."],"examples":[{"example":"救急車が来たので、車が道の端に退きました。","example_reading":"きゅうきゅうしゃがきたので、くるまがみちのはしにどきました。","example_meaning":"Xe cứu thương đến nên xe cộ tránh sang mép đường."},{"example":"邪魔なので、そこから退いてください。","example_reading":"じゃまなので、そこからどいてください。","example_meaning":"Cản đường nên xin hãy tránh ra khỏi đó."}]},{"word":"退ける","reading":"どける","meaning":"dời đi, di chuyển ra chỗ khác (có tác động) [他動詞]","notes":["Có người chủ động dời vật đi → 物を退ける."],"examples":[{"example":"彼は道の石を退けました。","example_reading":"かれはみちのいしをどけました。","example_meaning":"Anh ấy đã dời hòn đá trên đường."},{"example":"机を退けて、掃除をしました。","example_reading":"つくえをどけて、そうじをしました。","example_meaning":"Tôi dời cái bàn ra rồi lau dọn."}]}],"level":"n3"},
{"word":"零れる・零す","reading":"こぼれる・こぼす","pair":[{"word":"零れる","reading":"こぼれる","meaning":"bị đổ, trào ra (tự nhiên) [自動詞]","notes":["Chất lỏng/hạt tự đổ ra → 水が零れる."],"examples":[{"example":"牛乳がテーブルに零れました。","example_reading":"ぎゅうにゅうがてーぶるにこぼれました。","example_meaning":"Sữa đã đổ ra bàn."},{"example":"嬉しくて、涙が零れました。","example_reading":"うれしくて、なみだがこぼれました。","example_meaning":"Vui quá nên nước mắt trào ra."}]},{"word":"零す","reading":"こぼす","meaning":"làm đổ, làm rơi vãi (có tác động) [他動詞]","notes":["Có người làm đổ (thường vô ý) → コーヒーを零す."],"examples":[{"example":"彼はコーヒーを零してしまいました。","example_reading":"かれはこーひーをこぼしてしまいました。","example_meaning":"Anh ấy lỡ làm đổ cà phê."},{"example":"子供がご飯を零しながら、食べています。","example_reading":"こどもがごはんをこぼしながら、たべています。","example_meaning":"Đứa trẻ vừa ăn vừa làm rơi vãi cơm."}]}],"level":"n3"},
{"word":"漏れる・漏らす","reading":"もれる・もらす","pair":[{"word":"漏れる","reading":"もれる","meaning":"rò rỉ, bị lộ (tự nhiên) [自動詞]","notes":["Chất lỏng/thông tin tự rò rỉ → 秘密が漏れる."],"examples":[{"example":"水道から、水が漏れています。","example_reading":"すいどうから、みずがもれています。","example_meaning":"Nước đang rò rỉ từ vòi."},{"example":"秘密が、外に漏れてしまいました。","example_reading":"ひみつが、そとにもれてしまいました。","example_meaning":"Bí mật đã bị lộ ra ngoài."}]},{"word":"漏らす","reading":"もらす","meaning":"để lộ ra, làm rò rỉ (có tác động) [他動詞]","notes":["Có người chủ động/vô ý để lộ → 秘密を漏らす."],"examples":[{"example":"彼はうっかり、秘密を漏らしました。","example_reading":"かれはうっかり、ひみつをもらしました。","example_meaning":"Anh ấy đã lỡ để lộ bí mật."},{"example":"彼女はため息を漏らして、窓の外を見ました。","example_reading":"かのじょはためいきをもらして、まどのそとをみました。","example_meaning":"Cô ấy thở dài rồi nhìn ra ngoài cửa sổ."}]}],"level":"n3"},
{"word":"垂れる・垂らす","reading":"たれる・たらす","pair":[{"word":"垂れる","reading":"たれる","meaning":"rủ xuống, nhỏ giọt (tự nhiên) [自動詞]","notes":["Chất lỏng/vật tự rủ xuống → 汗が垂れる."],"examples":[{"example":"屋根から、雨の水が垂れています。","example_reading":"やねから、あめのみずがたれています。","example_meaning":"Nước mưa đang nhỏ giọt từ mái nhà."},{"example":"汗が、顔から垂れました。","example_reading":"あせが、かおからたれました。","example_meaning":"Mồ hôi nhỏ xuống từ mặt."}]},{"word":"垂らす","reading":"たらす","meaning":"nhỏ xuống, thả xuống (có tác động) [他動詞]","notes":["Có người chủ động nhỏ/thả xuống → 糸を垂らす."],"examples":[{"example":"彼はパンにはちみつを垂らしました。","example_reading":"かれはぱんにはちみつをたらしました。","example_meaning":"Anh ấy nhỏ mật ong lên bánh mì."},{"example":"私は魚釣りで、糸を水に垂らしました。","example_reading":"わたしはさかなつりで、いとをみずにたらしました。","example_meaning":"Khi câu cá, tôi thả dây câu xuống nước."}]}],"level":"n3"},
{"word":"刺さる・刺す","reading":"ささる・さす","pair":[{"word":"刺さる","reading":"ささる","meaning":"bị đâm vào, cắm vào (tự nhiên) [自動詞]","notes":["Vật nhọn tự đâm vào → とげが刺さる."],"examples":[{"example":"足に、とげが刺さりました。","example_reading":"あしに、とげがささりました。","example_meaning":"Cái gai đã đâm vào chân."},{"example":"指に、針が刺さって、痛いです。","example_reading":"ゆびに、はりがささって、いたいです。","example_meaning":"Kim đâm vào ngón tay nên đau."}]},{"word":"刺す","reading":"さす","meaning":"đâm, chích, xiên (có tác động) [他動詞]","notes":["Có người/vật chủ động đâm/chích → 針を刺す."],"examples":[{"example":"蜂が私の腕を刺しました。","example_reading":"はちがわたしのうでをさしました。","example_meaning":"Con ong đã chích vào tay tôi."},{"example":"彼はフォークで、肉を刺して食べました。","example_reading":"かれはふぉーくで、にくをさしてたべました。","example_meaning":"Anh ấy xiên thịt bằng nĩa rồi ăn."}]}],"level":"n3"},
{"word":"挟まる・挟む","reading":"はさまる・はさむ","pair":[{"word":"挟まる","reading":"はさまる","meaning":"bị kẹt vào giữa (tự nhiên) [自動詞]","notes":["Vật tự bị kẹt giữa hai vật → ドアに挟まる."],"examples":[{"example":"ドアに、指が挟まりました。","example_reading":"どあに、ゆびがはさまりました。","example_meaning":"Ngón tay bị kẹt vào cửa."},{"example":"歯の間に、食べ物が挟まっています。","example_reading":"はのあいだに、たべものがはさまっています。","example_meaning":"Thức ăn đang bị kẹt giữa kẽ răng."}]},{"word":"挟む","reading":"はさむ","meaning":"kẹp vào giữa (có tác động) [他動詞]","notes":["Có người chủ động kẹp vào → 本に挟む."],"examples":[{"example":"彼は本にしおりを挟みました。","example_reading":"かれはほんにしおりをはさみました。","example_meaning":"Anh ấy kẹp bookmark vào sách."},{"example":"パンに、ハムと野菜を挟んで食べます。","example_reading":"ぱんに、はむとやさいをはさんでたべます。","example_meaning":"Tôi kẹp giăm bông và rau vào bánh mì rồi ăn."}]}],"level":"n3"},
{"word":"足りる・足す","reading":"たりる・たす","pair":[{"word":"足りる","reading":"たりる","meaning":"đủ (tự nhiên) [自動詞]","notes":["Số lượng tự đủ → お金が足りる."],"examples":[{"example":"お金が足りなくて、買えませんでした。","example_reading":"おかねがたりなくて、かえませんでした。","example_meaning":"Không đủ tiền nên tôi không mua được."},{"example":"材料は、これで足ります。","example_reading":"ざいりょうは、これでたります。","example_meaning":"Nguyên liệu chỉ cần chừng này là đủ."}]},{"word":"足す","reading":"たす","meaning":"cộng thêm, bổ sung (có tác động) [他動詞]","notes":["Có người chủ động thêm vào → 塩を足す."],"examples":[{"example":"彼は料理に塩を足しました。","example_reading":"かれはりょうりにしおをたしました。","example_meaning":"Anh ấy cho thêm muối vào món ăn."},{"example":"二つの数を足すと、十になります。","example_reading":"ふたつのかずをたすと、じゅうになります。","example_meaning":"Cộng hai số lại sẽ thành mười."}]}],"level":"n3"},
{"word":"尽きる・尽くす","reading":"つきる・つくす","pair":[{"word":"尽きる","reading":"つきる","meaning":"cạn kiệt, hết sạch (tự nhiên) [自動詞]","notes":["Vật tự cạn hết → お金が尽きる."],"examples":[{"example":"長い旅で、お金が尽きてしまいました。","example_reading":"ながいたびで、おかねがつきてしまいました。","example_meaning":"Sau chuyến đi dài, tiền đã cạn sạch."},{"example":"話が尽きなくて、朝まで話しました。","example_reading":"はなしがつきなくて、あさまではなしました。","example_meaning":"Chuyện không dứt nên chúng tôi nói chuyện đến sáng."}]},{"word":"尽くす","reading":"つくす","meaning":"dốc hết, tận tụy (có tác động) [他動詞]","notes":["Có người chủ động dốc hết sức → 力を尽くす."],"examples":[{"example":"彼は最後まで、全力を尽くしました。","example_reading":"かれはさいごまで、ぜんりょくをつくしました。","example_meaning":"Anh ấy đã dốc toàn lực đến cuối cùng."},{"example":"彼は、チームのために力を尽くしました。","example_reading":"かれは、ちーむのためにちからをつくしました。","example_meaning":"Anh ấy đã hết lòng vì đội."}]}],"level":"n3"},
{"word":"済む・済ます","reading":"すむ・すます","pair":[{"word":"済む","reading":"すむ","meaning":"xong, kết thúc (tự nhiên) [自動詞]","notes":["Việc tự xong → 用事が済む."],"examples":[{"example":"宿題が済んだら、遊びに行ってもいいです。","example_reading":"しゅくだいがすんだら、あそびにいってもいいです。","example_meaning":"Làm xong bài tập thì được đi chơi."},{"example":"手続きは、五分で済みました。","example_reading":"てつづきは、ごふんですみました。","example_meaning":"Thủ tục đã xong trong 5 phút."}]},{"word":"済ます","reading":"すます","meaning":"làm cho xong, giải quyết (có tác động) [他動詞]","notes":["Có người chủ động làm cho xong → 食事を済ます."],"examples":[{"example":"私は朝ご飯を簡単に済ましました。","example_reading":"わたしはあさごはんをかんたんにすましました。","example_meaning":"Tôi đã ăn sáng qua loa cho xong."},{"example":"彼は電話で、用事を済ましました。","example_reading":"かれはでんわで、ようじをすましました。","example_meaning":"Anh ấy đã giải quyết việc qua điện thoại."}]}],"level":"n3"},
{"word":"似る・似せる","reading":"にる・にせる","pair":[{"word":"似る","reading":"にる","meaning":"giống (tự nhiên) [自動詞]","notes":["Chủ thể tự giống đối tượng → 母に似る."],"examples":[{"example":"彼女は、お母さんによく似ています。","example_reading":"かのじょは、おかあさんによくにています。","example_meaning":"Cô ấy rất giống mẹ."},{"example":"兄弟だから、声が似ています。","example_reading":"きょうだいだから、こえがにています。","example_meaning":"Vì là anh em nên giọng nói giống nhau."}]},{"word":"似せる","reading":"にせる","meaning":"làm cho giống, bắt chước (có tác động) [他動詞]","notes":["Có người chủ động làm cho giống → 本物に似せる."],"examples":[{"example":"彼は有名人の声に似せて、話しました。","example_reading":"かれはゆうめいじんのこえににせて、はなしました。","example_meaning":"Anh ấy nói bắt chước giọng người nổi tiếng."},{"example":"画家は、本物に似せて、絵を描きました。","example_reading":"がかは、ほんものににせて、えをかきました。","example_meaning":"Họa sĩ vẽ tranh sao cho giống bản thật."}]}],"level":"n3"},
{"word":"分かれる・分ける","reading":"わかれる・わける","pair":[{"word":"分かれる","reading":"わかれる","meaning":"chia ra, tách ra (tự nhiên) [自動詞]","notes":["Vật tự chia tách → 道が分かれる."],"examples":[{"example":"道が、ここで二つに分かれています。","example_reading":"みちが、ここでふたつにわかれています。","example_meaning":"Con đường chia làm hai ngả ở đây."},{"example":"意見が、二つに分かれました。","example_reading":"いけんが、ふたつにわかれました。","example_meaning":"Ý kiến chia thành hai phía."}]},{"word":"分ける","reading":"わける","meaning":"chia, phân loại (có tác động) [他動詞]","notes":["Có người chủ động chia/phân loại → ケーキを分ける."],"examples":[{"example":"母はケーキを四つに分けました。","example_reading":"はははけーきをよっつにわけました。","example_meaning":"Mẹ đã chia bánh làm bốn phần."},{"example":"ごみは、種類ごとに分けて捨てます。","example_reading":"ごみは、しゅるいごとにわけてすてます。","example_meaning":"Rác được phân loại theo từng loại rồi bỏ."}]}],"level":"n3"},
{"word":"離れる・離す","reading":"はなれる・はなす","pair":[{"word":"離れる","reading":"はなれる","meaning":"rời xa, cách xa (tự nhiên) [自動詞]","notes":["Chủ thể tự rời xa → 家を離れる."],"examples":[{"example":"家を離れて、一人で暮らしています。","example_reading":"いえをはなれて、ひとりでくらしています。","example_meaning":"Tôi rời nhà và sống một mình."},{"example":"駅から、少し離れたところに住んでいます。","example_reading":"えきから、すこしはなれたところにすんでいます。","example_meaning":"Tôi sống ở chỗ hơi xa nhà ga."}]},{"word":"離す","reading":"はなす","meaning":"buông ra, tách ra (có tác động) [他動詞]","notes":["Có người chủ động buông/tách ra → 手を離す."],"examples":[{"example":"彼は手を離しました。","example_reading":"かれはてをはなしました。","example_meaning":"Anh ấy đã buông tay ra."},{"example":"小さい子供から、目を離さないでください。","example_reading":"ちいさいこどもから、めをはなさないでください。","example_meaning":"Xin đừng rời mắt khỏi trẻ nhỏ."}]}],"level":"n3"},
{"word":"近づく・近づける","reading":"ちかづく・ちかづける","pair":[{"word":"近づく","reading":"ちかづく","meaning":"đến gần (tự nhiên) [自動詞]","notes":["Chủ thể tự tiến lại gần → 台風が近づく."],"examples":[{"example":"台風が、日本に近づいています。","example_reading":"たいふうが、にほんにちかづいています。","example_meaning":"Bão đang tiến gần đến Nhật Bản."},{"example":"試験の日が、近づいてきました。","example_reading":"しけんのひが、ちかづいてきました。","example_meaning":"Ngày thi đã đến gần."}]},{"word":"近づける","reading":"ちかづける","meaning":"đưa lại gần (có tác động) [他動詞]","notes":["Có người chủ động đưa lại gần → 椅子を近づける."],"examples":[{"example":"彼は椅子をテーブルに近づけました。","example_reading":"かれはいすをてーぶるにちかづけました。","example_meaning":"Anh ấy kéo ghế lại gần bàn."},{"example":"犬を危ないものに近づけないでください。","example_reading":"いぬをあぶないものにちかづけないでください。","example_meaning":"Xin đừng để chó lại gần những thứ nguy hiểm."}]}],"level":"n3"},
{"word":"遠ざかる・遠ざける","reading":"とおざかる・とおざける","pair":[{"word":"遠ざかる","reading":"とおざかる","meaning":"xa dần (tự nhiên) [自動詞]","notes":["Chủ thể tự xa dần → 音が遠ざかる."],"examples":[{"example":"車の音が、だんだん遠ざかっていきます。","example_reading":"くるまのおとが、だんだんとおざかっていきます。","example_meaning":"Tiếng xe xa dần."},{"example":"船が、岸から遠ざかりました。","example_reading":"ふねが、きしからとおざかりました。","example_meaning":"Con thuyền đã rời xa bờ."}]},{"word":"遠ざける","reading":"とおざける","meaning":"giữ cho tránh xa, xa lánh (có tác động) [他動詞]","notes":["Có người chủ động giữ cho tránh xa → 危険を遠ざける."],"examples":[{"example":"母は子供を、危険なものから遠ざけました。","example_reading":"はははこどもを、きけんなものからとおざけました。","example_meaning":"Mẹ giữ con tránh xa những thứ nguy hiểm."},{"example":"医者に、お酒を遠ざけるように言われました。","example_reading":"いしゃに、おさけをとおざけるようにいわれました。","example_meaning":"Bác sĩ dặn tôi tránh xa rượu."}]}],"level":"n3"},
{"word":"寄る・寄せる","reading":"よる・よせる","pair":[{"word":"寄る","reading":"よる","meaning":"ghé qua, xúm lại (tự nhiên) [自動詞]","notes":["Chủ thể tự ghé/xúm lại → 店に寄る."],"examples":[{"example":"帰りに、本屋に寄りました。","example_reading":"かえりに、ほんやによりました。","example_meaning":"Trên đường về tôi đã ghé hiệu sách."},{"example":"みんなが、彼のまわりに寄ってきました。","example_reading":"みんなが、かれのまわりによってきました。","example_meaning":"Mọi người xúm lại quanh anh ấy."}]},{"word":"寄せる","reading":"よせる","meaning":"dồn sát vào, đẩy lại gần (có tác động) [他動詞]","notes":["Có người chủ động đẩy lại gần → 机を寄せる."],"examples":[{"example":"彼は机を壁に寄せました。","example_reading":"かれはつくえをかべによせました。","example_meaning":"Anh ấy đẩy cái bàn sát vào tường."},{"example":"運転手は、車を道の端に寄せました。","example_reading":"うんてんしゅは、くるまをみちのはしによせました。","example_meaning":"Tài xế đã tấp xe vào lề đường."}]}],"level":"n3"},
{"word":"預かる・預ける","reading":"あずかる・あずける","pair":[{"word":"預かる","reading":"あずかる","meaning":"nhận giữ, trông giúp (tự nhiên) [自動詞]","notes":["Phía nhận giữ đồ/trông giúp → 荷物を預かる."],"examples":[{"example":"友達の犬を、一週間預かりました。","example_reading":"ともだちのいぬを、いっしゅうかんあずかりました。","example_meaning":"Tôi đã trông giúp con chó của bạn một tuần."},{"example":"荷物は、受付で預かります。","example_reading":"にもつは、うけつけであずかります。","example_meaning":"Hành lý sẽ được giữ ở quầy lễ tân."}]},{"word":"預ける","reading":"あずける","meaning":"gửi, giao cho giữ (có tác động) [他動詞]","notes":["Phía gửi đồ/giao cho người khác → 荷物を預ける."],"examples":[{"example":"私は荷物を、駅のロッカーに預けました。","example_reading":"わたしはにもつを、えきのろっかーにあずけました。","example_meaning":"Tôi đã gửi hành lý vào tủ khóa ở nhà ga."},{"example":"出かけるとき、子供を祖母に預けました。","example_reading":"でかけるとき、こどもをそぼにあずけました。","example_meaning":"Khi ra ngoài tôi gửi con cho bà."}]}],"level":"n3"},
{"word":"売れる・売る","reading":"うれる・うる","pair":[{"word":"売れる","reading":"うれる","meaning":"bán chạy, bán được (tự nhiên) [自動詞]","notes":["Hàng hóa tự bán được → 本が売れる."],"examples":[{"example":"この本は、よく売れています。","example_reading":"このほんは、よくうれています。","example_meaning":"Cuốn sách này bán rất chạy."},{"example":"新しい商品は、すぐに売れてしまいました。","example_reading":"あたらしいしょうひんは、すぐにうれてしまいました。","example_meaning":"Sản phẩm mới đã bán hết ngay."}]},{"word":"売る","reading":"うる","meaning":"bán (có tác động) [他動詞]","notes":["Có người chủ động bán → 車を売る."],"examples":[{"example":"彼は古い車を売りました。","example_reading":"かれはふるいくるまをうりました。","example_meaning":"Anh ấy đã bán chiếc xe cũ."},{"example":"この店では、新鮮な魚を売っています。","example_reading":"このみせでは、しんせんなさかなをうっています。","example_meaning":"Cửa hàng này bán cá tươi."}]}],"level":"n3"},
{"word":"釣れる・釣る","reading":"つれる・つる","pair":[{"word":"釣れる","reading":"つれる","meaning":"câu được (tự nhiên) [自動詞]","notes":["Cá tự câu được, chú ý kết quả → 魚が釣れる."],"examples":[{"example":"今日は、魚がよく釣れました。","example_reading":"きょうは、さかながよくつれました。","example_meaning":"Hôm nay câu được nhiều cá."},{"example":"この川では、大きな魚が釣れます。","example_reading":"このかわでは、おおきなさかながつれます。","example_meaning":"Ở con sông này câu được cá lớn."}]},{"word":"釣る","reading":"つる","meaning":"câu (cá) (có tác động) [他動詞]","notes":["Có người chủ động câu → 魚を釣る."],"examples":[{"example":"父は川で、魚を釣りました。","example_reading":"ちちはかわで、さかなをつりました。","example_meaning":"Bố câu cá ở sông."},{"example":"日曜日に、海で魚を釣るのが好きです。","example_reading":"にちようびに、うみでさかなをつるのがすきです。","example_meaning":"Tôi thích câu cá ở biển vào Chủ nhật."}]}],"level":"n3"},
{"word":"捕まる・捕まえる","reading":"つかまる・つかまえる","pair":[{"word":"捕まる","reading":"つかまる","meaning":"bị bắt, bị túm (tự nhiên) [自動詞]","notes":["Đối tượng bị bắt, chú ý kết quả → 泥棒が捕まる."],"examples":[{"example":"泥棒が、警察に捕まりました。","example_reading":"どろぼうが、けいさつにつかまりました。","example_meaning":"Tên trộm đã bị cảnh sát bắt."},{"example":"逃げた猫が、やっと捕まりました。","example_reading":"にげたねこが、やっとつかまりました。","example_meaning":"Con mèo bỏ chạy cuối cùng cũng bị bắt lại."}]},{"word":"捕まえる","reading":"つかまえる","meaning":"bắt, tóm (có tác động) [他動詞]","notes":["Có người chủ động bắt → 犯人を捕まえる."],"examples":[{"example":"警察は、泥棒を捕まえました。","example_reading":"けいさつは、どろぼうをつかまえました。","example_meaning":"Cảnh sát đã bắt tên trộm."},{"example":"子供は、虫取り網で、蝶を捕まえました。","example_reading":"こどもは、むしとりあみで、ちょうをつかまえました。","example_meaning":"Đứa trẻ bắt bướm bằng lưới bắt côn trùng."}]}],"level":"n3"},
{"word":"加わる・加える","reading":"くわわる・くわえる","pair":[{"word":"加わる","reading":"くわわる","meaning":"tham gia, được thêm vào (tự nhiên) [自動詞]","notes":["Chủ thể tự gia nhập/được thêm vào → チームに加わる."],"examples":[{"example":"新しいメンバーが、チームに加わりました。","example_reading":"あたらしいめんばーが、ちーむにくわわりました。","example_meaning":"Thành viên mới đã gia nhập đội."},{"example":"今年は、新しい授業が加わりました。","example_reading":"ことしは、あたらしいじゅぎょうがくわわりました。","example_meaning":"Năm nay có thêm môn học mới."}]},{"word":"加える","reading":"くわえる","meaning":"thêm vào, bổ sung (có tác động) [他動詞]","notes":["Có người chủ động thêm vào → 塩を加える."],"examples":[{"example":"母は、スープに塩を加えました。","example_reading":"はははすーぷにしおをくわえました。","example_meaning":"Mẹ đã cho thêm muối vào súp."},{"example":"彼は、計画に新しい意見を加えました。","example_reading":"かれは、けいかくにあたらしいいけんをくわえました。","example_meaning":"Anh ấy đã bổ sung ý kiến mới vào kế hoạch."}]}],"level":"n3"},
{"word":"備わる・備える","reading":"そなわる・そなえる","pair":[{"word":"備わる","reading":"そなわる","meaning":"được trang bị sẵn, vốn có (tự nhiên) [自動詞]","notes":["Vật/người có sẵn thiết bị hoặc khả năng → 力が備わる."],"examples":[{"example":"この部屋には、エアコンが備わっています。","example_reading":"このへやには、えあこんがそなわっています。","example_meaning":"Phòng này được trang bị sẵn điều hòa."},{"example":"彼には、リーダーとしての力が備わっています。","example_reading":"かれには、りーだーとしてのちからがそなわっています。","example_meaning":"Anh ấy có sẵn năng lực của một người lãnh đạo."}]},{"word":"備える","reading":"そなえる","meaning":"chuẩn bị, trang bị (có tác động) [他動詞]","notes":["Có người chủ động chuẩn bị/trang bị → 地震に備える."],"examples":[{"example":"学校は、地震に備えて、水を用意しました。","example_reading":"がっこうは、じしんにそなえて、みずをよういしました。","example_meaning":"Trường học đã chuẩn bị nước để phòng khi động đất."},{"example":"会社は、各部屋にエアコンを備えました。","example_reading":"かいしゃは、かくへやにえあこんをそなえました。","example_meaning":"Công ty đã lắp điều hòa cho từng phòng."}]}],"level":"n3"},
{"word":"くっつく・くっつける","reading":"くっつく・くっつける","pair":[{"word":"くっつく","reading":"くっつく","meaning":"dính vào, bám vào (tự nhiên) [自動詞]","notes":["Vật tự dính vào nhau → ガムがくっつく."],"examples":[{"example":"ガムが靴の裏にくっつきました。","example_reading":"がむがくつのうらにくっつきました。","example_meaning":"Kẹo cao su đã dính vào đế giày."},{"example":"二つの磁石が、くっついています。","example_reading":"ふたつのじしゃくが、くっついています。","example_meaning":"Hai cục nam châm đang dính vào nhau."}]},{"word":"くっつける","reading":"くっつける","meaning":"dán vào, gắn vào (có tác động) [他動詞]","notes":["Có người chủ động dán/gắn → 紙をくっつける."],"examples":[{"example":"私は、のりで紙と紙をくっつけました。","example_reading":"わたしは、のりでかみとかみをくっつけました。","example_meaning":"Tôi dán hai tờ giấy lại bằng hồ."},{"example":"壊れたお皿を、接着剤でくっつけました。","example_reading":"こわれたおさらを、せっちゃくざいでくっつけました。","example_meaning":"Tôi gắn lại cái đĩa vỡ bằng keo."}]}],"level":"n3"},
{"word":"狂う・狂わす","reading":"くるう・くるわす","pair":[{"word":"狂う","reading":"くるう","meaning":"bị lệch, hỏng, điên (tự nhiên) [自動詞]","notes":["Vật tự bị sai lệch → 予定が狂う."],"examples":[{"example":"時計が狂って、約束に遅れました。","example_reading":"とけいがくるって、やくそくにおくれました。","example_meaning":"Đồng hồ chạy sai nên tôi trễ hẹn."},{"example":"雨で、予定が狂ってしまいました。","example_reading":"あめで、よていがくるってしまいました。","example_meaning":"Vì mưa nên kế hoạch bị đảo lộn."}]},{"word":"狂わす","reading":"くるわす","meaning":"làm sai lệch, làm đảo lộn (có tác động) [他動詞]","notes":["Có người/vật làm lệch kế hoạch → 計画を狂わす."],"examples":[{"example":"台風が、旅行の計画を狂わしました。","example_reading":"たいふうが、りょこうのけいかくをくるわしました。","example_meaning":"Cơn bão đã làm đảo lộn kế hoạch du lịch."},{"example":"夜更かしは、生活のリズムを狂わします。","example_reading":"よふかしは、せいかつのりずむをくるわします。","example_meaning":"Thức khuya làm rối loạn nhịp sống."}]}],"level":"n3"},
{"word":"痛む・痛める","reading":"いたむ・いためる","pair":[{"word":"痛む","reading":"いたむ","meaning":"đau, nhức (tự nhiên) [自動詞]","notes":["Bộ phận cơ thể tự đau → 足が痛む."],"examples":[{"example":"転んだ足が、まだ痛みます。","example_reading":"ころんだあしが、まだいたみます。","example_meaning":"Chân bị ngã vẫn còn đau."},{"example":"歯が痛んで、よく眠れませんでした。","example_reading":"はがいたんで、よくねむれませんでした。","example_meaning":"Răng đau nên tôi ngủ không ngon."}]},{"word":"痛める","reading":"いためる","meaning":"làm đau, làm tổn thương (có tác động) [他動詞]","notes":["Có người/việc chủ động làm đau → 足を痛める."],"examples":[{"example":"彼は走りすぎて、足を痛めました。","example_reading":"かれははしりすぎて、あしをいためました。","example_meaning":"Anh ấy chạy quá nhiều nên bị đau chân."},{"example":"私は事故で、腰を痛めました。","example_reading":"わたしはじこで、こしをいためました。","example_meaning":"Tôi bị đau lưng do tai nạn."}]}],"level":"n3"},
{"word":"凹む・凹ます","reading":"へこむ・へこます","pair":[{"word":"凹む","reading":"へこむ","meaning":"bị lõm, bị móp (tự nhiên) [自動詞]","notes":["Vật tự bị lõm xuống → 車が凹む."],"examples":[{"example":"ボールが当たって、缶が凹みました。","example_reading":"ぼーるがあたって、かんがへこみました。","example_meaning":"Bóng trúng làm cái lon bị móp."},{"example":"ドアが凹んでいます。","example_reading":"どあがへこんでいます。","example_meaning":"Cánh cửa đang bị lõm."}]},{"word":"凹ます","reading":"へこます","meaning":"làm lõm, làm móp (có tác động) [他動詞]","notes":["Có người chủ động làm lõm → 缶を凹ます."],"examples":[{"example":"彼は車をぶつけて、ドアを凹ましました。","example_reading":"かれはくるまをぶつけて、どあをへこましました。","example_meaning":"Anh ấy đâm xe làm móp cửa."},{"example":"子供が、空き缶を足で凹ましました。","example_reading":"こどもが、あきかんをあしでへこましました。","example_meaning":"Đứa trẻ giẫm cho cái lon rỗng bị móp."}]}],"level":"n3"},
{"word":"覆る・覆す","reading":"くつがえる・くつがえす","pair":[{"word":"覆る","reading":"くつがえる","meaning":"bị lật ngược, bị đảo ngược (tự nhiên) [自動詞]","notes":["Tình thế/phán quyết tự bị đảo ngược → 判決が覆る."],"examples":[{"example":"裁判の結果が、覆りました。","example_reading":"さいばんのけっかが、くつがえりました。","example_meaning":"Kết quả phiên tòa đã bị đảo ngược."},{"example":"ボートが波で覆りました。","example_reading":"ぼーとがなみでくつがえりました。","example_meaning":"Chiếc thuyền bị sóng lật úp."}]},{"word":"覆す","reading":"くつがえす","meaning":"lật ngược, đảo ngược (có tác động) [他動詞]","notes":["Có người chủ động lật ngược → 決定を覆す."],"examples":[{"example":"会社は、前の決定を覆しました。","example_reading":"かいしゃは、まえのけっていをくつがえしました。","example_meaning":"Công ty đã đảo ngược quyết định trước."},{"example":"彼は新しい証拠で、結論を覆しました。","example_reading":"かれはあたらしいしょうこで、けつろんをくつがえしました。","example_meaning":"Anh ấy dùng bằng chứng mới để lật ngược kết luận."}]}],"level":"n3"},
{"word":"滅びる・滅ぼす","reading":"ほろびる・ほろぼす","pair":[{"word":"滅びる","reading":"ほろびる","meaning":"diệt vong, sụp đổ (tự nhiên) [自動詞]","notes":["Chủ thể tự diệt vong → 国が滅びる."],"examples":[{"example":"昔、この国は戦争で滅びました。","example_reading":"むかし、このくには、せんそうでほろびました。","example_meaning":"Ngày xưa đất nước này đã sụp đổ vì chiến tranh."},{"example":"恐竜は、遠い昔に滅びました。","example_reading":"きょうりゅうは、とおいむかしにほろびました。","example_meaning":"Khủng long đã tuyệt chủng từ rất lâu rồi."}]},{"word":"滅ぼす","reading":"ほろぼす","meaning":"tiêu diệt, làm sụp đổ (có tác động) [他動詞]","notes":["Có người chủ động tiêu diệt → 敵を滅ぼす."],"examples":[{"example":"王は、敵の国を滅ぼしました。","example_reading":"おうは、てきのくにをほろぼしました。","example_meaning":"Nhà vua đã tiêu diệt nước địch."},{"example":"飲みすぎは、体を滅ぼします。","example_reading":"のみすぎは、からだをほろぼします。","example_meaning":"Uống quá nhiều sẽ hủy hoại cơ thể."}]}],"level":"n3"},
{"word":"酔う・酔わせる","reading":"よう・よわせる","pair":[{"word":"酔う","reading":"よう","meaning":"say (tự nhiên) [自動詞]","notes":["Chủ thể tự bị say → お酒に酔う."],"examples":[{"example":"彼は、お酒に酔って、寝てしまいました。","example_reading":"かれは、おさけによって、ねてしまいました。","example_meaning":"Anh ấy say rượu rồi ngủ mất."},{"example":"私は、船に酔いやすいです。","example_reading":"わたしは、ふねによいやすいです。","example_meaning":"Tôi dễ bị say tàu."}]},{"word":"酔わせる","reading":"よわせる","meaning":"làm cho say, làm mê mẩn (có tác động) [他動詞]","notes":["Có người/vật làm ai đó say → 人を酔わせる. Dạng sai khiến của 酔う."],"examples":[{"example":"彼は、友達を酔わせて、本音を聞きました。","example_reading":"かれは、ともだちをよわせて、ほんねをききました。","example_meaning":"Anh ấy chuốc say bạn để nghe lời thật lòng."},{"example":"彼女の歌声は、聞く人を酔わせました。","example_reading":"かのじょのうたごえは、きくひとをよわせました。","example_meaning":"Giọng hát của cô ấy làm người nghe mê mẩn."}]}],"level":"n3"},
{"word":"光る・光らせる","reading":"ひかる・ひからせる","pair":[{"word":"光る","reading":"ひかる","meaning":"sáng, tỏa sáng (tự nhiên) [自動詞]","notes":["Vật tự phát sáng → 星が光る."],"examples":[{"example":"夜空に、星が光っています。","example_reading":"よぞらに、ほしがひかっています。","example_meaning":"Những vì sao đang tỏa sáng trên bầu trời đêm."},{"example":"海が、太陽の光で、きらきら光っています。","example_reading":"うみが、たいようのひかりで、きらきらひかっています。","example_meaning":"Biển lấp lánh dưới ánh mặt trời."}]},{"word":"光らせる","reading":"ひからせる","meaning":"làm cho sáng, canh chừng (có tác động) [他動詞]","notes":["Có người chủ động làm sáng → 目を光らせる. Dạng sai khiến của 光る."],"examples":[{"example":"彼は、靴をぴかぴかに光らせました。","example_reading":"かれは、くつをぴかぴかにひからせました。","example_meaning":"Anh ấy đánh giày cho bóng loáng."},{"example":"警察は、町の安全に目を光らせています。","example_reading":"けいさつは、まちのあんぜんにめをひからせています。","example_meaning":"Cảnh sát đang canh chừng an ninh của thị trấn."}]}],"level":"n3"},
{"word":"立ち上がる・立ち上げる","reading":"たちあがる・たちあげる","pair":[{"word":"立ち上がる","reading":"たちあがる","meaning":"đứng dậy, khởi động (tự nhiên) [自動詞]","notes":["Chủ thể tự đứng dậy hoặc hệ thống tự khởi động → 席から立ち上がる."],"examples":[{"example":"彼は、席から立ち上がりました。","example_reading":"かれは、せきからたちあがりました。","example_meaning":"Anh ấy đã đứng dậy khỏi chỗ."},{"example":"パソコンが、立ち上がるまで、時間がかかります。","example_reading":"ぱそこんが、たちあがるまで、じかんがかかります。","example_meaning":"Máy tính mất thời gian để khởi động."}]},{"word":"立ち上げる","reading":"たちあげる","meaning":"khởi động, thành lập (có tác động) [他動詞]","notes":["Có người chủ động khởi động/thành lập → 会社を立ち上げる."],"examples":[{"example":"彼は、パソコンを立ち上げました。","example_reading":"かれは、ぱそこんをたちあげました。","example_meaning":"Anh ấy đã khởi động máy tính."},{"example":"彼は、仲間と、新しい会社を立ち上げました。","example_reading":"かれは、なかまと、あたらしいかいしゃをたちあげました。","example_meaning":"Anh ấy cùng đồng đội thành lập một công ty mới."}]}],"level":"n3"},
{"word":"咲く・咲かせる","reading":"さく・さかせる","pair":[{"word":"咲く","reading":"さく","meaning":"nở (tự nhiên) [自動詞]","notes":["Hoa tự nở → 花が咲く."],"examples":[{"example":"春になると、桜が咲きます。","example_reading":"はるになると、さくらがさきます。","example_meaning":"Mùa xuân đến thì hoa anh đào nở."},{"example":"庭に、きれいな花が咲いています。","example_reading":"にわに、きれいなはながさいています。","example_meaning":"Trong vườn có những bông hoa đẹp đang nở."}]},{"word":"咲かせる","reading":"さかせる","meaning":"làm cho nở, làm nở rộ (có tác động) [他動詞]","notes":["Có người chủ động làm hoa nở → 花を咲かせる. Dạng sai khiến của 咲く."],"examples":[{"example":"母は、庭にたくさんの花を咲かせました。","example_reading":"はははにわにたくさんのはなをさかせました。","example_meaning":"Mẹ đã làm cho vườn nở đầy hoa."},{"example":"私たちは、昔話に花を咲かせました。","example_reading":"わたしたちは、むかしばなしにはなをさかせました。","example_meaning":"Chúng tôi trò chuyện rôm rả về chuyện ngày xưa."}]}],"level":"n3"}
],
"grammar": [
{"pattern":"主語が + 自動詞","usage":"Tự động từ: động tác/biến đổi không tác động lên đối tượng nào, chủ ngữ dùng trợ từ が","example":"ドアが開きました。","example_reading":"どあがあきました。","example_meaning":"Cửa đã mở (tự nó mở, hoặc không rõ ai mở)."},
{"pattern":"主語が + 目的語を + 他動詞","usage":"Tha động từ: có đối tượng bị tác động rõ ràng, đối tượng dùng trợ từ を","example":"彼がドアを開けました。","example_reading":"かれがどあをあけました。","example_meaning":"Anh ấy đã mở cửa (rõ ràng ai là người mở)."},
{"pattern":"Tiêu điểm câu chuyện","usage":"Nếu người nói chỉ chú ý đến SỰ THAY ĐỔI của vật → dùng tự động từ. Nếu chú ý cả NGƯỜI GÂY RA sự thay đổi → dùng tha động từ","example":"電気が付いた。／電気を付けた。","example_reading":"でんきがついた。／でんきをつけた。","example_meaning":"Đèn đã sáng (chỉ chú ý đèn sáng). / Tôi đã bật đèn (chú ý cả người bật)."},
{"pattern":"自動詞 vs. 他動詞の受身形","usage":"Tự động từ chỉ mô tả trạng thái; Tha động từ thể bị động ngụ ý CÓ AI ĐÓ đã gây ra hành động","example":"窓が割れた。／窓が割られた。","example_reading":"まどがわれた。／まどがわられた。","example_meaning":"Cửa sổ đã vỡ (chỉ mô tả). / Cửa sổ đã bị (ai đó) đập vỡ (ngụ ý có người làm)."},
{"pattern":"使役形 thay thế tha động từ","usage":"Khi tự động từ (vô ý chí) không có tha động từ tương ứng, dùng THỂ SAI KHIẾN để diễn đạt 'làm cho...'","example":"野菜が腐る → 野菜を腐らせる","example_reading":"やさいがくさる → やさいをくさらせる","example_meaning":"Rau bị hỏng → (Ai đó) làm cho rau bị hỏng."}
]
};
